export default "      operations=[\\n            {\\n                \\\"op\\\": \\\"rename_tool\\\",\\n                \\\"tool\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-1\\\"},\\n                \\\"tool_display_name\\\": \\\"Better Name\\\",\\n            },\\n        ],\\n    )\\n    plan = build_plan(agent=agent, provider_update=payload)\\n    assert plan.tool_renames == {\\\"tool-1\\\": \\\"Better Name\\\"}\\n\\n\\ndef test_build_update_plan_without_renames_has_empty_dict():\\n    \\\"\\\"\\\"build_provider_update_plan returns empty tool_renames when no renames present.\\\"\\\"\\\"\\n    build_plan = update_core_module.build_provider_update_plan\\n\\n    agent = {\\\"id\\\": \\\"agent-1\\\", \\\"tools\\\": [\\\"tool-1\\\"]}\\n    payload = WatsonxDeploymentUpdatePayload(\\n        llm=TEST_WXO_LLM,\\n        operations=[\\n            {\\n                \\\"op\\\": \\\"remove_tool\\\",\\n                \\\"tool\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-1\\\"},\\n            },\\n        ],\\n    )\\n    plan = build_plan(agent=agent, provider_update=payload)\\n    assert plan.tool_renames == {}\\n\\n\\n# ---------------------------------------------------------------------------\\n# WXO_LFX_REQUIREMENT_OVERRIDE\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_resolve_lfx_requirement_uses_override(monkeypatch):\\n    \\\"\\\"\\\"_resolve_lfx_requirement returns the env var value when set.\\\"\\\"\\\"\\n    _resolve = tools_module._resolve_lfx_requirement\\n\\n    monkeypatch.setenv(\\\"WXO_LFX_REQUIREMENT_OVERRIDE\\\", \\\"lfx-nightly==0.4.0.dev32\\\")\\n    assert _resolve() == \\\"lfx-nightly==0.4.0.dev32\\\"\\n\\n\\ndef test_resolve_lfx_requirement_ignores_blank_override(monkeypatch):\\n    \\\"\\\"\\\"_resolve_lfx_requirement ignores empty/whitespace-only override.\\\"\\\"\\\"\\n    _resolve = tools_module._resolve_lfx_requirement\\n\\n    monkeypatch.setenv(\\\"WXO_LFX_REQUIREMENT_OVERRIDE\\\", \\\"   \\\")\\n    # Should not return blank \u2014 should fall through to installed version or raise\\n    result = _resolve()\\n    assert result.strip()\\n    assert result != \\\"   \\\"\\n\\n\\ndef test_rename_tool_provider_payload_parses():\\n    \\\"\\\"\\\"WatsonxRenameToolOperation parses correctly at provider level.\\\"\\\"\\\"\\n    op = WatsonxRenameToolOperation(\\n        op=\\\"rename_tool\\\",\\n        tool={\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-1\\\"},\\n        tool_display_name=\\\"Better Name\\\",\\n    )\\n    assert op.tool_display_name == \\\"Better Name\\\"\\n    assert op.tool.tool_id == \\\"tool-1\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# DeploymentFlowVersionListItem carries provider tool names under provider_data\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_flow_version_list_item_includes_tool_names_in_provider_data():\\n    \\\"\\\"\\\"DeploymentFlowVersionListItem serializes provider tool metadata under provider_data.\\\"\\\"\\\"\\n    from langflow.api.v1.schemas.deployments import DeploymentFlowVersionListItem\\n\\n    item = DeploymentFlowVersionListItem(\\n        id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n        flow_id=\\\"00000000-0000-0000-0000-000000000002\\\",\\n        flow_name=\\\"My Flow\\\",\\n        version_number=1,\\n        provider_data={\\\"tool_name\\\": \\\"my_custom_tool\\\", \\\"tool_display_name\\\": \\\"My Custom Tool\\\"},\\n    )\\n    data = item.model_dump()\\n    assert data[\\\"provider_data\\\"][\\\"tool_name\\\"] == \\\"my_custom_tool\\\"\\n    assert data[\\\"provider_data\\\"][\\\"tool_display_name\\\"] == \\\"My Custom Tool\\\"\\n\\n\\ndef test_flow_version_list_item_provider_data_defaults_to_none():\\n    \\\"\\\"\\\"DeploymentFlowVersionListItem defaults provider_data to None.\\\"\\\"\\\"\\n    from langflow.api.v1.schemas.deployments import DeploymentFlowVersionListItem\\n\\n    item = DeploymentFlowVersionListItem(\\n        id=\\\"00000000-0000-0000-0000-000000000001\\\",\\n        flow_id=\\\"00000000-0000-0000-0000-000000000002\\\",\\n        version_number=1,\\n    )\\n    assert item.provider_data is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/deployment/test_watsonx_orchestrate_update_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9796e3bf5c64160c658daec913719e06aedb802fed6a0f3c90593d0352e2343e\",\"content\":\"\\\"\\\"\\\"Unit tests for Watsonx deployment update provider schema.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom uuid import UUID\\n\\nimport pytest\\n\\ntry:\\n    from langflow.services.adapters.deployment.watsonx_orchestrate import (\\n        WatsonxOrchestrateDeploymentService,  # noqa: F401\\n    )\\nexcept ModuleNotFoundError:\\n    pytest.skip(\\n        \\\"Skipping Watsonx deployment tests: optional IBM SDK dependencies not available.\\\",\\n        allow_module_level=True,\\n    )\\n\\nfrom langflow.services.adapters.deployment.watsonx_orchestrate.payloads import (\\n    PAYLOAD_SCHEMAS,\\n    WatsonxAgentExecutionResultData,\\n    WatsonxDeploymentCreatePayload,\\n    WatsonxDeploymentCreateResultData,\\n    WatsonxDeploymentUpdatePayload,\\n    WatsonxDeploymentUpdateResultData,\\n    WatsonxFlowArtifactProviderData,\\n)\\nfrom lfx.services.adapters.payload import AdapterPayloadValidationError\\n\\npayload_schemas = PAYLOAD_SCHEMAS\\n\\n\\ndef _raw_tool(name: str, suffix: int) -> dict:\\n    technical_name = name.replace(\\\"-\\\", \\\"_\\\")\\n    return {\\n        \\\"id\\\": str(UUID(int=suffix)),\\n        \\\"name\\\": name,\\n        \\\"description\\\": \\\"desc\\\",\\n        \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n        \\\"tags\\\": [],\\n        \\\"provider_data\\\": {\\n            \\\"project_id\\\": \\\"project-1\\\",\\n            \\\"source_ref\\\": f\\\"fv-{suffix}\\\",\\n            \\\"tool_name\\\": technical_name,\\n            \\\"tool_display_name\\\": name,\\n        },\\n    }\\n\\n\\ndef _raw_connection(app_id: str) -> dict:\\n    return {\\n        \\\"app_id\\\": app_id,\\n        \\\"environment_variables\\\": {\\n            \\\"API_KEY\\\": {\\\"source\\\": \\\"raw\\\", \\\"value\\\": \\\"secret\\\"},\\n        },\\n    }\\n\\n\\ndef test_payload_schema_slot_registered_for_deployment_update() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_create is not None\\n    assert slot.deployment_create.adapter_model is WatsonxDeploymentCreatePayload\\n    assert slot.flow_artifact is not None\\n    assert slot.flow_artifact.adapter_model is WatsonxFlowArtifactProviderData\\n    assert slot.deployment_create_result is not None\\n    assert slot.deployment_create_result.adapter_model is WatsonxDeploymentCreateResultData\\n    assert slot.deployment_update is not None\\n    assert slot.deployment_update.adapter_model is WatsonxDeploymentUpdatePayload\\n    assert slot.deployment_update_result is not None\\n    assert slot.deployment_update_result.adapter_model is WatsonxDeploymentUpdateResultData\\n    assert slot.execution_create_result is not None\\n    assert slot.execution_create_result.adapter_model is WatsonxAgentExecutionResultData\\n    assert slot.execution_status_result is not None\\n    assert slot.execution_status_result.adapter_model is WatsonxAgentExecutionResultData\\n\\n\\ndef test_update_result_schema_dedupes_id_lists() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_update_result is not None\\n\\n    applied = slot.deployment_update_result.apply(\\n        {\\n            \\\"name\\\": \\\"agent-name\\\",\\n            \\\"display_name\\\": \\\"Agent Name\\\",\\n            \\\"created_app_ids\\\": [\\\"app-1\\\", \\\"app-1\\\", \\\"app-2\\\"],\\n            \\\"created_snapshot_ids\\\": [\\\"tool-1\\\", \\\"tool-1\\\", \\\"tool-2\\\"],\\n            \\\"added_snapshot_ids\\\": [\\\"tool-1\\\", \\\"tool-2\\\", \\\"tool-1\\\"],\\n        }\\n    )\\n\\n    assert applied[\\\"created_app_ids\\\"] == [\\\"app-1\\\", \\\"app-2\\\"]\\n    assert applied[\\\"created_snapshot_ids\\\"] == [\\\"tool-1\\\", \\\"tool-2\\\"]\\n    assert applied[\\\"added_snapshot_ids\\\"] == [\\\"tool-1\\\", \\\"tool-2\\\"]\\n\\n\\ndef test_create_schema_accepts_raw_tool_pool_and_shared_connection_refs() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_create is not None\\n\\n    payload = {\\n        \\\"display_name\\\": \\\"Create Agent\\\",\\n        \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n        \\\"tools\\\": {\\n            \\\"raw_payloads\\\": [_raw_tool(\\\"tool-new-1\\\", 11)],\\n        },\\n        \\\"connections\\\": {\\n            \\\"raw_payloads\\\": [_raw_connection(\\\"app-new-1\\\")],\\n        },\\n        \\\"operations\\\": [\\n            {\\n                \\\"op\\\": \\\"bind\\\",\\n                \\\"tool\\\": {\\\"name_of_raw\\\": \\\"tool_new_1\\\"},\\n                \\\"app_ids\\\": [\\\"app-new-1\\\"],\\n            },\\n            {\\n                \\\"op\\\": \\\"bind\\\",\\n                \\\"tool\\\": {\\\"tool_id_with_ref\\\": {\\\"source_ref\\\": \\\"fv-existing-1\\\", \\\"tool_id\\\": \\\"tool-existing-1\\\"}},\\n                \\\"app_ids\\\": [\\\"app-existing-1\\\"],\\n            },\\n        ],\\n    }\\n\\n    applied = slot.deployment_create.apply(payload)\\n    assert applied[\\\"operations\\\"][0][\\\"tool\\\"][\\\"name_of_raw\\\"] == \\\"tool_new_1\\\"\\n\\n\\ndef test_create_schema_dedupes_duplicate_raw_tool_names() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_create is not None\\n\\n    payload = {\\n        \\\"display_name\\\": \\\"Create Agent\\\",\\n        \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n        \\\"tools\\\": {\\n            \\\"raw_payloads\\\": [\\n                _raw_tool(\\\"tool-dup\\\", 101),\\n                _raw_tool(\\\"tool-dup\\\", 102),\\n            ],\\n        },\\n        \\\"connections\\\": {},\\n        \\\"operations\\\": [\\n            {\\n                \\\"op\\\": \\\"bind\\\",\\n                \\\"tool\\\": {\\\"name_of_raw\\\": \\\"tool_dup\\\"},\\n                \\\"app_ids\\\": [\\\"app-existing-1\\\"],\\n            }\\n        ],\\n    }\\n\\n    applied = slot.deployment_create.apply(payload)\\n    raw_payloads = applied[\\\"tools\\\"][\\\"raw_payloads\\\"]\\n    assert len(raw_payloads) == 1\\n    assert raw_payloads[0][\\\"provider_data\\\"][\\\"tool_name\\\"] == \\\"tool_dup\\\"\\n    # First payload wins after dedupe.\\n    assert raw_payloads[0][\\\"provider_data\\\"][\\\"source_ref\\\"] == \\\"fv-101\\\"\\n\\n\\ndef test_update_schema_accepts_raw_tool_pool_and_shared_connection_refs() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_update is not None\\n\\n    payload = {\\n        \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n        \\\"tools\\\": {\\n            \\\"raw_payloads\\\": [_raw_tool(\\\"tool-new-1\\\", 1)],\\n        },\\n        \\\"connections\\\": {\\n            \\\"raw_payloads\\\": [_raw_connection(\\\"app-new-1\\\")],\\n        },\\n        \\\"operations\\\": [\\n            {\\n                \\\"op\\\": \\\"bind\\\",\\n                \\\"tool\\\": {\\\"name_of_raw\\\": \\\"tool_new_1\\\"},\\n                \\\"app_ids\\\": [\\\"app-new-1\\\"],\\n            },\\n            {\\n                \\\"op\\\": \\\"bind\\\",\\n                \\\"tool\\\": {\\\"tool_id_with_ref\\\": {\\\"source_ref\\\": \\\"fv-existing-1\\\", \\\"tool_id\\\": \\\"tool-existing-1\\\"}},\\n                \\\"app_ids\\\": [\\\"app-existing-1\\\"],\\n            },\\n        ],\\n    }\\n\\n    applied = slot.deployment_update.apply(payload)\\n    assert applied[\\\"operations\\\"][0][\\\"tool\\\"][\\\"name_of_raw\\\"] == \\\"tool_new_1\\\"\\n    assert applied[\\\"operations\\\"][1][\\\"tool\\\"][\\\"tool_id_with_ref\\\"][\\\"tool_id\\\"] == \\\"tool-existing-1\\\"\\n\\n\\ndef test_update_schema_allows_bind_app_ids_that_overlap_raw_connection_ids() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_update is not None\\n\\n    applied = slot.deployment_update.apply(\\n        {\\n            \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n            \\\"connections\\\": {\\\"raw_payloads\\\": [_raw_connection(\\\"dup\\\")]},\\n            \\\"operations\\\": [\\n                {\\n                    \\\"op\\\": \\\"bind\\\",\\n                    \\\"tool\\\": {\\\"tool_id_with_ref\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-existing-1\\\"}},\\n                    \\\"app_ids\\\": [\\\"dup\\\"],\\n                }\\n            ],\\n        }\\n    )\\n    assert applied[\\\"connections\\\"][\\\"raw_payloads\\\"][0][\\\"app_id\\\"] == \\\"dup\\\"\\n\\n\\ndef test_update_schema_rejects_missing_raw_tool_reference() -> None:\\n    with pytest.raises(AdapterPayloadValidationError) as exc:\\n        payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n            {\\n                \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n                \\\"connections\\\": {\\n                    \\\"raw_payloads\\\": [],\\n                },\\n                \\\"operations\\\": [\\n                    {\\n                        \\\"op\\\": \\\"bind\\\",\\n                        \\\"tool\\\": {\\\"name_of_raw\\\": \\\"missing-tool\\\"},\\n                        \\\"app_ids\\\": [\\\"app-existing-1\\\"],\\n                    }\\n                ],\\n            }\\n        )\\n    assert \\\"name_of_raw not found\\\" in str(exc.value.error)\\n\\n\\ndef test_update_schema_rejects_tool_reference_with_both_selectors() -> None:\\n    with pytest.raises(AdapterPayloadValidationError) as exc:\\n        payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n            {\\n                \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n                \\\"tools\\\": {\\\"raw_payloads\\\": [_raw_tool(\\\"tool-new-1\\\", 1)]},\\n                \\\"connections\\\": {},\\n                \\\"operations\\\": [\\n                    {\\n                        \\\"op\\\": \\\"bind\\\",\\n                        \\\"tool\\\": {\\n                            \\\"tool_id_with_ref\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-existing-1\\\"},\\n                            \\\"name_of_raw\\\": \\\"tool_new_1\\\",\\n                        },\\n                        \\\"app_ids\\\": [\\\"app-existing-1\\\"],\\n                    }\\n                ],\\n            }\\n        )\\n    assert \\\"Exactly one of 'tool.tool_id_with_ref' or 'tool.name_of_raw' must be provided\\\" in str(exc.value.error)\\n\\n\\ndef test_update_schema_rejects_conflicting_source_ref_for_same_tool_id() -> None:\\n    with pytest.raises(AdapterPayloadValidationError) as exc:\\n        payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n            {\\n                \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n                \\\"connections\\\": {},\\n                \\\"operations\\\": [\\n                    {\\n                        \\\"op\\\": \\\"bind\\\",\\n                        \\\"tool\\\": {\\\"tool_id_with_ref\\\": {\\\"source_ref\\\": \\\"fv-aaa\\\", \\\"tool_id\\\": \\\"tool-1\\\"}},\\n                        \\\"app_ids\\\": [\\\"app-1\\\"],\\n                    },\\n                    {\\n                        \\\"op\\\": \\\"unbind\\\",\\n                        \\\"tool\\\": {\\\"source_ref\\\": \\\"fv-bbb\\\", \\\"tool_id\\\": \\\"tool-1\\\"},\\n                        \\\"app_ids\\\": [\\\"app-2\\\"],\\n                    },\\n                ],\\n            }\\n        )\\n    assert \\\"Conflicting source_ref for tool_id='tool-1'\\\" in str(exc.value.error)\\n\\n\\ndef test_update_schema_accepts_bind_app_id_not_in_raw_pool_as_existing() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_update is not None\\n\\n    applied = slot.deployment_update.apply(\\n        {\\n            \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n            \\\"tools\\\": {\\n                \\\"raw_payloads\\\": [_raw_tool(\\\"tool-new-1\\\", 2)],\\n            },\\n            \\\"connections\\\": {},\\n            \\\"operations\\\": [\\n                {\\n                    \\\"op\\\": \\\"bind\\\",\\n                    \\\"tool\\\": {\\\"name_of_raw\\\": \\\"tool_new_1\\\"},\\n                    \\\"app_ids\\\": [\\\"app-not-declared\\\"],\\n                }\\n            ],\\n        }\\n    )\\n    assert applied[\\\"operations\\\"][0][\\\"app_ids\\\"] == [\\\"app-not-declared\\\"]\\n\\n\\ndef test_update_schema_accepts_implicit_existing_connections() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_update is not None\\n\\n    applied = slot.deployment_update.apply(\\n        {\\n            \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n            \\\"connections\\\": {},\\n            \\\"operations\\\": [\\n                {\\n                    \\\"op\\\": \\\"bind\\\",\\n                    \\\"tool\\\": {\\\"tool_id_with_ref\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-existing-1\\\"}},\\n                    \\\"app_ids\\\": [\\\"app-existing-1\\\"],\\n                }\\n            ],\\n        }\\n    )\\n    assert applied[\\\"operations\\\"][0][\\\"app_ids\\\"] == [\\\"app-existing-1\\\"]\\n\\n\\ndef test_update_schema_rejects_unused_raw_connection_app_ids() -> None:\\n    with pytest.raises(AdapterPayloadValidationError) as exc:\\n        payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n            {\\n                \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n                \\\"tools\\\": {\\\"raw_payloads\\\": [_raw_tool(\\\"tool-new-1\\\", 3)]},\\n                \\\"connections\\\": {\\\"raw_payloads\\\": [_raw_connection(\\\"app-new-1\\\"), _raw_connection(\\\"app-unused\\\")]},\\n                \\\"operations\\\": [\\n                    {\\n                        \\\"op\\\": \\\"bind\\\",\\n                        \\\"tool\\\": {\\\"name_of_raw\\\": \\\"tool_new_1\\\"},\\n                        \\\"app_ids\\\": [\\\"app-new-1\\\"],\\n                    }\\n                ],\\n            }\\n        )\\n    assert \\\"raw_payloads contains app_id values not referenced by operations\\\" in str(exc.value.error)\\n\\n\\ndef test_update_schema_dedupes_bind_app_ids() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_update is not None\\n\\n    payload = {\\n        \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n        \\\"connections\\\": {},\\n        \\\"operations\\\": [\\n            {\\n                \\\"op\\\": \\\"bind\\\",\\n                \\\"tool\\\": {\\\"tool_id_with_ref\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-existing-1\\\"}},\\n                \\\"app_ids\\\": [\\\"app-existing-1\\\", \\\"app-existing-1\\\", \\\"app-existing-2\\\"],\\n            }\\n        ],\\n    }\\n\\n    applied = slot.deployment_update.apply(payload)\\n    assert applied[\\\"operations\\\"][0][\\\"app_ids\\\"] == [\\\"app-existing-1\\\", \\\"app-existing-2\\\"]\\n\\n\\ndef test_update_schema_requires_unbind_app_ids() -> None:\\n    with pytest.raises(AdapterPayloadValidationError):\\n        payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n            {\\n                \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n                \\\"operations\\\": [\\n                    {\\n                        \\\"op\\\": \\\"unbind\\\",\\n                        \\\"tool\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-1\\\"},\\n                    }\\n                ],\\n            }\\n        )\\n\\n\\ndef test_update_schema_rejects_unbind_raw_app_ids() -> None:\\n    with pytest.raises(AdapterPayloadValidationError) as exc:\\n        payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n            {\\n                \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n                \\\"connections\\\": {\\\"raw_payloads\\\": [_raw_connection(\\\"app-new-1\\\")]},\\n                \\\"operations\\\": [\\n                    {\\n                        \\\"op\\\": \\\"unbind\\\",\\n                        \\\"tool\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-1\\\"},\\n                        \\\"app_ids\\\": [\\\"app-new-1\\\"],\\n                    }\\n                ],\\n            }\\n        )\\n    assert \\\"must not reference connections.raw_payloads app_ids\\\" in str(exc.value.error)\\n\\n\\n# ---------------------------------------------------------------------------\\n# validate_has_work / put_tools\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_update_schema_accepts_empty_payload_without_llm() -> None:\\n    \\\"\\\"\\\"Empty update payload is allowed; service layer decides if the request has actionable work.\\\"\\\"\\\"\\n    applied = payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n        {}\\n    )\\n    assert applied[\\\"llm\\\"] is None\\n    assert applied[\\\"operations\\\"] == []\\n\\n\\ndef test_update_schema_accepts_put_tools_alone() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_update is not None\\n\\n    applied = slot.deployment_update.apply({\\\"put_tools\\\": [\\\"tool-id-1\\\", \\\"tool-id-2\\\"]})\\n    assert applied[\\\"put_tools\\\"] == [\\\"tool-id-1\\\", \\\"tool-id-2\\\"]\\n    assert applied[\\\"operations\\\"] == []\\n\\n\\ndef test_update_schema_put_tools_deduplicates() -> None:\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_update is not None\\n\\n    applied = slot.deployment_update.apply({\\\"put_tools\\\": [\\\"t1\\\", \\\"t2\\\", \\\"t1\\\", \\\"t3\\\", \\\"t2\\\"]})\\n    assert applied[\\\"put_tools\\\"] == [\\\"t1\\\", \\\"t2\\\", \\\"t3\\\"]\\n\\n\\ndef test_update_schema_rejects_put_tools_with_operations() -> None:\\n    with pytest.raises(AdapterPayloadValidationError) as exc:\\n        payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n            {\\n                \\\"put_tools\\\": [\\\"tool-id-1\\\"],\\n                \\\"connections\\\": {},\\n                \\\"operations\\\": [\\n                    {\\n                        \\\"op\\\": \\\"bind\\\",\\n                        \\\"tool\\\": {\\\"tool_id_with_ref\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-1\\\"}},\\n                        \\\"app_ids\\\": [\\\"app-1\\\"],\\n                    }\\n                ],\\n            }\\n        )\\n    assert \\\"standalone full replacement and cannot be combined\\\" in str(exc.value.error)\\n\\n\\ndef test_update_schema_rejects_put_tools_with_raw_tool_payloads() -> None:\\n    with pytest.raises(AdapterPayloadValidationError) as exc:\\n        payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n            {\\n                \\\"put_tools\\\": [\\\"tool-id-1\\\"],\\n                \\\"tools\\\": {\\\"raw_payloads\\\": [_raw_tool(\\\"tool-new\\\", 1)]},\\n            }\\n        )\\n    assert \\\"standalone full replacement and cannot be combined\\\" in str(exc.value.error)\\n\\n\\ndef test_update_schema_rejects_put_tools_with_connection_raw_payloads() -> None:\\n    with pytest.raises(AdapterPayloadValidationError) as exc:\\n        payload_schemas.deployment_update.apply(  # type: ignore[union-attr]\\n            {\\n                \\\"put_tools\\\": [\\\"tool-id-1\\\"],\\n                \\\"connections\\\": {\\\"raw_payloads\\\": [_raw_connection(\\\"app-1\\\")]},\\n            }\\n        )\\n    assert \\\"standalone full replacement and cannot be combined\\\" in str(exc.value.error)\\n\\n\\ndef test_update_schema_accepts_operations_without_put_tools() -> None:\\n    \\\"\\\"\\\"Existing happy-path: operations alone is valid (pre-existing behavior).\\\"\\\"\\\"\\n    slot = payload_schemas\\n    assert slot is not None\\n    assert slot.deployment_update is not None\\n\\n    applied = slot.deployment_update.apply(\\n        {\\n            \\\"llm\\\": \\\"granite-3-8b-instruct\\\",\\n            \\\"connections\\\": {},\\n            \\\"operations\\\": [\\n                {\\n                    \\\"op\\\": \\\"bind\\\",\\n                    \\\"tool\\\": {\\\"tool_id_with_ref\\\": {\\\"source_ref\\\": \\\"fv-1\\\", \\\"tool_id\\\": \\\"tool-1\\\"}},\\n                    \\\"app_ids\\\": [\\\"app-1\\\"],\\n                }\\n            ],\\n        }\\n    )\\n    assert len(applied[\\\"operations\\\"]) == 1\\n    assert applied[\\\"put_tools\\\"] is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/deployment_artifacts/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0c9c293c3f98d398ba84cbd27382968364b24db3c74f2e9ce363953e8236d9d9\",\"content\":\"\\\"\\\"\\\"Tests for deployment artifact services.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/deployment_artifacts/test_project_artifact.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1bd62e939fe2495ae05ec273e36fa3a5abe090f9ca1125e307a0fa3780c8a967\",\"content\":\"from __future__ import annotations\\n\\nimport ast\\nimport asyncio\\nimport hashlib\\nimport io\\nimport json\\nimport stat\\nimport threading\\nimport tracemalloc\\nimport zipfile\\nfrom copy import deepcopy\\nfrom datetime import timedelta\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom fastapi import HTTPException\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.folder.model import Folder\\nfrom langflow.services.deployment_artifacts import (\\n    LFPKG_MEDIA_TYPE,\\n    EmptyProjectArtifactError,\\n    ProjectArtifactError,\\n    ProjectArtifactLimitError,\\n    ProjectArtifactLimits,\\n    ProjectArtifactNotFoundError,\\n    build_project_artifact,\\n)\\n\\nMODULE = \\\"langflow.services.deployment_artifacts.builder\\\"\\nFIXED_ZIP_TIMESTAMP = (1980, 1, 1, 0, 0, 0)\\n\\n\\ndef _flow(*, flow_id: UUID | None = None, owner_id: UUID, project_id: UUID, name: str = \\\"Flow\\\") -> Flow:\\n    return Flow(\\n        id=flow_id or uuid4(),\\n        name=name,\\n        user_id=owner_id,\\n        folder_id=project_id,\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n    )\\n\\n\\ndef _session_with_flows(flows: list[Flow], *, repeats: int = 1) -> AsyncMock:\\n    ordered = sorted(flows, key=lambda flow: str(flow.id))\\n    pages = [ordered[index : index + 4] for index in range(0, len(ordered), 4)]\\n    results: list[MagicMock] = []\\n    for _ in range(repeats):\\n        revision_result = MagicMock()\\n        revision_result.all.return_value = [(flow.id, flow.user_id, flow.updated_at) for flow in ordered]\\n        results.append(revision_result)\\n        for page in pages:\\n            result = MagicMock()\\n            result.all.return_value = page\\n            results.append(result)\\n        final_revision_result = MagicMock()\\n        final_revision_result.all.return_value = [(flow.id, flow.user_id, flow.updated_at) for flow in ordered]\\n        results.append(final_revision_result)\\n    session = AsyncMock()\\n    session.exec.side_effect = results\\n    return session\\n\\n\\nasync def _build_authorized(\\n    *,\\n    session: AsyncMock,\\n    user: SimpleNamespace,\\n    project: Folder,\\n    limits: ProjectArtifactLimits | None = None,\\n    flow_ids: list[UUID] | None = None,\\n):\\n    with (\\n        patch(f\\\"{MODULE}.authorized_or_owner_scoped\\\", new_callable=AsyncMock, return_value=project) as load_project,\\n        patch(f\\\"{MODULE}.ensure_project_permission\\\", new_callable=AsyncMock) as ensure_project,\\n        patch(f\\\"{MODULE}.ensure_flows_permission\\\", new_callable=AsyncMock) as ensure_flows,\\n    ):\\n        kwargs = {\\\"limits\\\": limits} if limits is not None else {}\\n        if flow_ids is not None:\\n            kwargs[\\\"flow_ids\\\"] = flow_ids\\n        artifact = await build_project_artifact(session, user, project.id, **kwargs)\\n    return artifact, load_project, ensure_project, ensure_flows\\n\\n\\ndef test_deployment_artifact_service_does_not_depend_on_api_or_fastapi() -> None:\\n    from langflow.services.deployment_artifacts import builder\\n\\n    tree = ast.parse(Path(builder.__file__).read_text())\\n    imported_modules = {alias.name for node in ast.walk(tree) if isinstance(node, ast.Import) for alias in node.names}\\n    imported_modules.update(\\n        node.module for node in ast.walk(tree) if isinstance(node, ast.ImportFrom) and node.module is not None\\n    )\\n\\n    assert not any(module.startswith((\\\"fastapi\\\", \\\"langflow.api\\\")) for module in imported_modules)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_raises_domain_error_when_project_is_not_found() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    session = AsyncMock()\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with (\\n        patch(f\\\"{MODULE}.authorized_or_owner_scoped\\\", new_callable=AsyncMock, return_value=None),\\n        pytest.raises(ProjectArtifactNotFoundError, match=\\\"Project not found\\\"),\\n    ):\\n        await build_project_artifact(session, user, project_id)\\n\\n    session.exec.assert_not_awaited()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_is_deterministic_and_manifest_binds_exact_flow_files() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Deterministic Project\\\", user_id=actor_id)\\n    first_id = UUID(\\\"00000000-0000-0000-0000-000000000001\\\")\\n    second_id = UUID(\\\"00000000-0000-0000-0000-000000000002\\\")\\n    flows = [\\n        _flow(flow_id=second_id, owner_id=actor_id, project_id=project_id, name=\\\"Second\\\"),\\n        _flow(flow_id=first_id, owner_id=actor_id, project_id=project_id, name=\\\"First\\\"),\\n    ]\\n    session = _session_with_flows(flows, repeats=2)\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    first, *_ = await _build_authorized(session=session, user=user, project=project)\\n    second, *_ = await _build_authorized(session=session, user=user, project=project)\\n\\n    assert first.content == second.content\\n    assert first.filename == f\\\"langflow-project-{project_id}.lfpkg\\\"\\n    assert first.media_type == LFPKG_MEDIA_TYPE\\n    assert first.project_id == project_id\\n    assert first.project_name == project.name\\n    assert first.flow_count == 2\\n\\n    with zipfile.ZipFile(io.BytesIO(first.content)) as archive:\\n        expected_names = [\\n            \\\"manifest.json\\\",\\n            f\\\"flows/{first_id}.json\\\",\\n            f\\\"flows/{second_id}.json\\\",\\n        ]\\n        assert archive.namelist() == expected_names\\n        for info in archive.infolist():\\n            assert info.date_time == FIXED_ZIP_TIMESTAMP\\n            assert info.compress_type == zipfile.ZIP_STORED\\n            assert stat.S_IMODE(info.external_attr >> 16) == 0o644\\n\\n        manifest = json.loads(archive.read(\\\"manifest.json\\\"))\\n        assert manifest[\\\"schema_version\\\"] == 1\\n        assert manifest[\\\"project\\\"] == {\\\"id\\\": str(project_id), \\\"name\\\": project.name}\\n        assert manifest[\\\"required_variables\\\"] == []\\n        assert [entry[\\\"id\\\"] for entry in manifest[\\\"flows\\\"]] == [str(first_id), str(second_id)]\\n        for entry in manifest[\\\"flows\\\"]:\\n            payload = archive.read(entry[\\\"path\\\"])\\n            assert entry[\\\"sha256\\\"] == hashlib.sha256(payload).hexdigest()\\n            assert entry[\\\"size\\\"] == len(payload)\\n            assert entry[\\\"required_variables\\\"] == []\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_omits_environment_specific_flow_fields() -> None:\\n    \\\"\\\"\\\"Packaged flows must not carry identifiers of the deployment they came from.\\\"\\\"\\\"\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    workspace_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Portable Project\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id, name=\\\"Portable\\\")\\n    flow.workspace_id = workspace_id\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    artifact, *_ = await _build_authorized(session=session, user=user, project=project)\\n\\n    with zipfile.ZipFile(io.BytesIO(artifact.content)) as archive:\\n        payload = archive.read(f\\\"flows/{flow.id}.json\\\")\\n        packaged = json.loads(payload)\\n\\n    assert str(workspace_id) not in payload.decode()\\n    for field in (\\\"workspace_id\\\", \\\"user_id\\\", \\\"folder_id\\\", \\\"updated_at\\\"):\\n        assert field not in packaged\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_packages_only_explicit_flow_ids() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Selected flows\\\", user_id=actor_id)\\n    selected_id = UUID(\\\"00000000-0000-0000-0000-000000000001\\\")\\n    unselected_id = UUID(\\\"00000000-0000-0000-0000-000000000002\\\")\\n    selected = _flow(flow_id=selected_id, owner_id=actor_id, project_id=project_id, name=\\\"Selected\\\")\\n    _ = _flow(flow_id=unselected_id, owner_id=actor_id, project_id=project_id, name=\\\"Unselected\\\")\\n    session = _session_with_flows([selected])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    artifact, _, _, ensure_flows = await _build_authorized(\\n        session=session,\\n        user=user,\\n        project=project,\\n        flow_ids=[selected_id],\\n    )\\n\\n    assert [flow.flow_id for flow in artifact.flows] == [selected_id]\\n    assert ensure_flows.await_args.kwargs[\\\"flow_ids\\\"] == [selected_id]\\n    with zipfile.ZipFile(io.BytesIO(artifact.content)) as archive:\\n        assert archive.namelist() == [\\\"manifest.json\\\", f\\\"flows/{selected_id}.json\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_rejects_missing_or_duplicate_flow_selection() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Selected flows\\\", user_id=actor_id)\\n    selected = _flow(owner_id=actor_id, project_id=project_id)\\n    missing_id = uuid4()\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with (\\n        patch(f\\\"{MODULE}.authorized_or_owner_scoped\\\", new_callable=AsyncMock, return_value=project),\\n        patch(f\\\"{MODULE}.ensure_project_permission\\\", new_callable=AsyncMock),\\n        pytest.raises(ProjectArtifactNotFoundError, match=\\\"selected flows were not found\\\"),\\n    ):\\n        await build_project_artifact(\\n            _session_with_flows([selected]),\\n            user,\\n            project_id,\\n            flow_ids=[selected.id, missing_id],\\n        )\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"duplicate flow IDs\\\"):\\n        await build_project_artifact(\\n            AsyncMock(),\\n            user,\\n            project_id,\\n            flow_ids=[selected.id, selected.id],\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_includes_cross_author_flows_with_safe_permission_batches() -> None:\\n    actor_id = uuid4()\\n    owner_id = uuid4()\\n    collaborator_id = uuid4()\\n    project_id = uuid4()\\n    workspace_id = uuid4()\\n    project = Folder(\\n        id=project_id,\\n        name=\\\"Shared Project\\\",\\n        user_id=owner_id,\\n        workspace_id=workspace_id,\\n    )\\n    actor_flow = _flow(\\n        flow_id=UUID(\\\"00000000-0000-0000-0000-000000000001\\\"),\\n        owner_id=actor_id,\\n        project_id=project_id,\\n        name=\\\"Actor flow\\\",\\n    )\\n    owner_flow = _flow(\\n        flow_id=UUID(\\\"00000000-0000-0000-0000-000000000002\\\"),\\n        owner_id=owner_id,\\n        project_id=project_id,\\n        name=\\\"Project owner flow\\\",\\n    )\\n    collaborator_flow = _flow(\\n        flow_id=UUID(\\\"00000000-0000-0000-0000-000000000003\\\"),\\n        owner_id=collaborator_id,\\n        project_id=project_id,\\n        name=\\\"Collaborator flow\\\",\\n    )\\n    session = _session_with_flows([actor_flow, owner_flow, collaborator_flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    artifact, load_project, ensure_project, ensure_flows = await _build_authorized(\\n        session=session,\\n        user=user,\\n        project=project,\\n    )\\n\\n    assert [flow.flow_id for flow in artifact.flows] == [actor_flow.id, owner_flow.id, collaborator_flow.id]\\n    assert load_project.await_args.kwargs[\\\"owner_id\\\"] == actor_id\\n    ensure_project.assert_awaited_once()\\n    assert ensure_project.await_args.args[1].value == \\\"read\\\"\\n    assert ensure_project.await_args.kwargs == {\\n        \\\"project_id\\\": project_id,\\n        \\\"project_user_id\\\": owner_id,\\n        \\\"workspace_id\\\": workspace_id,\\n    }\\n    assert ensure_flows.await_count == 2\\n    actor_batch, non_owned_batch = ensure_flows.await_args_list\\n    assert actor_batch.args[1].value == \\\"read\\\"\\n    assert actor_batch.kwargs == {\\n        \\\"flow_ids\\\": [actor_flow.id],\\n        \\\"flow_user_id\\\": actor_id,\\n        \\\"workspace_id\\\": workspace_id,\\n        \\\"folder_id\\\": project_id,\\n    }\\n    assert non_owned_batch.args[1].value == \\\"read\\\"\\n    assert non_owned_batch.kwargs == {\\n        \\\"flow_ids\\\": [owner_flow.id, collaborator_flow.id],\\n        \\\"flow_user_id\\\": None,\\n        \\\"workspace_id\\\": workspace_id,\\n        \\\"folder_id\\\": project_id,\\n    }\\n\\n    assert session.exec.await_count == 3\\n    for flow_query_call in session.exec.await_args_list:\\n        compiled = str(flow_query_call.args[0].compile(compile_kwargs={\\\"literal_binds\\\": True}))\\n        assert project_id.hex in compiled\\n        assert owner_id.hex not in compiled\\n        assert collaborator_id.hex not in compiled\\n        assert actor_id.hex not in compiled\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_requires_project_read_before_loading_flows() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Denied\\\", user_id=actor_id)\\n    session = _session_with_flows([])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with (\\n        patch(f\\\"{MODULE}.authorized_or_owner_scoped\\\", new_callable=AsyncMock, return_value=project),\\n        patch(\\n            f\\\"{MODULE}.ensure_project_permission\\\",\\n            new_callable=AsyncMock,\\n            side_effect=HTTPException(status_code=403, detail=\\\"denied\\\"),\\n        ),\\n        patch(f\\\"{MODULE}.ensure_flows_permission\\\", new_callable=AsyncMock) as ensure_flows,\\n        pytest.raises(HTTPException, match=\\\"denied\\\"),\\n    ):\\n        await build_project_artifact(session, user, project_id)\\n\\n    session.exec.assert_not_awaited()\\n    ensure_flows.assert_not_awaited()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_fails_whole_package_when_any_flow_is_unreadable() -> None:\\n    actor_id = uuid4()\\n    owner_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"No partial exports\\\", user_id=owner_id)\\n    flows = [\\n        _flow(owner_id=owner_id, project_id=project_id, name=\\\"Allowed\\\"),\\n        _flow(owner_id=owner_id, project_id=project_id, name=\\\"Denied\\\"),\\n    ]\\n    session = _session_with_flows(flows)\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with (\\n        patch(f\\\"{MODULE}.authorized_or_owner_scoped\\\", new_callable=AsyncMock, return_value=project),\\n        patch(f\\\"{MODULE}.ensure_project_permission\\\", new_callable=AsyncMock),\\n        patch(\\n            f\\\"{MODULE}.ensure_flows_permission\\\",\\n            new_callable=AsyncMock,\\n            side_effect=HTTPException(status_code=403, detail=\\\"denied\\\"),\\n        ),\\n        patch(f\\\"{MODULE}._build_archive\\\") as build_archive,\\n        pytest.raises(HTTPException, match=\\\"denied\\\"),\\n    ):\\n        await build_project_artifact(session, user, project_id)\\n\\n    build_archive.assert_not_called()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cancelled_package_waits_for_archive_worker_before_releasing_capacity() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Cancellation\\\", user_id=actor_id)\\n    session = _session_with_flows([_flow(owner_id=actor_id, project_id=project_id)])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n    worker_started = threading.Event()\\n    release_worker = threading.Event()\\n\\n    def blocking_archive(**_kwargs):\\n        worker_started.set()\\n        release_worker.wait(timeout=5)\\n        return MagicMock()\\n\\n    with (\\n        patch(f\\\"{MODULE}.authorized_or_owner_scoped\\\", new_callable=AsyncMock, return_value=project),\\n        patch(f\\\"{MODULE}.ensure_project_permission\\\", new_callable=AsyncMock),\\n        patch(f\\\"{MODULE}.ensure_flows_permission\\\", new_callable=AsyncMock),\\n        patch(f\\\"{MODULE}._build_archive\\\", side_effect=blocking_archive),\\n    ):\\n        task = asyncio.create_task(build_project_artifact(session, user, project_id))\\n        assert await asyncio.to_thread(worker_started.wait, 2)\\n        task.cancel()\\n        await asyncio.sleep(0)\\n        try:\\n            assert not task.done()\\n        finally:\\n            release_worker.set()\\n\\n        with pytest.raises(asyncio.CancelledError):\\n            await task\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_scrubs_secret_fields_without_resolving_references() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Secrets\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n    flow.data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"password\\\": {\\\"name\\\": \\\"password\\\", \\\"password\\\": True, \\\"value\\\": \\\"raw-password\\\"},\\n                            \\\"client_secret\\\": {\\\"name\\\": \\\"client_secret\\\", \\\"value\\\": \\\"raw-client-secret\\\"},\\n                            \\\"headers\\\": {\\n                                \\\"name\\\": \\\"headers\\\",\\n                                \\\"value\\\": {\\\"Authorization\\\": \\\"Bearer raw-token\\\", \\\"safe\\\": \\\"kept\\\"},\\n                            },\\n                            \\\"variable\\\": {\\\"name\\\": \\\"model\\\", \\\"value\\\": \\\"${MODEL_NAME}\\\"},\\n                        }\\n                    }\\n                }\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    artifact, *_ = await _build_authorized(session=session, user=user, project=project)\\n\\n    assert b\\\"raw-password\\\" not in artifact.content\\n    assert b\\\"raw-client-secret\\\" not in artifact.content\\n    assert b\\\"raw-token\\\" not in artifact.content\\n    with zipfile.ZipFile(io.BytesIO(artifact.content)) as archive:\\n        exported = json.loads(archive.read(f\\\"flows/{flow.id}.json\\\"))\\n    template = exported[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n    assert template[\\\"password\\\"][\\\"value\\\"] is None\\n    assert template[\\\"client_secret\\\"][\\\"value\\\"] is None\\n    assert template[\\\"headers\\\"][\\\"value\\\"] == {\\\"Authorization\\\": None, \\\"safe\\\": \\\"kept\\\"}\\n    assert template[\\\"variable\\\"][\\\"value\\\"] == \\\"${MODEL_NAME}\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_preserves_variable_references_and_lists_required_variables() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Variable references\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n    flow.data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"api_key\\\": {\\n                                \\\"name\\\": \\\"api_key\\\",\\n                                \\\"password\\\": True,\\n                                \\\"load_from_db\\\": True,\\n                                \\\"value\\\": \\\"OPENAI_API_KEY\\\",\\n                            },\\n                            \\\"password\\\": {\\\"name\\\": \\\"password\\\", \\\"password\\\": True, \\\"value\\\": \\\"raw-password\\\"},\\n                            \\\"endpoint\\\": {\\\"name\\\": \\\"endpoint\\\", \\\"load_from_db\\\": True, \\\"value\\\": \\\"MY_INTERNAL_API_URL\\\"},\\n                            \\\"mislabeled\\\": {\\n                                \\\"name\\\": \\\"token\\\",\\n                                \\\"password\\\": True,\\n                                \\\"load_from_db\\\": True,\\n                                \\\"value\\\": \\\"raw-mislabeled-secret\\\\nwith-newline\\\",\\n                            },\\n                        }\\n                    }\\n                }\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    artifact, *_ = await _build_authorized(session=session, user=user, project=project)\\n\\n    assert b\\\"raw-password\\\" not in artifact.content\\n    assert b\\\"raw-mislabeled-secret\\\" not in artifact.content\\n    assert artifact.flows[0].required_variables == (\\\"MY_INTERNAL_API_URL\\\", \\\"OPENAI_API_KEY\\\")\\n    with zipfile.ZipFile(io.BytesIO(artifact.content)) as archive:\\n        exported = json.loads(archive.read(f\\\"flows/{flow.id}.json\\\"))\\n        manifest = json.loads(archive.read(\\\"manifest.json\\\"))\\n    template = exported[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n    assert template[\\\"api_key\\\"][\\\"value\\\"] == \\\"OPENAI_API_KEY\\\"\\n    assert template[\\\"api_key\\\"][\\\"load_from_db\\\"] is True\\n    assert template[\\\"password\\\"][\\\"value\\\"] is None\\n    assert template[\\\"endpoint\\\"][\\\"value\\\"] == \\\"MY_INTERNAL_API_URL\\\"\\n    assert template[\\\"mislabeled\\\"][\\\"value\\\"] is None\\n    assert manifest[\\\"required_variables\\\"] == [\\\"MY_INTERNAL_API_URL\\\", \\\"OPENAI_API_KEY\\\"]\\n    assert manifest[\\\"flows\\\"][0][\\\"required_variables\\\"] == [\\\"MY_INTERNAL_API_URL\\\", \\\"OPENAI_API_KEY\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_keeps_newline_heavy_code_as_bounded_string() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Runtime code\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n    code = \\\"\\\\n\\\" * 100_000\\n    flow.data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"code\\\": {\\\"name\\\": \\\"code\\\", \\\"type\\\": \\\"code\\\", \\\"value\\\": code},\\n                        }\\n                    }\\n                }\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    artifact, *_ = await _build_authorized(session=session, user=user, project=project)\\n\\n    with zipfile.ZipFile(io.BytesIO(artifact.content)) as archive:\\n        exported = json.loads(archive.read(f\\\"flows/{flow.id}.json\\\"))\\n    assert exported[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] == code\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_rejects_lone_unicode_surrogate_in_flow_name() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Valid project\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id, name=\\\"Invalid flow \\\\ud800\\\")\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"Unicode surrogate\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_rejects_lone_unicode_surrogate_in_project_name() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Invalid project \\\\ud800\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"Unicode surrogate\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_rejects_lone_unicode_surrogate_in_persisted_string_value() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Valid project\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n    flow.data = {\\\"nodes\\\": [], \\\"edges\\\": [], \\\"persisted\\\": \\\"Invalid value \\\\ud800\\\"}\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"Unicode surrogate\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_rejects_lone_unicode_surrogate_in_persisted_object_key() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Valid project\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n    flow.data = {\\\"nodes\\\": [], \\\"edges\\\": [], \\\"persisted\\\": {\\\"Invalid key \\\\ud800\\\": \\\"value\\\"}}\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"Unicode surrogate\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n\\ndef test_secret_scrub_uses_bounded_memory_for_wide_deep_structured_value() -> None:\\n    from langflow.services.deployment_artifacts import builder\\n\\n    structured: object = [None] * 100_000\\n    for _ in range(50):\\n        structured = {\\\"nested\\\": structured}\\n    snapshot = builder._FlowSnapshot(\\n        flow_id=uuid4(),\\n        name=\\\"Bounded scrub\\\",\\n        payload={\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"data\\\": {\\n                            \\\"node\\\": {\\n                                \\\"template\\\": {\\n                                    \\\"settings\\\": {\\\"name\\\": \\\"settings\\\", \\\"value\\\": structured},\\n                                }\\n                            }\\n                        }\\n                    }\\n                ],\\n                \\\"edges\\\": [],\\n            }\\n        },\\n    )\\n\\n    tracemalloc.start()\\n    try:\\n        content, _ = builder._normalized_flow_bytes(snapshot)\\n        _, peak = tracemalloc.get_traced_memory()\\n    finally:\\n        tracemalloc.stop()\\n\\n    assert len(content) < 1024 * 1024\\n    assert peak < 16 * 1024 * 1024\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"data\\\", \\\"expected_data\\\"),\\n    [\\n        (None, None),\\n        (\\n            {\\\"nodes\\\": [None], \\\"edges\\\": []},\\n            {\\\"nodes\\\": [None], \\\"edges\\\": []},\\n        ),\\n        (\\n            {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"data\\\": {\\n                            \\\"node\\\": {\\n                                \\\"template\\\": {\\n                                    \\\"malformed\\\": {\\\"name\\\": None, \\\"password\\\": True, \\\"value\\\": \\\"retained\\\"},\\n                                }\\n                            }\\n                        }\\n                    }\\n                ],\\n                \\\"edges\\\": [],\\n            },\\n            {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"data\\\": {\\n                            \\\"node\\\": {\\n                                \\\"template\\\": {\\n                                    \\\"malformed\\\": {\\\"name\\\": None, \\\"password\\\": True, \\\"value\\\": None},\\n                                }\\n                            }\\n                        }\\n                    }\\n                ],\\n                \\\"edges\\\": [],\\n            },\\n        ),\\n    ],\\n)\\ndef test_normalized_flow_bytes_accepts_model_valid_sparse_data(data: object, expected_data: object) -> None:\\n    from langflow.services.deployment_artifacts import builder\\n\\n    snapshot = builder._FlowSnapshot(\\n        flow_id=uuid4(),\\n        name=\\\"Empty flow\\\",\\n        payload={\\\"data\\\": data},\\n    )\\n    original_payload = deepcopy(snapshot.payload)\\n\\n    content, required_variables = builder._normalized_flow_bytes(snapshot)\\n    assert json.loads(content) == {\\\"data\\\": expected_data}\\n    assert required_variables == ()\\n    assert snapshot.payload == original_payload\\n\\n\\ndef test_normalized_flow_bytes_does_not_mutate_shared_flow_data() -> None:\\n    from langflow.services.deployment_artifacts import builder\\n\\n    flow = _flow(owner_id=uuid4(), project_id=uuid4())\\n    flow.data = {\\n        \\\"nodes\\\": [\\n            {\\n                \\\"selected\\\": True,\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"password\\\": {\\\"name\\\": \\\"password\\\", \\\"password\\\": True, \\\"value\\\": \\\"raw-password\\\"},\\n                        }\\n                    }\\n                },\\n            }\\n        ],\\n        \\\"edges\\\": [],\\n    }\\n    original_data = deepcopy(flow.data)\\n    snapshot = builder._FlowSnapshot(\\n        flow_id=flow.id,\\n        name=\\\"Shared flow data\\\",\\n        payload={\\\"data\\\": flow.data},\\n    )\\n\\n    content, _ = builder._normalized_flow_bytes(snapshot)\\n    exported = json.loads(content)\\n\\n    assert exported[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"password\\\"][\\\"value\\\"] is None\\n    assert \\\"selected\\\" not in exported[\\\"data\\\"][\\\"nodes\\\"][0]\\n    assert flow.data == original_data\\n    assert snapshot.payload[\\\"data\\\"] is flow.data\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_never_uses_mutable_names_as_archive_paths() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name='../../Project\\\\n\\\"name\\\"', user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id, name=\\\"../flow\\\\\\\\name\\\")\\n    flow.fs_path = \\\"../../server-only/path\\\"\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    artifact, *_ = await _build_authorized(session=session, user=user, project=project)\\n\\n    assert artifact.filename == f\\\"langflow-project-{project_id}.lfpkg\\\"\\n    with zipfile.ZipFile(io.BytesIO(artifact.content)) as archive:\\n        assert archive.namelist() == [\\\"manifest.json\\\", f\\\"flows/{flow.id}.json\\\"]\\n        assert all(\\\"..\\\" not in name and \\\"\\\\\\\\\\\" not in name for name in archive.namelist())\\n        exported = json.loads(archive.read(f\\\"flows/{flow.id}.json\\\"))\\n        assert \\\"fs_path\\\" not in exported\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_rejects_empty_projects() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Empty\\\", user_id=actor_id)\\n    session = _session_with_flows([])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(EmptyProjectArtifactError, match=\\\"no flows\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.parametrize(\\n    (\\\"flows\\\", \\\"limits\\\", \\\"message\\\"),\\n    [\\n        (2, ProjectArtifactLimits(max_flow_count=1), \\\"flow count\\\"),\\n        (1, ProjectArtifactLimits(max_flow_bytes=32), \\\"flow file\\\"),\\n        (\\n            1,\\n            ProjectArtifactLimits(max_flow_bytes=1024 * 1024, max_expanded_bytes=32),\\n            \\\"expanded size\\\",\\n        ),\\n    ],\\n)\\nasync def test_build_project_artifact_enforces_resource_limits(\\n    flows: int,\\n    limits: ProjectArtifactLimits,\\n    message: str,\\n) -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Limits\\\", user_id=actor_id)\\n    rows = [_flow(owner_id=actor_id, project_id=project_id, name=f\\\"Flow {index}\\\") for index in range(flows)]\\n    session = _session_with_flows(rows)\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactLimitError, match=message):\\n        await _build_authorized(session=session, user=user, project=project, limits=limits)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_pages_flow_rows_and_authorizes_each_page() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Paged\\\", user_id=actor_id)\\n    rows = [_flow(owner_id=actor_id, project_id=project_id, name=f\\\"Flow {index}\\\") for index in range(5)]\\n    session = _session_with_flows(rows)\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    artifact, _, _, ensure_flows = await _build_authorized(session=session, user=user, project=project)\\n\\n    assert artifact.flow_count == 5\\n    assert session.exec.await_count == 4\\n    ensure_flows.assert_awaited_once()\\n    assert len(ensure_flows.await_args.kwargs[\\\"flow_ids\\\"]) == 5\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_fails_if_selected_flow_changes_before_page_load() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Changing\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n    id_result = MagicMock()\\n    id_result.all.return_value = [(flow.id, flow.user_id, flow.updated_at)]\\n    missing_page = MagicMock()\\n    missing_page.all.return_value = []\\n    session = AsyncMock()\\n    session.exec.side_effect = [id_result, missing_page]\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"changed during packaging\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_fails_if_flow_owner_changes_before_page_snapshot() -> None:\\n    actor_id = uuid4()\\n    new_owner_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Changing owner\\\", user_id=actor_id)\\n    flow = _flow(owner_id=new_owner_id, project_id=project_id)\\n\\n    initial_revisions = MagicMock()\\n    initial_revisions.all.return_value = [(flow.id, actor_id, flow.updated_at)]\\n    page = MagicMock()\\n    page.all.return_value = [flow]\\n    session = AsyncMock()\\n    session.exec.side_effect = [initial_revisions, page]\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"changed during packaging\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_fails_if_loaded_flow_changes_before_final_revision_check() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Changing revision\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n    initial_updated_at = flow.updated_at\\n    assert initial_updated_at is not None\\n\\n    initial_revisions = MagicMock()\\n    initial_revisions.all.return_value = [(flow.id, flow.user_id, initial_updated_at)]\\n    page = MagicMock()\\n    page.all.return_value = [flow]\\n    final_revisions = MagicMock()\\n    final_revisions.all.return_value = [(flow.id, flow.user_id, initial_updated_at + timedelta(microseconds=1))]\\n    session = AsyncMock()\\n    session.exec.side_effect = [initial_revisions, page, final_revisions]\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"changed during packaging\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_fails_if_flow_owner_changes_before_final_revision_check() -> None:\\n    actor_id = uuid4()\\n    new_owner_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Changing owner\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n\\n    initial_revisions = MagicMock()\\n    initial_revisions.all.return_value = [(flow.id, actor_id, flow.updated_at)]\\n    page = MagicMock()\\n    page.all.return_value = [flow]\\n    final_revisions = MagicMock()\\n    final_revisions.all.return_value = [(flow.id, new_owner_id, flow.updated_at)]\\n    session = AsyncMock()\\n    session.exec.side_effect = [initial_revisions, page, final_revisions]\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"changed during packaging\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_detaches_and_preflights_outside_event_loop() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Worker\\\", user_id=actor_id)\\n    session = _session_with_flows([_flow(owner_id=actor_id, project_id=project_id)])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n    event_loop_thread = threading.get_ident()\\n    worker_threads: list[int] = []\\n\\n    from langflow.services.deployment_artifacts import builder\\n\\n    original_snapshot_rows = builder._snapshot_rows\\n\\n    def observed_snapshot_rows(*args, **kwargs):\\n        worker_threads.append(threading.get_ident())\\n        return original_snapshot_rows(*args, **kwargs)\\n\\n    with patch(f\\\"{MODULE}._snapshot_rows\\\", side_effect=observed_snapshot_rows):\\n        await _build_authorized(session=session, user=user, project=project)\\n\\n    assert worker_threads\\n    assert all(thread_id != event_loop_thread for thread_id in worker_threads)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_build_project_artifact_rejects_deep_data_before_recursive_scrubbing() -> None:\\n    actor_id = uuid4()\\n    project_id = uuid4()\\n    project = Folder(id=project_id, name=\\\"Deep\\\", user_id=actor_id)\\n    flow = _flow(owner_id=actor_id, project_id=project_id)\\n    nested: dict[str, object] = {}\\n    for _ in range(130):\\n        nested = {\\\"nested\\\": nested}\\n    flow.data = nested\\n    session = _session_with_flows([flow])\\n    user = SimpleNamespace(id=actor_id, is_superuser=False)\\n\\n    with pytest.raises(ProjectArtifactLimitError, match=\\\"nesting limit\\\"):\\n        await _build_authorized(session=session, user=user, project=project)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/deployment_artifacts/test_project_artifact_dependencies.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2c18ca2fcb2df510d326fc55809c2406666132c2be03495d3565ab1b3fccf399\",\"content\":\"\\\"\\\"\\\"Unit tests for MB/KB dependency resolution in the project-artifact builder.\\n\\nCovers the feature's core (`_collect_dependency_refs`, `_resolve_dependencies`) and the\\nC1 defense-in-depth secret scrub (`_scrub_backend_config`). These are targeted unit tests\\nagainst the private helpers so they don't have to thread the full `build_project_artifact`\\nmock sequence.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport io\\nimport json\\nimport zipfile\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.deployment_artifacts.builder import (\\n    ProjectArtifactError,\\n    ProjectArtifactLimits,\\n    _build_archive,\\n    _collect_dependency_refs,\\n    _FlowSnapshot,\\n    _resolve_dependencies,\\n    _scrub_backend_config,\\n)\\n\\n# Fake, non-functional fixture values (not real credentials): one variable-NAME pointer\\n# that must survive scrubbing, and one raw secret that must be stripped.\\n_KEY_VAR_NAME = \\\"CHROMA_API_KEY\\\"  # pragma: allowlist secret\\n_RAW_SECRET = \\\"sk-RAWLEAK\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n\\ndef _exec_result(rows):\\n    result = MagicMock()\\n    result.all.return_value = rows\\n    return result\\n\\n\\n# --- C1: backend_config secret scrub -----------------------------------------\\n\\n\\ndef test_scrub_backend_config_keeps_routing_and_variable_name_pointers():\\n    cfg = {\\\"mode\\\": \\\"cloud\\\", \\\"api_key_variable\\\": _KEY_VAR_NAME, \\\"tenant_variable\\\": \\\"CHROMA_TENANT\\\"}\\n    # variable-NAME pointers + routing are non-secret and must survive verbatim\\n    assert _scrub_backend_config(cfg) == cfg\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"secret_key\\\",\\n    [\\\"api_key\\\", \\\"apikey\\\", \\\"password\\\", \\\"auth_token\\\", \\\"connection_string\\\", \\\"db_secret\\\", \\\"private_key\\\"],\\n)\\ndef test_scrub_backend_config_strips_inlined_raw_secret(secret_key):\\n    scrubbed = _scrub_backend_config({\\\"mode\\\": \\\"cloud\\\", secret_key: _RAW_SECRET})\\n    assert scrubbed == {\\\"mode\\\": \\\"cloud\\\"}\\n    assert _RAW_SECRET not in json.dumps(scrubbed)\\n\\n\\ndef test_scrub_backend_config_handles_non_dict():\\n    assert _scrub_backend_config(None) == {}\\n    assert _scrub_backend_config(\\\"not-a-dict\\\") == {}\\n\\n\\ndef test_scrub_backend_config_drops_unknown_nested_values():\\n    cfg = {\\n        \\\"mode\\\": \\\"cloud\\\",\\n        \\\"cloud_host\\\": \\\"api.trychroma.com\\\",\\n        \\\"metadata\\\": {\\\"auth\\\": {\\\"token\\\": _RAW_SECRET}},\\n        \\\"notes\\\": [\\\"safe-looking\\\", {\\\"password\\\": _RAW_SECRET}],\\n    }\\n\\n    scrubbed = _scrub_backend_config(cfg)\\n\\n    assert scrubbed == {\\\"mode\\\": \\\"cloud\\\", \\\"cloud_host\\\": \\\"api.trychroma.com\\\"}\\n    assert _RAW_SECRET not in json.dumps(scrubbed)\\n\\n\\n# --- reference collection -----------------------------------------------------\\n\\n\\ndef test_collect_dependency_refs_reads_kb_mb_and_inline_kb():\\n    payload = {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"knowledge_base\\\": {\\\"value\\\": \\\"testKb\\\"}}}}},\\n                {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"memory_base\\\": {\\\"value\\\": \\\"testMb\\\"}}}}},\\n                {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"new_kb_name\\\": {\\\"value\\\": \\\"inlineKb\\\"}}}}},\\n                {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"unrelated\\\": {\\\"value\\\": \\\"ignore-me\\\"}}}}},\\n            ]\\n        }\\n    }\\n    mb_names, kb_names = _collect_dependency_refs(payload)\\n    assert mb_names == {\\\"testMb\\\"}\\n    assert kb_names == {\\\"testKb\\\", \\\"inlineKb\\\"}\\n\\n\\ndef test_collect_dependency_refs_tolerates_malformed_payload():\\n    assert _collect_dependency_refs({}) == (set(), set())\\n    assert _collect_dependency_refs({\\\"data\\\": {\\\"nodes\\\": [None, {}, {\\\"data\\\": None}]}}) == (set(), set())\\n\\n\\n# --- full resolution (shape + backing-KB dedup + secret strip) ----------------\\n\\n\\n@pytest.mark.asyncio\\nasync def test_resolve_dependencies_shapes_specs_and_strips_secret():\\n    owner_id = uuid4()\\n    flow_id = uuid4()\\n\\n    mb = SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        name=\\\"testMb\\\",\\n        kb_name=\\\"testmb_backing\\\",\\n        flow_id=flow_id,\\n        embedding_model=\\\"nomic-embed-text\\\",\\n        threshold=1,\\n        auto_capture=True,\\n        preprocessing=False,\\n        preproc_model=None,\\n        preproc_instructions=None,\\n        preproc_kill_phrase=None,\\n    )\\n    backing_kb = SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        name=\\\"testmb_backing\\\",\\n        backend_type=\\\"postgres\\\",\\n        backend_config={},\\n    )\\n    kb = SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        name=\\\"testKb\\\",\\n        backend_type=\\\"chroma\\\",\\n        # a raw api_key inlined next to the legitimate variable-name pointer\\n        backend_config={\\\"mode\\\": \\\"cloud\\\", \\\"api_key_variable\\\": _KEY_VAR_NAME, \\\"api_key\\\": _RAW_SECRET},\\n        model_selection={\\\"provider\\\": \\\"Ollama\\\", \\\"name\\\": \\\"nomic-embed-text\\\"},\\n        column_config=[{\\\"column_name\\\": \\\"text\\\", \\\"vectorize\\\": True, \\\"identifier\\\": True}],\\n    )\\n\\n    session = AsyncMock()\\n    # exec order in _resolve_dependencies: MemoryBase -> backing KB -> KB\\n    session.exec.side_effect = [_exec_result([mb]), _exec_result([backing_kb]), _exec_result([kb])]\\n\\n    snapshot = SimpleNamespace(\\n        owner_id=owner_id,\\n        payload={\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"knowledge_base\\\": {\\\"value\\\": \\\"testKb\\\"}}}}},\\n                    {\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"memory_base\\\": {\\\"value\\\": \\\"testMb\\\"}}}}},\\n                ]\\n            }\\n        },\\n    )\\n\\n    user = SimpleNamespace(id=owner_id)\\n    with patch(\\n        \\\"langflow.services.deployment_artifacts.builder.ensure_knowledge_base_permission\\\",\\n        new_callable=AsyncMock,\\n    ) as authorize:\\n        deps = await _resolve_dependencies(\\n            session,\\n            user=user,\\n            owner_id=owner_id,\\n            workspace_id=uuid4(),\\n            project_id=uuid4(),\\n            snapshots=(snapshot,),\\n        )\\n\\n    # MB is shaped and its backend is read from the backing KB\\n    assert [m[\\\"name\\\"] for m in deps[\\\"memoryBases\\\"]] == [\\\"testMb\\\"]\\n    assert deps[\\\"memoryBases\\\"][0][\\\"backendType\\\"] == \\\"postgres\\\"\\n    assert deps[\\\"memoryBases\\\"][0][\\\"flowId\\\"] == str(flow_id)\\n    # backing KB is NOT emitted as its own KB\\n    assert [k[\\\"name\\\"] for k in deps[\\\"knowledgeBases\\\"]] == [\\\"testKb\\\"]\\n\\n    kb_item = deps[\\\"knowledgeBases\\\"][0]\\n    assert kb_item[\\\"backendType\\\"] == \\\"chroma\\\"\\n    assert kb_item[\\\"embeddingProvider\\\"] == \\\"Ollama\\\"\\n    # C1: raw secret stripped; routing + variable-name pointer preserved\\n    assert kb_item[\\\"backendConfig\\\"] == {\\\"mode\\\": \\\"cloud\\\", \\\"api_key_variable\\\": _KEY_VAR_NAME}\\n    assert _RAW_SECRET not in json.dumps(deps)\\n    assert authorize.await_count == 2\\n    authorized_ids = {call.kwargs[\\\"kb_id\\\"] for call in authorize.await_args_list}\\n    assert authorized_ids == {mb.id, kb.id}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_resolve_dependencies_reads_typed_column_config_flags():\\n    \\\"\\\"\\\"KB rows can hold flags typed into the column table as strings; ``bool(\\\"false\\\")`` is True.\\\"\\\"\\\"\\n    owner_id = uuid4()\\n    kb = SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        name=\\\"typedKb\\\",\\n        backend_type=\\\"chroma\\\",\\n        backend_config={\\\"mode\\\": \\\"cloud\\\", \\\"api_key_variable\\\": _KEY_VAR_NAME},\\n        model_selection={\\\"provider\\\": \\\"Ollama\\\", \\\"name\\\": \\\"nomic-embed-text\\\"},\\n        column_config=[\\n            {\\\"column_name\\\": \\\"question\\\", \\\"vectorize\\\": True, \\\"identifier\\\": \\\"true\\\"},\\n            {\\\"column_name\\\": \\\"answer\\\", \\\"vectorize\\\": \\\"true\\\", \\\"identifier\\\": \\\"false\\\"},\\n            {\\\"column_name\\\": \\\"category\\\", \\\"vectorize\\\": \\\"False\\\", \\\"identifier\\\": \\\"\\\"},\\n        ],\\n    )\\n    session = AsyncMock()\\n    session.exec.side_effect = [_exec_result([kb])]\\n    snapshot = SimpleNamespace(\\n        owner_id=owner_id,\\n        payload={\\\"data\\\": {\\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"knowledge_base\\\": {\\\"value\\\": \\\"typedKb\\\"}}}}}]}},\\n    )\\n\\n    with patch(\\n        \\\"langflow.services.deployment_artifacts.builder.ensure_knowledge_base_permission\\\",\\n        new_callable=AsyncMock,\\n    ):\\n        deps = await _resolve_dependencies(\\n            session,\\n            user=SimpleNamespace(id=owner_id),\\n            owner_id=owner_id,\\n            workspace_id=uuid4(),\\n            project_id=uuid4(),\\n            snapshots=(snapshot,),\\n        )\\n\\n    assert deps[\\\"knowledgeBases\\\"][0][\\\"columnConfig\\\"] == [\\n        {\\\"columnName\\\": \\\"question\\\", \\\"vectorize\\\": True, \\\"identifier\\\": True},\\n        {\\\"columnName\\\": \\\"answer\\\", \\\"vectorize\\\": True, \\\"identifier\\\": False},\\n        {\\\"columnName\\\": \\\"category\\\", \\\"vectorize\\\": False, \\\"identifier\\\": False},\\n    ]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_resolve_dependencies_empty_when_no_refs_and_hits_no_db():\\n    session = AsyncMock()\\n    snapshot = SimpleNamespace(payload={\\\"data\\\": {\\\"nodes\\\": []}})\\n    owner_id = uuid4()\\n    deps = await _resolve_dependencies(\\n        session,\\n        user=SimpleNamespace(id=owner_id),\\n        owner_id=owner_id,\\n        workspace_id=uuid4(),\\n        project_id=uuid4(),\\n        snapshots=(snapshot,),\\n    )\\n    assert deps == {}\\n    session.exec.assert_not_awaited()\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.parametrize(\\\"dependency_type\\\", [\\\"knowledge_base\\\", \\\"memory_base\\\"])\\nasync def test_resolve_dependencies_fails_when_a_reference_is_missing(dependency_type):\\n    owner_id = uuid4()\\n    field_name = \\\"knowledge_base\\\" if dependency_type == \\\"knowledge_base\\\" else \\\"memory_base\\\"\\n    snapshot = SimpleNamespace(\\n        owner_id=owner_id,\\n        payload={\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {field_name: {\\\"value\\\": \\\"missing\\\"}}}}}],\\n            }\\n        },\\n    )\\n    session = AsyncMock()\\n    session.exec.return_value = _exec_result([])\\n\\n    with pytest.raises(ProjectArtifactError, match=r\\\"referenced .* not found\\\"):\\n        await _resolve_dependencies(\\n            session,\\n            user=SimpleNamespace(id=owner_id),\\n            owner_id=owner_id,\\n            workspace_id=uuid4(),\\n            project_id=uuid4(),\\n            snapshots=(snapshot,),\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_resolve_dependencies_fails_when_memory_base_backing_kb_is_missing():\\n    owner_id = uuid4()\\n    mb = SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        name=\\\"testMb\\\",\\n        kb_name=\\\"missing_backing\\\",\\n    )\\n    session = AsyncMock()\\n    session.exec.side_effect = [_exec_result([mb]), _exec_result([])]\\n    snapshot = SimpleNamespace(\\n        owner_id=owner_id,\\n        payload={\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"memory_base\\\": {\\\"value\\\": \\\"testMb\\\"}}}}}],\\n            }\\n        },\\n    )\\n\\n    with pytest.raises(ProjectArtifactError, match=\\\"backing Knowledge Base was not found\\\"):\\n        await _resolve_dependencies(\\n            session,\\n            user=SimpleNamespace(id=owner_id),\\n            owner_id=owner_id,\\n            workspace_id=uuid4(),\\n            project_id=uuid4(),\\n            snapshots=(snapshot,),\\n        )\\n\\n\\n@pytest.mark.asyncio\\n@pytest.mark.parametrize(\\\"dependency_type\\\", [\\\"knowledge_base\\\", \\\"memory_base\\\"])\\nasync def test_resolve_dependencies_rejects_local_chroma(dependency_type):\\n    owner_id = uuid4()\\n    kb = SimpleNamespace(\\n        id=uuid4(),\\n        user_id=owner_id,\\n        name=\\\"localKb\\\" if dependency_type == \\\"knowledge_base\\\" else \\\"memory_backing\\\",\\n        backend_type=\\\"chroma\\\",\\n        backend_config={},\\n        model_selection={\\\"provider\\\": \\\"OpenAI\\\", \\\"name\\\": \\\"text-embedding-3-small\\\"},\\n        column_config=[],\\n    )\\n    if dependency_type == \\\"knowledge_base\\\":\\n        rows = [_exec_result([kb])]\\n        field_name = \\\"knowledge_base\\\"\\n        reference_name = \\\"localKb\\\"\\n    else:\\n        mb = SimpleNamespace(\\n            id=uuid4(),\\n            user_id=owner_id,\\n            name=\\\"testMb\\\",\\n            kb_name=\\\"memory_backing\\\",\\n            flow_id=uuid4(),\\n            embedding_model=\\\"text-embedding-3-small\\\",\\n            threshold=1,\\n            auto_capture=True,\\n            preprocessing=False,\\n            preproc_model=None,\\n            preproc_instructions=None,\\n            preproc_kill_phrase=None,\\n        )\\n        rows = [_exec_result([mb]), _exec_result([kb])]\\n        field_name = \\\"memory_base\\\"\\n        reference_name = \\\"testMb\\\"\\n    session = AsyncMock()\\n    session.exec.side_effect = rows\\n    snapshot = SimpleNamespace(\\n        owner_id=owner_id,\\n        payload={\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {field_name: {\\\"value\\\": reference_name}}}}}],\\n            }\\n        },\\n    )\\n\\n    with (\\n        patch(\\n            \\\"langflow.services.deployment_artifacts.builder.ensure_knowledge_base_permission\\\",\\n            new_callable=AsyncMock,\\n        ),\\n        pytest.raises(ProjectArtifactError, match=\\\"local Chroma\\\"),\\n    ):\\n        await _resolve_dependencies(\\n            session,\\n            user=SimpleNamespace(id=owner_id),\\n            owner_id=owner_id,\\n            workspace_id=uuid4(),\\n            project_id=uuid4(),\\n            snapshots=(snapshot,),\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_resolve_dependencies_rejects_conflicting_same_name_across_flow_owners():\\n    first_owner = uuid4()\\n    second_owner = uuid4()\\n    rows = [\\n        SimpleNamespace(\\n            id=uuid4(),\\n            user_id=first_owner,\\n            name=\\\"sharedName\\\",\\n            backend_type=\\\"postgres\\\",\\n            backend_config={},\\n            model_selection={\\\"provider\\\": \\\"OpenAI\\\", \\\"name\\\": \\\"model-a\\\"},\\n            column_config=[],\\n        ),\\n        SimpleNamespace(\\n            id=uuid4(),\\n            user_id=second_owner,\\n            name=\\\"sharedName\\\",\\n            backend_type=\\\"postgres\\\",\\n            backend_config={},\\n            model_selection={\\\"provider\\\": \\\"OpenAI\\\", \\\"name\\\": \\\"model-b\\\"},\\n            column_config=[],\\n        ),\\n    ]\\n    session = AsyncMock()\\n    session.exec.return_value = _exec_result(rows)\\n    snapshots = tuple(\\n        SimpleNamespace(\\n            owner_id=owner_id,\\n            payload={\\n                \\\"data\\\": {\\n                    \\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"knowledge_base\\\": {\\\"value\\\": \\\"sharedName\\\"}}}}}],\\n                }\\n            },\\n        )\\n        for owner_id in (first_owner, second_owner)\\n    )\\n\\n    with (\\n        patch(\\n            \\\"langflow.services.deployment_artifacts.builder.ensure_knowledge_base_permission\\\",\\n            new_callable=AsyncMock,\\n        ),\\n        pytest.raises(ProjectArtifactError, match=\\\"ambiguous across flow owners\\\"),\\n    ):\\n        await _resolve_dependencies(\\n            session,\\n            user=SimpleNamespace(id=first_owner),\\n            owner_id=first_owner,\\n            workspace_id=uuid4(),\\n            project_id=uuid4(),\\n            snapshots=snapshots,\\n        )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_resolve_dependencies_ignores_unreferenced_cross_product_rows():\\n    first_owner = uuid4()\\n    second_owner = uuid4()\\n\\n    def kb(owner_id, name, model):\\n        return SimpleNamespace(\\n            id=uuid4(),\\n            user_id=owner_id,\\n            name=name,\\n            backend_type=\\\"postgres\\\",\\n            backend_config={},\\n            model_selection={\\\"provider\\\": \\\"OpenAI\\\", \\\"name\\\": model},\\n            column_config=[],\\n        )\\n\\n    session = AsyncMock()\\n    session.exec.return_value = _exec_result(\\n        [\\n            kb(first_owner, \\\"firstKb\\\", \\\"model-a\\\"),\\n            kb(second_owner, \\\"secondKb\\\", \\\"model-b\\\"),\\n            # Matches the query's owner/name sets but was not referenced by\\n            # this owner's flow and must not be packaged.\\n            kb(first_owner, \\\"secondKb\\\", \\\"wrong-model\\\"),\\n        ]\\n    )\\n    snapshots = (\\n        SimpleNamespace(\\n            owner_id=first_owner,\\n            payload={\\\"data\\\": {\\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"knowledge_base\\\": {\\\"value\\\": \\\"firstKb\\\"}}}}}]}},\\n        ),\\n        SimpleNamespace(\\n            owner_id=second_owner,\\n            payload={\\\"data\\\": {\\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"knowledge_base\\\": {\\\"value\\\": \\\"secondKb\\\"}}}}}]}},\\n        ),\\n    )\\n\\n    with patch(\\n        \\\"langflow.services.deployment_artifacts.builder.ensure_knowledge_base_permission\\\",\\n        new_callable=AsyncMock,\\n    ) as authorize:\\n        dependencies = await _resolve_dependencies(\\n            session,\\n            user=SimpleNamespace(id=first_owner),\\n            owner_id=first_owner,\\n            workspace_id=uuid4(),\\n            project_id=uuid4(),\\n            snapshots=snapshots,\\n        )\\n\\n    assert [item[\\\"name\\\"] for item in dependencies[\\\"knowledgeBases\\\"]] == [\\\"firstKb\\\", \\\"secondKb\\\"]\\n    assert authorize.await_count == 2\\n\\n\\ndef test_build_archive_emits_dependencies_in_a_v3_manifest():\\n    project_id = uuid4()\\n    snapshot = _FlowSnapshot(\\n        flow_id=uuid4(),\\n        name=\\\"Flow\\\",\\n        payload={\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}},\\n    )\\n    dependencies = {\\\"knowledgeBases\\\": [{\\\"name\\\": \\\"testKb\\\", \\\"backendType\\\": \\\"postgres\\\"}]}\\n\\n    artifact = _build_archive(\\n        project_id=project_id,\\n        project_name=\\\"Project\\\",\\n        snapshots=(snapshot,),\\n        limits=ProjectArtifactLimits(),\\n        dependencies=dependencies,\\n    )\\n\\n    with zipfile.ZipFile(io.BytesIO(artifact.content)) as archive:\\n        manifest = json.loads(archive.read(\\\"manifest.json\\\"))\\n    assert manifest[\\\"schema_version\\\"] == 3\\n    assert manifest[\\\"dependencies\\\"] == dependencies\\n    assert artifact.dependencies == dependencies\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/jobs/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/jobs/test_jobs_dedupe_scope.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"66740d6770d6b1c5550335a3e2af49c6fa5133ca2662cdf7192199dbf586f37e\",\"content\":\"\\\"\\\"\\\"create_job dedupe must be scoped per-user, not global.\\n\\nA client-controlled idempotency_key flows into dedupe_key. A GLOBAL dedupe\\ncount lets user A collide with / DoS user B's key (and the resulting error\\nleaks that a job with that key exists somewhere). The uniqueness must be scoped\\nto the owner.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.jobs.exceptions import DuplicateJobError\\nfrom langflow.services.jobs.service import JobService\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_dedupe_is_scoped_per_user():\\n    service = JobService()\\n    user_a = uuid4()\\n    user_b = uuid4()\\n\\n    # User A reserves a human-meaningful key.\\n    await service.create_job(job_id=uuid4(), flow_id=uuid4(), user_id=user_a, dedupe_key=\\\"daily-report\\\")\\n\\n    # User B using the SAME key must NOT collide with A's job.\\n    job_b = await service.create_job(job_id=uuid4(), flow_id=uuid4(), user_id=user_b, dedupe_key=\\\"daily-report\\\")\\n    assert job_b is not None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_dedupe_still_blocks_same_user():\\n    service = JobService()\\n    user_a = uuid4()\\n    await service.create_job(job_id=uuid4(), flow_id=uuid4(), user_id=user_a, dedupe_key=\\\"k1\\\")\\n\\n    # Same user, same key, still active -> duplicate is rejected (unchanged behaviour).\\n    with pytest.raises(DuplicateJobError):\\n        await service.create_job(job_id=uuid4(), flow_id=uuid4(), user_id=user_a, dedupe_key=\\\"k1\\\")\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_dedupe_ownerless_still_blocks():\\n    \\\"\\\"\\\"Single-tenant AUTO_LOGIN style (user_id=None) keeps a global dedupe floor.\\\"\\\"\\\"\\n    service = JobService()\\n    await service.create_job(job_id=uuid4(), flow_id=uuid4(), user_id=None, dedupe_key=\\\"kx\\\")\\n    with pytest.raises(DuplicateJobError):\\n        await service.create_job(job_id=uuid4(), flow_id=uuid4(), user_id=None, dedupe_key=\\\"kx\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/jobs/test_jobs_liveness.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8b7f5b26a89d5f44056cc1b7c97c39865806c10d9545b3cb001572cbe435611d\",\"content\":\"\\\"\\\"\\\"Store-layer liveness primitives: heartbeat, stale predicate, atomic attempt.\\n\\nThese back the lease+heartbeat reconciliation model. A reconciler must only\\nfail/requeue a job whose heartbeat is STALE (older than the lease TTL), never a\\nfresh one, and the retry-safe attempt bump must be atomic so two concurrent\\nreconcilers cannot push a job past max_attempts.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom datetime import datetime, timedelta, timezone\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom langflow.services.jobs.service import JobService\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_heartbeat_records_owner_and_timestamp():\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    before = datetime.now(timezone.utc)\\n    await service.heartbeat(job_id, owner=\\\"worker-A\\\")\\n    after = datetime.now(timezone.utc)\\n\\n    job = await service.get_job_by_job_id(job_id)\\n    meta = job.job_metadata or {}\\n    assert meta.get(\\\"owner\\\") == \\\"worker-A\\\"\\n    hb = datetime.fromisoformat(meta[\\\"heartbeat_at\\\"])\\n    assert before <= hb <= after\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_heartbeat_preserves_other_metadata():\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_metadata(job_id, {\\\"request\\\": {\\\"input_value\\\": \\\"hi\\\"}, \\\"retry_safe\\\": True})\\n\\n    await service.heartbeat(job_id, owner=\\\"worker-A\\\")\\n\\n    job = await service.get_job_by_job_id(job_id)\\n    meta = job.job_metadata or {}\\n    # Heartbeat must not clobber the persisted request / retry flag.\\n    assert meta[\\\"request\\\"] == {\\\"input_value\\\": \\\"hi\\\"}\\n    assert meta[\\\"retry_safe\\\"] is True\\n    assert meta[\\\"owner\\\"] == \\\"worker-A\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_is_lease_stale_fresh_vs_stale():\\n    service = JobService()\\n    fresh = uuid4()\\n    stale = uuid4()\\n    absent = uuid4()\\n    await service.create_job(job_id=fresh, flow_id=uuid4(), user_id=uuid4())\\n    await service.create_job(job_id=stale, flow_id=uuid4(), user_id=uuid4())\\n    await service.create_job(job_id=absent, flow_id=uuid4(), user_id=uuid4())\\n\\n    await service.heartbeat(fresh, owner=\\\"w1\\\")\\n    # Backdate the stale job's heartbeat well past the TTL.\\n    old = (datetime.now(timezone.utc) - timedelta(seconds=120)).isoformat()\\n    await service.update_job_metadata(stale, {\\\"owner\\\": \\\"w1\\\", \\\"heartbeat_at\\\": old})\\n\\n    fresh_job = await service.get_job_by_job_id(fresh)\\n    stale_job = await service.get_job_by_job_id(stale)\\n    absent_job = await service.get_job_by_job_id(absent)\\n\\n    assert service.is_lease_stale(fresh_job, lease_ttl_s=30.0) is False\\n    assert service.is_lease_stale(stale_job, lease_ttl_s=30.0) is True\\n    # No heartbeat ever recorded -> treated as stale (truly orphaned / never ran).\\n    assert service.is_lease_stale(absent_job, lease_ttl_s=30.0) is True\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_increment_attempt_atomic_is_conditional():\\n    \\\"\\\"\\\"Atomic attempt bump only succeeds when it observes the expected value.\\n\\n    This is the optimistic guard that prevents two concurrent reconcilers from\\n    both reading attempt=1 and both writing attempt=2 (a lost update).\\n    \\\"\\\"\\\"\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_metadata(job_id, {\\\"attempt\\\": 1, \\\"max_attempts\\\": 3})\\n\\n    # First bump from 1 -> 2 wins.\\n    assert await service.increment_attempt_if(job_id, expected=1, new=2) is True\\n    job = await service.get_job_by_job_id(job_id)\\n    assert job.job_metadata[\\\"attempt\\\"] == 2\\n\\n    # A racer that still thinks attempt==1 must NOT bump it again.\\n    assert await service.increment_attempt_if(job_id, expected=1, new=2) is False\\n    job = await service.get_job_by_job_id(job_id)\\n    assert job.job_metadata[\\\"attempt\\\"] == 2\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_increment_attempt_concurrent_only_one_wins():\\n    \\\"\\\"\\\"Under concurrent bumps from the same expected value exactly one wins.\\\"\\\"\\\"\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_metadata(job_id, {\\\"attempt\\\": 1, \\\"max_attempts\\\": 5})\\n\\n    results = await asyncio.gather(*(service.increment_attempt_if(job_id, expected=1, new=2) for _ in range(8)))\\n    assert results.count(True) == 1\\n    job = await service.get_job_by_job_id(job_id)\\n    assert job.job_metadata[\\\"attempt\\\"] == 2\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_claim_queued_lease_keeps_status_queued():\\n    \\\"\\\"\\\"A lease-claim of a QUEUED row stamps owner+heartbeat WITHOUT flipping status.\\n\\n    This is what makes a re-enqueue that crashes before the runner starts safe:\\n    the row stays QUEUED (re-runnable) instead of becoming a stranded IN_PROGRESS\\n    that the next sweep would fail worker_lost.\\n    \\\"\\\"\\\"\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    assert await service.claim_queued_lease(job_id, owner=\\\"w1\\\", lease_ttl_s=30.0) is True\\n    job = await service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.QUEUED  # NOT flipped to IN_PROGRESS\\n    assert (job.job_metadata or {}).get(\\\"owner\\\") == \\\"w1\\\"\\n    assert (job.job_metadata or {}).get(\\\"heartbeat_at\\\")\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_claim_queued_lease_single_flight_when_fresh():\\n    \\\"\\\"\\\"A second claimant loses while the first lease is still fresh (single-flight).\\\"\\\"\\\"\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    assert await service.claim_queued_lease(job_id, owner=\\\"w1\\\", lease_ttl_s=30.0) is True\\n    # w2 sees a fresh lease -> must not steal it.\\n    assert await service.claim_queued_lease(job_id, owner=\\\"w2\\\", lease_ttl_s=30.0) is False\\n    job = await service.get_job_by_job_id(job_id)\\n    assert (job.job_metadata or {}).get(\\\"owner\\\") == \\\"w1\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_claim_queued_lease_reclaimable_when_stale():\\n    \\\"\\\"\\\"Once the lease goes stale (claimant died before running) it is re-claimable.\\\"\\\"\\\"\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    old = (datetime.now(timezone.utc) - timedelta(seconds=300)).isoformat()\\n    await service.update_job_metadata(job_id, {\\\"owner\\\": \\\"dead\\\", \\\"heartbeat_at\\\": old})\\n\\n    # The row is still QUEUED with a STALE lease -> a fresh worker re-claims it.\\n    assert await service.claim_queued_lease(job_id, owner=\\\"w2\\\", lease_ttl_s=30.0) is True\\n    job = await service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.QUEUED\\n    assert (job.job_metadata or {}).get(\\\"owner\\\") == \\\"w2\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_claim_queued_lease_concurrent_only_one_wins():\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    results = await asyncio.gather(\\n        *(service.claim_queued_lease(job_id, owner=f\\\"w{i}\\\", lease_ttl_s=30.0) for i in range(8))\\n    )\\n    assert results.count(True) == 1\\n    job = await service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.QUEUED\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/jobs/test_jobs_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cced4fab0e420c5097122627d608a3798d929d8ed5da610783640d3a772b20fc\",\"content\":\"\\\"\\\"\\\"Store-layer tests for JobService. Run against the app's real (sqlite) DB via the client fixture.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.jobs.model import JobStatus, JobType, SignalType\\nfrom langflow.services.jobs.service import JobService\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_get_jobs_by_flow_id_orders_by_created_timestamp():\\n    \\\"\\\"\\\"Regression: get_jobs_by_flow_id ordered by Job.created_at, which does not exist.\\n\\n    Job has `created_timestamp`, not `created_at`, so the previous code raised\\n    AttributeError at query-build time. This test exercises the real query path.\\n    \\\"\\\"\\\"\\n    service = JobService()\\n    flow_id = uuid4()\\n    user_id = uuid4()\\n\\n    first = uuid4()\\n    second = uuid4()\\n    await service.create_job(job_id=first, flow_id=flow_id, job_type=JobType.WORKFLOW, user_id=user_id)\\n    await service.create_job(job_id=second, flow_id=flow_id, job_type=JobType.WORKFLOW, user_id=user_id)\\n\\n    # Must not raise AttributeError, and must return both jobs newest-first.\\n    jobs = await service.get_jobs_by_flow_id(flow_id, user_id)\\n    returned_ids = [job.job_id for job in jobs]\\n    assert first in returned_ids\\n    assert second in returned_ids\\n    # created_timestamp is the ordering key; both rows present is the core assertion.\\n    assert all(job.status == JobStatus.QUEUED for job in jobs)\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_create_job_stamps_end_user_in_metadata():\\n    \\\"\\\"\\\"P3: an identified serving run records its end user in job_metadata (no schema change).\\n\\n    user_id stays the executing SID so re-enqueue/resume can still fetch the SID-owned flow;\\n    the end user lives only in job_metadata['end_user_id'] where status/stop/resume isolate on it.\\n    \\\"\\\"\\\"\\n    service = JobService()\\n    job_id = uuid4()\\n    sid = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=sid, end_user_id=\\\"alice\\\")\\n\\n    fetched = await service.get_job_by_job_id(job_id)\\n    assert fetched.user_id == sid  # owner column is the SID, not the end user\\n    assert (fetched.job_metadata or {}).get(\\\"end_user_id\\\") == \\\"alice\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_create_job_without_end_user_writes_no_metadata_key():\\n    \\\"\\\"\\\"BC: a non-serving / anonymous / feature-off run stays byte-identical (no metadata).\\\"\\\"\\\"\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    fetched = await service.get_job_by_job_id(job_id)\\n    # No end_user_id passed -> job_metadata is not created at all (omit, don't store None).\\n    assert fetched.job_metadata is None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_end_user_survives_later_metadata_merge():\\n    \\\"\\\"\\\"The end-user stamp must survive submit's later shallow update_job_metadata(request=...).\\\"\\\"\\\"\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4(), end_user_id=\\\"alice\\\")\\n    await service.update_job_metadata(job_id, {\\\"request\\\": {\\\"input_value\\\": \\\"hi\\\"}})\\n\\n    fetched = await service.get_job_by_job_id(job_id)\\n    meta = fetched.job_metadata or {}\\n    assert meta.get(\\\"end_user_id\\\") == \\\"alice\\\"  # preserved by the shallow merge\\n    assert meta.get(\\\"request\\\") == {\\\"input_value\\\": \\\"hi\\\"}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_set_result_persists_blob():\\n    service = JobService()\\n    job_id = uuid4()\\n    flow_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    updated = await service.set_result(job_id, {\\\"output_text\\\": \\\"hello\\\", \\\"session_id\\\": \\\"s1\\\"})\\n    assert updated is not None\\n    assert updated.result == {\\\"output_text\\\": \\\"hello\\\", \\\"session_id\\\": \\\"s1\\\"}\\n\\n    fetched = await service.get_job_by_job_id(job_id)\\n    assert fetched.result == {\\\"output_text\\\": \\\"hello\\\", \\\"session_id\\\": \\\"s1\\\"}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_set_error_persists_blob():\\n    service = JobService()\\n    job_id = uuid4()\\n    flow_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    updated = await service.set_error(job_id, {\\\"type\\\": \\\"worker_lost\\\", \\\"message\\\": \\\"crash\\\"})\\n    assert updated is not None\\n    assert updated.error == {\\\"type\\\": \\\"worker_lost\\\", \\\"message\\\": \\\"crash\\\"}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_set_result_returns_none_for_missing_job():\\n    service = JobService()\\n    assert await service.set_result(uuid4(), {\\\"x\\\": 1}) is None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_append_event_assigns_monotonic_seq():\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    seq1 = await service.append_event(job_id, \\\"run_started\\\", {\\\"a\\\": 1})\\n    seq2 = await service.append_event(job_id, \\\"vertex_started\\\", {\\\"b\\\": 2})\\n    seq3 = await service.append_event(job_id, \\\"run_finished\\\", {\\\"c\\\": 3})\\n\\n    assert (seq1, seq2, seq3) == (1, 2, 3)\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_append_event_seq_is_per_job():\\n    service = JobService()\\n    job_a = uuid4()\\n    job_b = uuid4()\\n    await service.create_job(job_id=job_a, flow_id=uuid4(), user_id=uuid4())\\n    await service.create_job(job_id=job_b, flow_id=uuid4(), user_id=uuid4())\\n\\n    assert await service.append_event(job_a, \\\"x\\\", {}) == 1\\n    assert await service.append_event(job_b, \\\"x\\\", {}) == 1\\n    assert await service.append_event(job_a, \\\"x\\\", {}) == 2\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_read_events_after_seq_returns_ordered_tail():\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    await service.append_event(job_id, \\\"e1\\\", {\\\"i\\\": 1})\\n    await service.append_event(job_id, \\\"e2\\\", {\\\"i\\\": 2})\\n    await service.append_event(job_id, \\\"e3\\\", {\\\"i\\\": 3})\\n\\n    tail = await service.read_events(job_id, after_seq=1)\\n    assert [e.seq for e in tail] == [2, 3]\\n    assert [e.event_type for e in tail] == [\\\"e2\\\", \\\"e3\\\"]\\n    assert tail[0].payload == {\\\"i\\\": 2}\\n\\n    # after_seq=0 (or default) returns everything in order.\\n    all_events = await service.read_events(job_id, after_seq=0)\\n    assert [e.seq for e in all_events] == [1, 2, 3]\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_write_signal_then_unconsumed():\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    signal = await service.write_signal(job_id, SignalType.STOP)\\n    assert signal.signal_type == SignalType.STOP\\n    assert signal.consumed_at is None\\n\\n    pending = await service.unconsumed_signals(job_id)\\n    assert len(pending) == 1\\n    assert pending[0].signal_type == SignalType.STOP\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_unconsumed_signals_empty_when_none_written():\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    assert await service.unconsumed_signals(job_id) == []\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_sweep_orphans_fails_in_progress_jobs():\\n    \\\"\\\"\\\"On startup, any IN_PROGRESS job is an orphan from a crashed worker.\\n\\n    The default at-most-once policy marks it FAILED with a worker_lost error.\\n    QUEUED jobs are left alone (at-least-once: they get re-picked).\\n    \\\"\\\"\\\"\\n    service = JobService()\\n    orphan = uuid4()\\n    queued = uuid4()\\n    flow_id = uuid4()\\n    user_id = uuid4()\\n    await service.create_job(job_id=orphan, flow_id=flow_id, user_id=user_id)\\n    await service.update_job_status(orphan, JobStatus.IN_PROGRESS)\\n    await service.create_job(job_id=queued, flow_id=flow_id, user_id=user_id)\\n\\n    swept = await service.sweep_orphans()\\n    assert orphan in swept\\n    assert queued not in swept\\n\\n    orphan_job = await service.get_job_by_job_id(orphan)\\n    assert orphan_job.status == JobStatus.FAILED\\n    assert orphan_job.error == {\\\"type\\\": \\\"worker_lost\\\"}\\n    assert orphan_job.finished_timestamp is not None\\n\\n    # A reattacher must see a clean terminal event on the durable log.\\n    orphan_events = await service.read_events(orphan)\\n    assert len(orphan_events) == 1\\n    assert orphan_events[0].event_type == \\\"run_failed\\\"\\n    assert orphan_events[0].payload == {\\\"type\\\": \\\"worker_lost\\\"}\\n\\n    queued_job = await service.get_job_by_job_id(queued)\\n    assert queued_job.status == JobStatus.QUEUED\\n    # QUEUED jobs are untouched: no terminal event.\\n    assert await service.read_events(queued) == []\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_sweep_orphans_noop_when_clean():\\n    service = JobService()\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_status(job_id, JobStatus.COMPLETED, finished_timestamp=True)\\n\\n    assert await service.sweep_orphans() == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/jobs/test_sweep_liveness.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0a96e8ffc83821da12cdf0824b7f5f9789a64cd31c040b3a8e0930fc0df97d6c\",\"content\":\"\\\"\\\"\\\"sweep_orphans must be liveness-aware: never fail a job with a FRESH heartbeat.\\n\\nThe startup sweep ran on every worker boot and marked EVERY IN_PROGRESS row\\nFAILED(worker_lost). Under gunicorn -w N a booting worker B would flip worker\\nA's just-claimed, actively-running job FAILED mid-run. The fix: only reconcile\\nIN_PROGRESS rows whose heartbeat is stale/absent; a fresh heartbeat means a live\\nowner is running it and the sweep must leave it alone.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom datetime import datetime, timedelta, timezone\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom langflow.services.jobs.service import JobService\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_sweep_skips_fresh_heartbeat_job():\\n    \\\"\\\"\\\"A live in-progress job (fresh heartbeat) is NOT failed by the sweep.\\\"\\\"\\\"\\n    service = JobService()\\n    live = uuid4()\\n    dead = uuid4()\\n    await service.create_job(job_id=live, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_status(live, JobStatus.IN_PROGRESS)\\n    await service.heartbeat(live, owner=\\\"worker-A\\\")  # fresh: live owner running it\\n\\n    await service.create_job(job_id=dead, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_status(dead, JobStatus.IN_PROGRESS)\\n    old = (datetime.now(timezone.utc) - timedelta(seconds=300)).isoformat()\\n    await service.update_job_metadata(dead, {\\\"owner\\\": \\\"worker-B\\\", \\\"heartbeat_at\\\": old})\\n\\n    swept = await service.sweep_orphans(lease_ttl_s=30.0)\\n\\n    # Only the stale (dead) job is reconciled.\\n    assert dead in swept\\n    assert live not in swept\\n\\n    live_job = await service.get_job_by_job_id(live)\\n    assert live_job.status == JobStatus.IN_PROGRESS  # untouched, no phantom failure\\n    assert await service.read_events(live) == []  # no phantom terminal event injected\\n\\n    dead_job = await service.get_job_by_job_id(dead)\\n    assert dead_job.status == JobStatus.FAILED\\n    assert (dead_job.error or {}).get(\\\"type\\\") == \\\"worker_lost\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_sweep_still_fails_heartbeatless_in_progress():\\n    \\\"\\\"\\\"An IN_PROGRESS row that never recorded a heartbeat is a real orphan.\\\"\\\"\\\"\\n    service = JobService()\\n    orphan = uuid4()\\n    await service.create_job(job_id=orphan, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_status(orphan, JobStatus.IN_PROGRESS)\\n\\n    swept = await service.sweep_orphans(lease_ttl_s=30.0)\\n    assert orphan in swept\\n    job = await service.get_job_by_job_id(orphan)\\n    assert job.status == JobStatus.FAILED\\n    events = await service.read_events(orphan)\\n    assert len(events) == 1\\n    assert events[0].event_type == \\\"run_failed\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_concurrent_sweeps_reconcile_an_orphan_once():\\n    \\\"\\\"\\\"Two replicas racing the same stale row emit one terminal transition.\\\"\\\"\\\"\\n    service = JobService()\\n    orphan = uuid4()\\n    await service.create_job(job_id=orphan, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_status(orphan, JobStatus.IN_PROGRESS)\\n    old = (datetime.now(timezone.utc) - timedelta(seconds=300)).isoformat()\\n    await service.update_job_metadata(orphan, {\\\"owner\\\": \\\"dead-worker\\\", \\\"heartbeat_at\\\": old})\\n\\n    results = await asyncio.gather(\\n        service.sweep_orphans(lease_ttl_s=30.0),\\n        service.sweep_orphans(lease_ttl_s=30.0),\\n    )\\n\\n    assert sum(result.count(orphan) for result in results) == 1\\n    events = await service.read_events(orphan)\\n    assert [event.event_type for event in events] == [\\\"run_failed\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/storage/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/storage/test_local_storage_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"41efa1f355358987431fcd4741ddea348a924cc744b71a60f968df1bac773acd\",\"content\":\"\\\"\\\"\\\"Tests for LocalStorageService.\\\"\\\"\\\"\\n\\nfrom unittest.mock import Mock\\n\\nimport anyio\\nimport pytest\\nfrom langflow.services.storage.local import LocalStorageService\\n\\n\\n@pytest.fixture\\ndef mock_settings_service():\\n    \\\"\\\"\\\"Create a mock settings service.\\\"\\\"\\\"\\n    settings_service = Mock()\\n    settings_service.settings.config_dir = \\\"/tmp/langflow_test\\\"  # noqa: S108\\n    return settings_service\\n\\n\\n@pytest.fixture\\ndef mock_session_service():\\n    \\\"\\\"\\\"Create a mock session service.\\\"\\\"\\\"\\n    return Mock()\\n\\n\\n@pytest.fixture\\nasync def local_storage_service(mock_session_service, mock_settings_service, tmp_path):\\n    \\\"\\\"\\\"Create a LocalStorageService instance for testing.\\\"\\\"\\\"\\n    # Override the config dir to use tmp_path\\n    mock_settings_service.settings.config_dir = str(tmp_path)\\n    service = LocalStorageService(mock_session_service, mock_settings_service)\\n    yield service\\n    # Cleanup\\n    await service.teardown()\\n\\n\\n@pytest.mark.asyncio\\nclass TestLocalStorageServiceBasics:\\n    \\\"\\\"\\\"Test basic LocalStorageService functionality.\\\"\\\"\\\"\\n\\n    async def test_initialization(self, local_storage_service):\\n        \\\"\\\"\\\"Test that the service initializes correctly.\\\"\\\"\\\"\\n        assert local_storage_service.ready is True\\n        assert local_storage_service.data_dir is not None\\n\\n    async def test_build_full_path(self, local_storage_service):\\n        \\\"\\\"\\\"Test building full path for a file.\\\"\\\"\\\"\\n        flow_id = \\\"test_flow_123\\\"\\n        file_name = \\\"test_file.txt\\\"\\n\\n        full_path = local_storage_service.build_full_path(flow_id, file_name)\\n\\n        assert flow_id in full_path\\n        assert file_name in full_path\\n        assert full_path.endswith(\\\"test_file.txt\\\")\\n\\n    async def test_resolve_component_path(self, local_storage_service):\\n        \\\"\\\"\\\"Test resolving logical path to filesystem path.\\\"\\\"\\\"\\n        logical_path = \\\"flow_123/myfile.txt\\\"\\n\\n        resolved = local_storage_service.resolve_component_path(logical_path)\\n\\n        assert \\\"flow_123\\\" in resolved\\n        assert \\\"myfile.txt\\\" in resolved\\n        assert resolved.startswith(str(local_storage_service.data_dir))\\n\\n    async def test_resolve_component_path_malformed(self, local_storage_service):\\n        \\\"\\\"\\\"Test resolving malformed logical path returns it as-is.\\\"\\\"\\\"\\n        malformed_path = \\\"just_a_filename.txt\\\"\\n\\n        resolved = local_storage_service.resolve_component_path(malformed_path)\\n\\n        assert resolved == malformed_path\\n\\n\\n@pytest.mark.asyncio\\nclass TestLocalStorageServiceFileOperations:\\n    \\\"\\\"\\\"Test file operations in LocalStorageService.\\\"\\\"\\\"\\n\\n    async def test_save_and_get_file(self, local_storage_service):\\n        \\\"\\\"\\\"Test saving and retrieving a file.\\\"\\\"\\\"\\n        flow_id = \\\"test_flow\\\"\\n        file_name = \\\"test.txt\\\"\\n        data = b\\\"Hello, World!\\\"\\n\\n        # Save file\\n        await local_storage_service.save_file(flow_id, file_name, data)\\n\\n        # Retrieve file\\n        retrieved_data = await local_storage_service.get_file(flow_id, file_name)\\n\\n        assert retrieved_data == data\\n\\n    async def test_save_file_creates_directory(self, local_storage_service):\\n        \\\"\\\"\\\"Test that save_file creates the flow directory if it doesn't exist.\\\"\\\"\\\"\\n        flow_id = \\\"new_flow_dir\\\"\\n        file_name = \\\"test.txt\\\"\\n        data = b\\\"test content\\\"\\n\\n        # Ensure directory doesn't exist\\n        flow_dir = local_storage_service.data_dir / flow_id\\n        assert not await flow_dir.exists()\\n\\n        # Save file\\n        await local_storage_service.save_file(flow_id, file_name, data)\\n\\n        # Directory should now exist\\n        assert await flow_dir.exists()\\n        assert await flow_dir.is_dir()\\n\\n    async def test_save_file_overwrites_existing(self, local_storage_service):\\n        \\\"\\\"\\\"Test that saving a file with the same name overwrites the existing file.\\\"\\\"\\\"\\n        flow_id = \\\"test_flow\\\"\\n        file_name = \\\"overwrite.txt\\\"\\n\\n        # Save initial file\\n        await local_storage_service.save_file(flow_id, file_name, b\\\"original\\\")\\n\\n        # Overwrite with new data\\n        new_data = b\\\"updated content\\\"\\n        await local_storage_service.save_file(flow_id, file_name, new_data)\\n\\n        # Verify new data\\n        retrieved = await local_storage_service.get_file(flow_id, file_name)\\n        assert retrieved == new_data\\n\\n    async def test_get_file_not_found(self, local_storage_service):\\n        \\\"\\\"\\\"Test getting a file that doesn't exist raises FileNotFoundError.\\\"\\\"\\\"\\n        with pytest.raises(FileNotFoundError) as exc_info:\\n            await local_storage_service.get_file(\\\"nonexistent_flow\\\", \\\"nonexistent.txt\\\")\\n\\n        assert \\\"not found\\\" in str(exc_info.value).lower()\\n\\n    async def test_save_binary_file(self, local_storage_service):\\n        \\\"\\\"\\\"Test saving and retrieving binary data.\\\"\\\"\\\"\\n        flow_id = \\\"binary_flow\\\"\\n        file_name = \\\"binary.bin\\\"\\n        # Create some binary data\\n        data = bytes(range(256))\\n\\n        await local_storage_service.save_file(flow_id, file_name, data)\\n        retrieved = await local_storage_service.get_file(flow_id, file_name)\\n\\n        assert retrieved == data\\n\\n\\n@pytest.mark.asyncio\\nclass TestLocalStorageServiceListOperations:\\n    \\\"\\\"\\\"Test list operations in LocalStorageService.\\\"\\\"\\\"\\n\\n    async def test_list_files_empty_directory(self, local_storage_service):\\n        \\\"\\\"\\\"Test listing files in an empty/nonexistent directory returns empty list.\\\"\\\"\\\"\\n        # New implementation returns empty list instead of raising FileNotFoundError\\n        listed_files = await local_storage_service.list_files(\\\"nonexistent_flow\\\")\\n        assert listed_files == []\\n\\n    async def test_list_files_with_files(self, local_storage_service):\\n        \\\"\\\"\\\"Test listing files in a directory with files.\\\"\\\"\\\"\\n        flow_id = \\\"list_test_flow\\\"\\n        files = [\\\"file1.txt\\\", \\\"file2.txt\\\", \\\"file3.csv\\\"]\\n\\n        # Create files\\n        for file_name in files:\\n            await local_storage_service.save_file(flow_id, file_name, b\\\"content\\\")\\n\\n        # List files\\n        listed_files = await local_storage_service.list_files(flow_id)\\n\\n        assert len(listed_files) == 3\\n        assert set(listed_files) == set(files)\\n\\n    async def test_list_files_with_numeric_flow_id(self, local_storage_service):\\n        \\\"\\\"\\\"Test listing files with numeric flow_id (converted to string).\\\"\\\"\\\"\\n        flow_id = 12345\\n        file_name = \\\"test.txt\\\"\\n\\n        await local_storage_service.save_file(str(flow_id), file_name, b\\\"content\\\")\\n\\n        # List with numeric flow_id\\n        listed_files = await local_storage_service.list_files(flow_id)\\n\\n        assert file_name in listed_files\\n\\n    async def test_list_files_async_iteration(self, local_storage_service):\\n        \\\"\\\"\\\"Test that list_files uses async iteration correctly (folder_path.iterdir()).\\\"\\\"\\\"\\n        flow_id = \\\"async_iter_test\\\"\\n        files = [\\\"file1.txt\\\", \\\"file2.txt\\\", \\\"file3.txt\\\"]\\n\\n        # Create files\\n        for file_name in files:\\n            await local_storage_service.save_file(flow_id, file_name, b\\\"content\\\")\\n\\n        # List files - this tests the async for loop with folder_path.iterdir()\\n        listed_files = await local_storage_service.list_files(flow_id)\\n\\n        # Verify all files are listed (tests async iteration works)\\n        assert len(listed_files) == 3\\n        assert set(listed_files) == set(files)\\n\\n    async def test_list_files_excludes_directories(self, local_storage_service):\\n        \\\"\\\"\\\"Test that list_files only returns files, not directories.\\\"\\\"\\\"\\n        flow_id = \\\"dir_test\\\"\\n        file_name = \\\"test.txt\\\"\\n\\n        # Create a file via the service\\n        await local_storage_service.save_file(flow_id, file_name, b\\\"content\\\")\\n\\n        # Create a subdirectory directly on disk so list_files has something to skip.\\n        # Cannot route this through save_file: passing a slashed flow_id is the same\\n        # shape as the public-build arbitrary-file-read regression, so the storage\\n        # layer (correctly) rejects it.\\n        subdir_path = local_storage_service.data_dir / flow_id / \\\"subdir\\\"\\n        await subdir_path.mkdir(parents=True, exist_ok=True)\\n\\n        # List files - should only return files in the flow_id directory, not subdirectories\\n        listed_files = await local_storage_service.list_files(flow_id)\\n\\n        # Should only return the file in the root, not the subdirectory\\n        assert file_name in listed_files\\n        assert \\\"subdir\\\" not in listed_files\\n\\n\\n@pytest.mark.asyncio\\nclass TestLocalStorageServiceDeleteOperations:\\n    \\\"\\\"\\\"Test delete operations in LocalStorageService.\\\"\\\"\\\"\\n\\n    async def test_delete_existing_file(self, local_storage_service):\\n        \\\"\\\"\\\"Test deleting an existing file.\\\"\\\"\\\"\\n        flow_id = \\\"delete_flow\\\"\\n        file_name = \\\"to_delete.txt\\\"\\n\\n        # Create file\\n        await local_storage_service.save_file(flow_id, file_name, b\\\"delete me\\\")\\n\\n        # Verify it exists\\n        files = await local_storage_service.list_files(flow_id)\\n        assert file_name in files\\n\\n        # Delete file\\n        await local_storage_service.delete_file(flow_id, file_name)\\n\\n        # Verify it's gone\\n        with pytest.raises(FileNotFoundError):\\n            await local_storage_service.get_file(flow_id, file_name)\\n\\n    async def test_delete_nonexistent_file(self, local_storage_service):\\n        \\\"\\\"\\\"Test deleting a non-existent file doesn't raise an error.\\\"\\\"\\\"\\n        flow_id = \\\"delete_flow\\\"\\n\\n        # Create the flow directory first\\n        await local_storage_service.save_file(flow_id, \\\"dummy.txt\\\", b\\\"dummy\\\")\\n\\n        # Delete non-existent file should not raise\\n        await local_storage_service.delete_file(flow_id, \\\"nonexistent.txt\\\")\\n\\n    async def test_delete_multiple_files(self, local_storage_service):\\n        \\\"\\\"\\\"Test deleting multiple files from the same flow.\\\"\\\"\\\"\\n        flow_id = \\\"multi_delete_flow\\\"\\n        files = [\\\"file1.txt\\\", \\\"file2.txt\\\", \\\"file3.txt\\\"]\\n\\n        # Create files\\n        for file_name in files:\\n            await local_storage_service.save_file(flow_id, file_name, b\\\"content\\\")\\n\\n        # Delete all files\\n        for file_name in files:\\n            await local_storage_service.delete_file(flow_id, file_name)\\n\\n        # Verify all are gone\\n        listed_files = await local_storage_service.list_files(flow_id)\\n        assert len(listed_files) == 0\\n\\n\\n@pytest.mark.asyncio\\nclass TestLocalStorageServiceFileSizeOperations:\\n    \\\"\\\"\\\"Test file size operations in LocalStorageService.\\\"\\\"\\\"\\n\\n    async def test_get_file_size(self, local_storage_service):\\n        \\\"\\\"\\\"Test getting the size of a file.\\\"\\\"\\\"\\n        flow_id = \\\"size_flow\\\"\\n        file_name = \\\"sized.txt\\\"\\n        data = b\\\"A\\\" * 100  # 100 bytes\\n\\n        await local_storage_service.save_file(flow_id, file_name, data)\\n\\n        size = await local_storage_service.get_file_size(flow_id, file_name)\\n\\n        assert size == 100\\n\\n    async def test_get_file_size_empty_file(self, local_storage_service):\\n        \\\"\\\"\\\"Test getting the size of an empty file.\\\"\\\"\\\"\\n        flow_id = \\\"size_flow\\\"\\n        file_name = \\\"empty.txt\\\"\\n\\n        await local_storage_service.save_file(flow_id, file_name, b\\\"\\\")\\n\\n        size = await local_storage_service.get_file_size(flow_id, file_name)\\n\\n        assert size == 0\\n\\n    async def test_get_file_size_nonexistent(self, local_storage_service):\\n        \\\"\\\"\\\"Test getting size of non-existent file raises FileNotFoundError.\\\"\\\"\\\"\\n        with pytest.raises(FileNotFoundError):\\n            await local_storage_service.get_file_size(\\\"no_flow\\\", \\\"no_file.txt\\\")\\n\\n    async def test_get_file_size_large_file(self, local_storage_service):\\n        \\\"\\\"\\\"Test getting the size of a large file.\\\"\\\"\\\"\\n        flow_id = \\\"size_flow\\\"\\n        file_name = \\\"large.bin\\\"\\n        data = b\\\"X\\\" * (1024 * 1024)  # 1 MB\\n\\n        await local_storage_service.save_file(flow_id, file_name, data)\\n\\n        size = await local_storage_service.get_file_size(flow_id, file_name)\\n\\n        assert size == 1024 * 1024\\n\\n\\n@pytest.mark.asyncio\\nclass TestLocalStorageServiceTeardown:\\n    \\\"\\\"\\\"Test teardown operations in LocalStorageService.\\\"\\\"\\\"\\n\\n    async def test_teardown(self, local_storage_service):\\n        \\\"\\\"\\\"Test that teardown completes without errors.\\\"\\\"\\\"\\n        await local_storage_service.teardown()\\n        # Local storage teardown is a no-op, so just verify it doesn't raise\\n\\n\\n@pytest.mark.asyncio\\nclass TestLocalStorageServicePathTraversal:\\n    \\\"\\\"\\\"Regression tests for PVR0754098 \u2014 path traversal on read/delete/size endpoints.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        \\\"malicious_filename\\\",\\n        [\\n            \\\"../../../etc/passwd\\\",\\n            \\\"../other_flow/file.txt\\\",\\n            \\\"..\\\\\\\\..\\\\\\\\etc\\\\\\\\passwd\\\",\\n            \\\"..\\\",\\n            \\\"sub/dir.txt\\\",\\n        ],\\n    )\\n    async def test_get_file_rejects_traversal(self, local_storage_service, malicious_filename):\\n        with pytest.raises(ValueError, match=\\\"Invalid file\\\"):\\n            await local_storage_service.get_file(\\\"flow_a\\\", malicious_filename)\\n\\n    @pytest.mark.parametrize(\\n        \\\"malicious_filename\\\",\\n        [\\n            \\\"../../../etc/passwd\\\",\\n            \\\"../other_flow/file.txt\\\",\\n            \\\"..\\\",\\n        ],\\n    )\\n    async def test_delete_file_rejects_traversal(self, local_storage_service, malicious_filename):\\n        with pytest.raises(ValueError, match=\\\"Invalid file\\\"):\\n            await local_storage_service.delete_file(\\\"flow_a\\\", malicious_filename)\\n\\n    @pytest.mark.parametrize(\\n        \\\"malicious_filename\\\",\\n        [\\n            \\\"../../../etc/passwd\\\",\\n            \\\"../other_flow/file.txt\\\",\\n            \\\"..\\\",\\n        ],\\n    )\\n    async def test_get_file_size_rejects_traversal(self, local_storage_service, malicious_filename):\\n        with pytest.raises(ValueError, match=\\\"Invalid file\\\"):\\n            await local_storage_service.get_file_size(\\\"flow_a\\\", malicious_filename)\\n\\n    async def test_get_file_stream_rejects_traversal(self, local_storage_service):\\n        with pytest.raises(ValueError, match=\\\"Invalid file\\\"):\\n            # AsyncIterator functions don't raise until first iteration.\\n            async for _ in local_storage_service.get_file_stream(\\\"flow_a\\\", \\\"../escape.txt\\\"):\\n                pass\\n\\n    async def test_cross_flow_read_is_blocked(self, local_storage_service):\\n        \\\"\\\"\\\"Writing a file to flow_b then attempting to read it from flow_a must fail.\\\"\\\"\\\"\\n        await local_storage_service.save_file(\\\"flow_b\\\", \\\"secret.txt\\\", b\\\"hidden\\\")\\n\\n        with pytest.raises(ValueError, match=\\\"Invalid file\\\"):\\n            await local_storage_service.get_file(\\\"flow_a\\\", \\\"../flow_b/secret.txt\\\")\\n\\n    @pytest.mark.parametrize(\\n        \\\"malicious_flow_id\\\",\\n        [\\n            \\\"/etc\\\",\\n            \\\"..\\\",\\n            \\\"../other\\\",\\n            \\\"..\\\\\\\\other\\\",\\n            \\\"flow/sub\\\",\\n            \\\"flow\\\\\\\\sub\\\",\\n            \\\"with\\\\x00null\\\",\\n            \\\"\\\",\\n        ],\\n    )\\n    async def test_get_file_rejects_malicious_flow_id(self, local_storage_service, malicious_flow_id):\\n        # Pre-vuln: flow_id=\\\"/etc\\\" + file_name=\\\"passwd\\\" collapsed Path join to /etc/passwd\\n        # and the containment check passed because it was anchored at folder_path.\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await local_storage_service.get_file(malicious_flow_id, \\\"passwd\\\")\\n\\n    async def test_get_file_rejects_absolute_flow_id_collapse(self, local_storage_service):\\n        # Direct regression for the public-build arbitrary-file-read: ensure the\\n        # /etc/<file> shape is rejected even when the file would exist on disk.\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await local_storage_service.get_file(\\\"/etc\\\", \\\"hosts\\\")\\n\\n\\n@pytest.mark.asyncio\\nclass TestLocalStorageServiceEdgeCases:\\n    \\\"\\\"\\\"Test edge cases and error conditions.\\\"\\\"\\\"\\n\\n    async def test_save_file_with_special_characters(self, local_storage_service):\\n        \\\"\\\"\\\"Test saving files with special characters in names.\\\"\\\"\\\"\\n        flow_id = \\\"special_chars_flow\\\"\\n        file_name = \\\"test-file_2024.txt\\\"\\n        data = b\\\"special content\\\"\\n\\n        await local_storage_service.save_file(flow_id, file_name, data)\\n        retrieved = await local_storage_service.get_file(flow_id, file_name)\\n\\n        assert retrieved == data\\n\\n    async def test_save_file_with_unicode_content(self, local_storage_service):\\n        \\\"\\\"\\\"Test saving files with unicode content.\\\"\\\"\\\"\\n        flow_id = \\\"unicode_flow\\\"\\n        file_name = \\\"unicode.txt\\\"\\n        data = \\\"Hello \u4e16\u754c \ud83c\udf0d\\\".encode()\\n\\n        await local_storage_service.save_file(flow_id, file_name, data)\\n        retrieved = await local_storage_service.get_file(flow_id, file_name)\\n\\n        assert retrieved == data\\n        assert retrieved.decode(\\\"utf-8\\\") == \\\"Hello \u4e16\u754c \ud83c\udf0d\\\"\\n\\n    async def test_concurrent_file_operations(self, local_storage_service):\\n        \\\"\\\"\\\"Test concurrent file operations on different files.\\\"\\\"\\\"\\n        flow_id = \\\"concurrent_flow\\\"\\n        files = [f\\\"file_{i}.txt\\\" for i in range(10)]\\n\\n        # Save files concurrently\\n        async with anyio.create_task_group() as tg:\\n            for i, file_name in enumerate(files):\\n                data = f\\\"content_{i}\\\".encode()\\n                tg.start_soon(local_storage_service.save_file, flow_id, file_name, data)\\n\\n        # Verify all files were saved\\n        listed = await local_storage_service.list_files(flow_id)\\n        assert len(listed) == 10\\n\\n    async def test_concurrent_write_then_read(self, local_storage_service):\\n        \\\"\\\"\\\"Regression test for SystemError(11, 'Resource temporarily unavailable').\\n\\n        Under concurrent execution, aiofile/caio would leak kernel AIO contexts\\n        causing EAGAIN after ~150-200 runs. This test verifies that writing a file\\n        and immediately reading it back works reliably under concurrency with the\\n        aiofiles backend. See https://github.com/langflow-ai/langflow/issues/12414\\n        \\\"\\\"\\\"\\n        flow_id = \\\"concurrent_rw_flow\\\"\\n        num_files = 50\\n\\n        async def write_then_read(i: int) -> None:\\n            file_name = f\\\"file_{i}.bin\\\"\\n            data = f\\\"payload-{i}\\\".encode()\\n            await local_storage_service.save_file(flow_id, file_name, data)\\n            retrieved = await local_storage_service.get_file(flow_id, file_name)\\n            assert retrieved == data, f\\\"file_{i} content mismatch\\\"\\n\\n        async with anyio.create_task_group() as tg:\\n            for i in range(num_files):\\n                tg.start_soon(write_then_read, i)\\n\\n        listed = await local_storage_service.list_files(flow_id)\\n        assert len(listed) == num_files\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/storage/test_s3_dependency.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8ba34a13a7968bd1d8eec096c39a9ac2aa201922397ee9b2af013608075b3e2d\",\"content\":\"\\\"\\\"\\\"Packaging tests for the asynchronous S3 storage dependency.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport sys\\nfrom pathlib import Path\\n\\nif sys.version_info >= (3, 11):\\n    import tomllib\\nelse:\\n    import tomli as tomllib\\n\\n\\ndef test_async_s3_extras_use_aiobotocore_directly() -> None:\\n    pyproject_path = Path(__file__).resolve().parents[4] / \\\"base\\\" / \\\"pyproject.toml\\\"\\n    with pyproject_path.open(\\\"rb\\\") as pyproject_file:\\n        project = tomllib.load(pyproject_file)[\\\"project\\\"]\\n\\n    expected = \\\"aiobotocore>=3.7.0,<4.0.0\\\"\\n    assert expected in project[\\\"dependencies\\\"]\\n    assert project[\\\"optional-dependencies\\\"][\\\"aiobotocore\\\"] == [expected]\\n    assert project[\\\"optional-dependencies\\\"][\\\"aioboto3\\\"] == [expected]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/storage/test_s3_storage_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0557dbc8796d4f61ce842e981ccde10f1e93ec3bd03b469a21fbca09a1742d98\",\"content\":\"\\\"\\\"\\\"Unit tests for S3StorageService input validation.\\n\\nThese tests run offline. They assert that malformed flow_id / file_name values\\nare rejected at the storage layer BEFORE any AWS call is attempted, so the\\nboundary fix in chat.py is not the only line of defense for callers that reach\\nthe S3 backend with untrusted identifiers.\\n\\nRegression for GHSA-rcjh-r59h-gq37 (defense in depth at the S3 backend).\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import Mock\\n\\nimport pytest\\nfrom langflow.services.storage.s3 import S3StorageService\\n\\n\\n@pytest.fixture\\ndef mock_settings_service(tmp_path):\\n    \\\"\\\"\\\"Settings configured for S3 with a stable bucket / prefix.\\\"\\\"\\\"\\n    settings_service = Mock()\\n    settings_service.settings.config_dir = str(tmp_path)\\n    settings_service.settings.object_storage_bucket_name = \\\"langflow-unit-test-bucket\\\"\\n    settings_service.settings.object_storage_prefix = \\\"test-prefix\\\"\\n    settings_service.settings.object_storage_tags = {}\\n    return settings_service\\n\\n\\n@pytest.fixture\\ndef mock_session_service():\\n    return Mock()\\n\\n\\n@pytest.fixture\\ndef s3_service_offline(mock_session_service, mock_settings_service, monkeypatch):\\n    \\\"\\\"\\\"S3StorageService that fails loudly if any AWS call is attempted.\\n\\n    Validation MUST short-circuit before _get_client is invoked. If a test\\n    reaches this assertion, the validation guard is missing or bypassed.\\n    \\\"\\\"\\\"\\n    service = S3StorageService(mock_session_service, mock_settings_service)\\n\\n    def _no_aws_calls():\\n        msg = \\\"validation should have rejected this input before reaching S3\\\"\\n        raise AssertionError(msg)\\n\\n    monkeypatch.setattr(service, \\\"_get_client\\\", _no_aws_calls)\\n    return service\\n\\n\\ndef test_get_client_uses_aiobotocore_create_client(mock_session_service, mock_settings_service):\\n    service = S3StorageService(mock_session_service, mock_settings_service)\\n    session = Mock()\\n    service.session = session\\n\\n    client_context = service._get_client()\\n\\n    session.create_client.assert_called_once_with(\\\"s3\\\")\\n    assert client_context is session.create_client.return_value\\n\\n\\n_MALICIOUS_FLOW_IDS = [\\n    \\\"/etc\\\",\\n    \\\"..\\\",\\n    \\\"../other\\\",\\n    \\\"..\\\\\\\\other\\\",\\n    \\\"flow/sub\\\",\\n    \\\"flow\\\\\\\\sub\\\",\\n    \\\"with\\\\x00null\\\",\\n    \\\"\\\",\\n]\\n\\n_MALICIOUS_FILE_NAMES = [\\n    \\\"../passwd\\\",\\n    \\\"..\\\\\\\\passwd\\\",\\n    \\\"sub/passwd\\\",\\n    \\\"sub\\\\\\\\passwd\\\",\\n    \\\"with\\\\x00null\\\",\\n    \\\"\\\",\\n]\\n\\n\\n@pytest.mark.asyncio\\nclass TestS3StorageServicePathValidation:\\n    \\\"\\\"\\\"GHSA-rcjh-r59h-gq37: S3 backend must reject untrusted identifiers locally.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"malicious_flow_id\\\", _MALICIOUS_FLOW_IDS)\\n    async def test_get_file_rejects_malicious_flow_id(self, s3_service_offline, malicious_flow_id):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await s3_service_offline.get_file(malicious_flow_id, \\\"passwd\\\")\\n\\n    @pytest.mark.parametrize(\\\"malicious_flow_id\\\", _MALICIOUS_FLOW_IDS)\\n    async def test_save_file_rejects_malicious_flow_id(self, s3_service_offline, malicious_flow_id):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await s3_service_offline.save_file(malicious_flow_id, \\\"passwd\\\", b\\\"x\\\")\\n\\n    @pytest.mark.parametrize(\\\"malicious_flow_id\\\", _MALICIOUS_FLOW_IDS)\\n    async def test_delete_file_rejects_malicious_flow_id(self, s3_service_offline, malicious_flow_id):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await s3_service_offline.delete_file(malicious_flow_id, \\\"passwd\\\")\\n\\n    @pytest.mark.parametrize(\\\"malicious_flow_id\\\", _MALICIOUS_FLOW_IDS)\\n    async def test_get_file_size_rejects_malicious_flow_id(self, s3_service_offline, malicious_flow_id):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await s3_service_offline.get_file_size(malicious_flow_id, \\\"passwd\\\")\\n\\n    @pytest.mark.parametrize(\\\"malicious_flow_id\\\", _MALICIOUS_FLOW_IDS)\\n    async def test_get_file_stream_rejects_malicious_flow_id(self, s3_service_offline, malicious_flow_id):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            # AsyncIterator functions don't raise until first iteration.\\n            async for _ in s3_service_offline.get_file_stream(malicious_flow_id, \\\"passwd\\\"):\\n                pass\\n\\n    @pytest.mark.parametrize(\\\"malicious_flow_id\\\", _MALICIOUS_FLOW_IDS)\\n    async def test_list_files_rejects_malicious_flow_id(self, s3_service_offline, malicious_flow_id):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await s3_service_offline.list_files(malicious_flow_id)\\n\\n    @pytest.mark.parametrize(\\\"malicious_file_name\\\", _MALICIOUS_FILE_NAMES)\\n    async def test_get_file_rejects_malicious_file_name(self, s3_service_offline, malicious_file_name):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await s3_service_offline.get_file(\\\"legit_flow\\\", malicious_file_name)\\n\\n    @pytest.mark.parametrize(\\\"malicious_file_name\\\", _MALICIOUS_FILE_NAMES)\\n    async def test_save_file_rejects_malicious_file_name(self, s3_service_offline, malicious_file_name):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await s3_service_offline.save_file(\\\"legit_flow\\\", malicious_file_name, b\\\"x\\\")\\n\\n    async def test_get_file_rejects_absolute_flow_id_collapse(self, s3_service_offline):\\n        \\\"\\\"\\\"Direct regression for the public-build arbitrary-file-read at the S3 layer.\\n\\n        Pre-vuln: ``build_full_path(\\\"/etc\\\", \\\"hosts\\\")`` produced a key that resolved\\n        to an attacker-controlled S3 path. Validation must reject the shape.\\n        \\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            await s3_service_offline.get_file(\\\"/etc\\\", \\\"hosts\\\")\\n\\n\\nclass TestS3BuildFullPathValidation:\\n    \\\"\\\"\\\"``build_full_path`` is a public key builder, so it validates its own inputs.\\n\\n    Path shape must never stand in for authorization: a caller that composes a key without\\n    going through one of the file operations still cannot address a foreign namespace.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"malicious_flow_id\\\", [fid for fid in _MALICIOUS_FLOW_IDS if fid])\\n    def test_build_full_path_rejects_malicious_flow_id(self, s3_service_offline, malicious_flow_id):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            s3_service_offline.build_full_path(malicious_flow_id, \\\"file.txt\\\")\\n\\n    @pytest.mark.parametrize(\\\"malicious_file_name\\\", [name for name in _MALICIOUS_FILE_NAMES if name])\\n    def test_build_full_path_rejects_malicious_file_name(self, s3_service_offline, malicious_file_name):\\n        with pytest.raises(ValueError, match=\\\"Invalid\\\"):\\n            s3_service_offline.build_full_path(\\\"legit_flow\\\", malicious_file_name)\\n\\n    def test_build_full_path_allows_empty_file_name_for_listing_prefix(self, s3_service_offline):\\n        \\\"\\\"\\\"``list_files`` builds a prefix with an empty file name; that must keep working.\\\"\\\"\\\"\\n        assert s3_service_offline.build_full_path(\\\"legit_flow\\\", \\\"\\\") == \\\"test-prefix/legit_flow/\\\"\\n\\n    def test_build_full_path_accepts_legitimate_identifiers(self, s3_service_offline):\\n        assert s3_service_offline.build_full_path(\\\"legit_flow\\\", \\\"file.txt\\\") == \\\"test-prefix/legit_flow/file.txt\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tasks/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tasks/test_task_service_revoke.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3f6578464c45e648c4ecd311abae6f499ac33889c15877c26e6ebf7c52da7041\",\"content\":\"\\\"\\\"\\\"TaskService.revoke_task must bridge the synchronous Celery backend (#14943).\\n\\n``CeleryBackend.revoke_task`` publishes a revoke broadcast synchronously. The\\nservice used to ``await`` its return value directly, so every Celery-mode\\ncancellation (workflow stop, KB ingestion cancel, memory-base delete) raised\\n``TypeError: object NoneType can't be used in 'await' expression``.\\n\\nCelery is not a declared dependency, so the service-contract tests use a\\nsynchronous stand-in backend and run everywhere; the real-Celery tests skip\\nunless ``celery`` is installed.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport threading\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.task.service import TaskService\\n\\n\\nclass _SyncRevokeBackend:\\n    \\\"\\\"\\\"Stand-in with CeleryBackend's synchronous ``revoke_task`` contract.\\\"\\\"\\\"\\n\\n    name = \\\"celery\\\"\\n\\n    def __init__(self, *, error: Exception | None = None) -> None:\\n        self.error = error\\n        self.calls: list[tuple[str, int]] = []\\n\\n    def revoke_task(self, task_id: str) -> bool:\\n        self.calls.append((task_id, threading.get_ident()))\\n        if self.error is not None:\\n            raise self.error\\n        return True\\n\\n\\ndef _celery_task_service(monkeypatch, backend) -> TaskService:\\n    monkeypatch.setattr(\\\"langflow.services.task.service.CeleryBackend\\\", lambda: backend)\\n    return TaskService(SimpleNamespace(settings=SimpleNamespace(celery_enabled=True)))\\n\\n\\nasync def test_celery_revoke_accepts_synchronous_backend(monkeypatch):\\n    backend = _SyncRevokeBackend()\\n    service = _celery_task_service(monkeypatch, backend)\\n    task_id = uuid4()\\n\\n    assert await service.revoke_task(task_id) is True\\n    assert [sent_task_id for sent_task_id, _ in backend.calls] == [str(task_id)]\\n\\n\\nasync def test_celery_revoke_publishes_off_the_event_loop(monkeypatch):\\n    backend = _SyncRevokeBackend()\\n    service = _celery_task_service(monkeypatch, backend)\\n\\n    await service.revoke_task(uuid4())\\n\\n    [(_, publish_thread)] = backend.calls\\n    assert publish_thread != threading.get_ident()\\n\\n\\nasync def test_celery_revoke_propagates_broker_errors(monkeypatch):\\n    service = _celery_task_service(monkeypatch, _SyncRevokeBackend(error=ConnectionError(\\\"broker unavailable\\\")))\\n\\n    with pytest.raises(ConnectionError, match=\\\"broker unavailable\\\"):\\n        await service.revoke_task(uuid4())\\n\\n\\n@pytest.fixture\\ndef celery_app(monkeypatch):\\n    celery = pytest.importorskip(\\\"celery\\\")\\n    # In-memory transport: exercises the real AsyncResult -> control -> kombu\\n    # publish path with no external broker and no worker.\\n    with celery.Celery(\\\"revoke-test\\\", broker=\\\"memory://\\\", set_as_current=False) as app:\\n        monkeypatch.setattr(\\\"langflow.worker.celery_app\\\", app)\\n        yield app\\n\\n\\ndef test_celery_backend_reports_published_revoke(celery_app, monkeypatch):\\n    \\\"\\\"\\\"``AsyncResult.revoke`` returns ``None``; the backend must still report success.\\\"\\\"\\\"\\n    from langflow.services.task.backends.celery import CeleryBackend\\n\\n    sent = []\\n    original_revoke = celery_app.control.revoke\\n\\n    def spy_revoke(task_id, **kwargs):\\n        sent.append((task_id, kwargs.get(\\\"terminate\\\")))\\n        return original_revoke(task_id, **kwargs)\\n\\n    monkeypatch.setattr(celery_app.control, \\\"revoke\\\", spy_revoke)\\n    task_id = str(uuid4())\\n\\n    assert CeleryBackend().revoke_task(task_id) is True\\n    assert sent == [(task_id, True)]\\n\\n\\nasync def test_task_service_revoke_with_real_celery(celery_app):\\n    \\\"\\\"\\\"The reproduction from #14943, end to end through the real Celery backend.\\\"\\\"\\\"\\n    service = TaskService(SimpleNamespace(settings=SimpleNamespace(celery_enabled=True)))\\n\\n    assert service.backend.celery_app is celery_app\\n    assert await service.revoke_task(uuid4()) is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_application_span_filter.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e6f2915e3807588e234c8be0072e68c56f05338715ca87f3d888279ca068bde6\",\"content\":\"\\\"\\\"\\\"LLM trace content must never reach the operator's APM.\\n\\nLangflow installs a global tracer provider, so the LLM tracing integrations end up\\nexporting through it. The export path filters to application instrumentation only; these\\ntests pin that boundary from the APM side, without touching the vendor integrations.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom langflow.services.telemetry.opentelemetry import (\\n    APPLICATION_INSTRUMENTATION_SCOPES,\\n    APPLICATION_TRACER_NAME,\\n    ApplicationOnlySpanProcessor,\\n)\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\nSENTINEL = \\\"SENTINEL-PROMPT-TEXT-MUST-NOT-BE-EXPORTED\\\"\\n\\n# These ship in the same opentelemetry.instrumentation.* namespace as the application\\n# instrumentation and carry prompt/completion text.\\nLLM_SCOPES = [\\n    \\\"opentelemetry.instrumentation.openai\\\",\\n    \\\"opentelemetry.instrumentation.anthropic\\\",\\n    \\\"opentelemetry.instrumentation.langchain\\\",\\n    \\\"opentelemetry.instrumentation.bedrock\\\",\\n    \\\"opentelemetry.instrumentation.llamaindex\\\",\\n    # The LLM tracer integrations take their tracer under the bare \\\"langflow\\\" name.\\n    \\\"langflow\\\",\\n]\\n\\n\\n@pytest.fixture\\ndef exporter_and_provider():\\n    exporter = InMemorySpanExporter()\\n    provider = TracerProvider()\\n    provider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\n    yield exporter, provider\\n    provider.shutdown()\\n\\n\\ndef exported_span_names(exporter, provider):\\n    provider.force_flush()\\n    return [span.name for span in exporter.get_finished_spans()]\\n\\n\\n@pytest.mark.parametrize(\\\"scope\\\", LLM_SCOPES)\\ndef test_llm_scopes_are_not_exported(scope, exporter_and_provider):\\n    exporter, provider = exporter_and_provider\\n    span = provider.get_tracer(scope).start_span(\\\"chat\\\")\\n    span.set_attribute(\\\"gen_ai.prompt.0.content\\\", SENTINEL)\\n    span.end()\\n\\n    assert exported_span_names(exporter, provider) == []\\n\\n\\n@pytest.mark.parametrize(\\\"scope\\\", sorted(APPLICATION_INSTRUMENTATION_SCOPES))\\ndef test_application_scopes_are_exported(scope, exporter_and_provider):\\n    exporter, provider = exporter_and_provider\\n    provider.get_tracer(scope).start_span(\\\"GET /api/v1/flows\\\").end()\\n\\n    assert exported_span_names(exporter, provider) == [\\\"GET /api/v1/flows\\\"]\\n\\n\\ndef test_application_and_llm_spans_together_export_only_the_application_span(exporter_and_provider):\\n    \\\"\\\"\\\"The realistic case: a traced request that also runs an LLM component.\\\"\\\"\\\"\\n    exporter, provider = exporter_and_provider\\n\\n    server_span = provider.get_tracer(\\\"opentelemetry.instrumentation.fastapi\\\").start_span(\\\"POST /api/v1/run\\\")\\n    flow_span = provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow\\\")\\n    llm_span = provider.get_tracer(\\\"opentelemetry.instrumentation.openai\\\").start_span(\\\"openai.chat\\\")\\n    llm_span.set_attribute(\\\"gen_ai.prompt.0.content\\\", SENTINEL)\\n    llm_span.set_attribute(\\\"gen_ai.completion.0.content\\\", SENTINEL)\\n    llm_span.end()\\n    flow_span.end()\\n    server_span.end()\\n\\n    provider.force_flush()\\n    finished = exporter.get_finished_spans()\\n    assert sorted(s.name for s in finished) == [\\\"POST /api/v1/run\\\", \\\"flow\\\"]\\n    assert SENTINEL not in str([dict(s.attributes or {}) for s in finished])\\n\\n\\ndef test_child_of_a_dropped_span_is_promoted_to_a_root(exporter_and_provider):\\n    \\\"\\\"\\\"A sub-flow run from inside an agent component, with nothing exported above it.\\n\\n    The dropped LLM span was its only ancestor, so there is nothing left to hang it from and\\n    it becomes a root. Previously it kept pointing at the dropped parent and arrived at the\\n    APM referencing a span that never showed up.\\n    \\\"\\\"\\\"\\n    from opentelemetry.trace import use_span\\n\\n    exporter, provider = exporter_and_provider\\n    llm_span = provider.get_tracer(\\\"opentelemetry.instrumentation.openai\\\").start_span(\\\"openai.chat\\\")\\n    with use_span(llm_span, end_on_exit=False):\\n        provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow.execute\\\").end()\\n    llm_span.end()\\n\\n    provider.force_flush()\\n    finished = exporter.get_finished_spans()\\n    assert [s.name for s in finished] == [\\\"flow.execute\\\"]\\n    assert finished[0].parent is None, \\\"should be a root, not pointing at a span that was never exported\\\"\\n\\n\\ndef test_child_of_a_dropped_span_is_reparented_to_its_nearest_exported_ancestor(exporter_and_provider):\\n    \\\"\\\"\\\"The case that actually renders as a tree: an exported ancestor exists above the drop.\\n\\n    request -> openai.chat (dropped) -> flow.execute. The middle span never reaches the APM,\\n    so flow.execute has to attach to the request or the trace has a hole in it.\\n    \\\"\\\"\\\"\\n    from opentelemetry.trace import use_span\\n\\n    exporter, provider = exporter_and_provider\\n    request = provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"POST /api/v1/run\\\")\\n    with use_span(request, end_on_exit=False):\\n        llm_span = provider.get_tracer(\\\"opentelemetry.instrumentation.openai\\\").start_span(\\\"openai.chat\\\")\\n        with use_span(llm_span, end_on_exit=False):\\n            provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow.execute\\\").end()\\n        llm_span.end()\\n    request.end()\\n\\n    provider.force_flush()\\n    by_name = {s.name: s for s in exporter.get_finished_spans()}\\n    assert sorted(by_name) == [\\\"POST /api/v1/run\\\", \\\"flow.execute\\\"]\\n    assert by_name[\\\"flow.execute\\\"].parent is not None\\n    assert by_name[\\\"flow.execute\\\"].parent.span_id == by_name[\\\"POST /api/v1/run\\\"].context.span_id\\n    # Same trace throughout: this moves a span within its tree, it does not relocate it.\\n    assert by_name[\\\"flow.execute\\\"].context.trace_id == by_name[\\\"POST /api/v1/run\\\"].context.trace_id\\n\\n\\ndef test_a_span_under_two_dropped_levels_still_finds_the_exported_ancestor(exporter_and_provider):\\n    \\\"\\\"\\\"The walk has to continue past the first dropped parent, not stop at it.\\\"\\\"\\\"\\n    from opentelemetry.trace import use_span\\n\\n    exporter, provider = exporter_and_provider\\n    request = provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"POST /api/v1/run\\\")\\n    with use_span(request, end_on_exit=False):\\n        outer = provider.get_tracer(\\\"opentelemetry.instrumentation.openai\\\").start_span(\\\"openai.chat\\\")\\n        with use_span(outer, end_on_exit=False):\\n            inner = provider.get_tracer(\\\"opentelemetry.instrumentation.requests\\\").start_span(\\\"HTTP POST\\\")\\n            with use_span(inner, end_on_exit=False):\\n                provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow.execute\\\").end()\\n            inner.end()\\n        outer.end()\\n    request.end()\\n\\n    provider.force_flush()\\n    by_name = {s.name: s for s in exporter.get_finished_spans()}\\n    assert sorted(by_name) == [\\\"POST /api/v1/run\\\", \\\"flow.execute\\\"]\\n    assert by_name[\\\"flow.execute\\\"].parent.span_id == by_name[\\\"POST /api/v1/run\\\"].context.span_id\\n\\n\\ndef test_a_real_parent_is_left_alone(exporter_and_provider):\\n    \\\"\\\"\\\"The control. Nothing was dropped, so nothing should be rewritten.\\\"\\\"\\\"\\n    from opentelemetry.trace import use_span\\n\\n    exporter, provider = exporter_and_provider\\n    request = provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"POST /api/v1/run\\\")\\n    with use_span(request, end_on_exit=False):\\n        provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow.execute\\\").end()\\n    request.end()\\n\\n    provider.force_flush()\\n    by_name = {s.name: s for s in exporter.get_finished_spans()}\\n    assert by_name[\\\"flow.execute\\\"].parent.span_id == by_name[\\\"POST /api/v1/run\\\"].context.span_id\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"scope\\\",\\n    [\\n        \\\"opentelemetry.instrumentation.requests\\\",\\n        \\\"opentelemetry.instrumentation.urllib3\\\",\\n        \\\"opentelemetry.instrumentation.httpx\\\",\\n    ],\\n)\\ndef test_outbound_http_client_scopes_are_not_allowlisted(scope):\\n    \\\"\\\"\\\"The LLM vendor SDKs instrument these globally, so they carry outbound LLM API calls.\\n\\n    traceloop-sdk calls RequestsInstrumentor().instrument() and the urllib3/httpx equivalents\\n    with no tracer_provider, which binds them to our global provider. Allowlisting them would\\n    produce one span per outbound LLM call, carrying the request URL, and provider keys passed\\n    as query parameters would travel with it. httpx especially: it is the transport the openai\\n    and anthropic SDKs use. The runtime's own uses pass tracer_provider= explicitly.\\n    \\\"\\\"\\\"\\n    assert scope not in APPLICATION_INSTRUMENTATION_SCOPES\\n\\n\\ndef test_globally_instrumented_requests_does_not_reach_the_apm(exporter_and_provider):\\n    \\\"\\\"\\\"Drives the real RequestsInstrumentor the way traceloop-sdk does, against a local server.\\\"\\\"\\\"\\n    import http.server\\n    import socketserver\\n    import threading\\n\\n    import requests\\n    from opentelemetry.instrumentation.requests import RequestsInstrumentor\\n\\n    exporter, provider = exporter_and_provider\\n\\n    class Handler(http.server.BaseHTTPRequestHandler):\\n        def do_GET(self):\\n            self.send_response(200)\\n            self.end_headers()\\n            self.wfile.write(b\\\"{}\\\")\\n\\n        def log_message(self, *args):\\n            pass\\n\\n    server = socketserver.TCPServer((\\\"127.0.0.1\\\", 0), Handler)\\n    port = server.server_address[1]\\n    threading.Thread(target=server.serve_forever, daemon=True).start()\\n\\n    instrumentor = RequestsInstrumentor()\\n    was_instrumented = instrumentor.is_instrumented_by_opentelemetry\\n    if not was_instrumented:\\n        # No tracer_provider, exactly as traceloop-sdk does it: binds to the global provider.\\n        instrumentor.instrument(tracer_provider=provider)\\n    try:\\n        requests.get(f\\\"http://127.0.0.1:{port}/v1beta/models/gemini:generateContent?key={SENTINEL}\\\", timeout=10)\\n    finally:\\n        if not was_instrumented:\\n            instrumentor.uninstrument()\\n        server.shutdown()\\n\\n    assert exported_span_names(exporter, provider) == [], \\\"outbound LLM API call reached the APM\\\"\\n\\n\\ndef test_llm_tracer_name_is_not_allowlisted():\\n    \\\"\\\"\\\"The vendor integrations use the bare \\\"langflow\\\" tracer name; ours must differ.\\\"\\\"\\\"\\n    assert \\\"langflow\\\" not in APPLICATION_INSTRUMENTATION_SCOPES\\n    assert APPLICATION_TRACER_NAME in APPLICATION_INSTRUMENTATION_SCOPES\\n\\n\\ndef test_a_remote_parent_is_never_rewritten():\\n    \\\"\\\"\\\"The safety case. An unknown parent is not evidence of a drop.\\n\\n    A parent from another process is absent from this processor's map for the same reason a\\n    dropped one is: it was never seen at on_start. Treating absence as a drop would detach\\n    every distributed trace from its caller and re-root it here, replacing a correct\\n    cross-process link with an invented local one.\\n    \\\"\\\"\\\"\\n    from opentelemetry import trace as otel_trace\\n    from opentelemetry.trace import NonRecordingSpan, SpanContext, TraceFlags\\n\\n    exporter = InMemorySpanExporter()\\n    provider = TracerProvider()\\n    provider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\n\\n    remote = SpanContext(\\n        trace_id=0x1234567890ABCDEF1234567890ABCDEF,\\n        span_id=0x1122334455667788,\\n        is_remote=True,\\n        trace_flags=TraceFlags(TraceFlags.SAMPLED),\\n    )\\n    context = otel_trace.set_span_in_context(NonRecordingSpan(remote))\\n    provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow.execute\\\", context=context).end()\\n\\n    provider.force_flush()\\n    exported = exporter.get_finished_spans()\\n    assert len(exported) == 1\\n    assert exported[0].parent is not None, \\\"a remote parent must survive; it is not an orphan\\\"\\n    assert exported[0].parent.span_id == remote.span_id\\n    provider.shutdown()\\n\\n\\ndef test_a_remote_parent_above_a_dropped_span_is_preserved():\\n    \\\"\\\"\\\"A dropped local span must not sever an incoming distributed trace.\\\"\\\"\\\"\\n    from opentelemetry import trace as otel_trace\\n    from opentelemetry.trace import NonRecordingSpan, SpanContext, TraceFlags, use_span\\n\\n    exporter = InMemorySpanExporter()\\n    provider = TracerProvider()\\n    provider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\n\\n    remote = SpanContext(\\n        trace_id=0x1234567890ABCDEF1234567890ABCDEF,\\n        span_id=0x1122334455667788,\\n        is_remote=True,\\n        trace_flags=TraceFlags(TraceFlags.SAMPLED),\\n    )\\n    context = otel_trace.set_span_in_context(NonRecordingSpan(remote))\\n    dropped = provider.get_tracer(\\\"opentelemetry.instrumentation.openai\\\").start_span(\\\"openai.chat\\\", context=context)\\n    with use_span(dropped, end_on_exit=False):\\n        provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow.execute\\\").end()\\n    dropped.end()\\n\\n    provider.force_flush()\\n    exported = exporter.get_finished_spans()\\n    assert len(exported) == 1\\n    assert exported[0].parent is not None\\n    assert exported[0].parent.span_id == remote.span_id\\n    assert exported[0].context.trace_id == remote.trace_id\\n    provider.shutdown()\\n\\n\\ndef test_the_lineage_map_does_not_grow_across_runs():\\n    \\\"\\\"\\\"Entries are removed as spans end, including the dropped ones.\\n\\n    The map is the only state this processor keeps, so an entry that outlives its span is a\\n    leak in a long-running server.\\n    \\\"\\\"\\\"\\n    from opentelemetry.trace import use_span\\n\\n    exporter = InMemorySpanExporter()\\n    processor = ApplicationOnlySpanProcessor(exporter)\\n    provider = TracerProvider()\\n    provider.add_span_processor(processor)\\n\\n    for _ in range(25):\\n        request = provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"POST /api/v1/run\\\")\\n        with use_span(request, end_on_exit=False):\\n            llm = provider.get_tracer(\\\"opentelemetry.instrumentation.openai\\\").start_span(\\\"openai.chat\\\")\\n            with use_span(llm, end_on_exit=False):\\n                provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow.execute\\\").end()\\n            llm.end()\\n        request.end()\\n\\n    provider.force_flush()\\n    assert processor._lineage == {}, f\\\"{len(processor._lineage)} entries left behind\\\"\\n    provider.shutdown()\\n\\n\\ndef test_a_failure_while_reparenting_does_not_break_the_run():\\n    \\\"\\\"\\\"Telemetry must not raise into the code that ended the span.\\n\\n    The SDK does not catch exceptions from a span processor: it lets them out of\\n    ``Span.end()`` and into the caller. Re-parenting reaches into SDK internals, so if a\\n    future release changes them, the failure has to stay inside the processor. The span is\\n    still exported, with whatever parent it already had.\\n\\n    Corrupts the processor's own lineage map rather than patching the SDK, so the failure is\\n    raised by the real code path under test.\\n    \\\"\\\"\\\"\\n    from opentelemetry.trace import use_span\\n\\n    exporter = InMemorySpanExporter()\\n    processor = ApplicationOnlySpanProcessor(exporter)\\n    provider = TracerProvider()\\n    provider.add_span_processor(processor)\\n\\n    request = provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"POST /api/v1/run\\\")\\n    with use_span(request, end_on_exit=False):\\n        llm = provider.get_tracer(\\\"opentelemetry.instrumentation.openai\\\").start_span(\\\"openai.chat\\\")\\n        with use_span(llm, end_on_exit=False):\\n            child = provider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow.execute\\\")\\n            # The walk unpacks each entry as (exported, parent_id, context). A short tuple\\n            # raises there, which is what a changed SDK looks like from inside this code.\\n            # It has to be falsy in position 0 too, or the caller returns before the walk.\\n            processor._lineage[llm.get_span_context().span_id] = (False,)\\n            child.end()  # must not raise\\n        llm.end()\\n    request.end()\\n\\n    provider.force_flush()\\n    exported = [s for s in exporter.get_finished_spans() if s.name == \\\"flow.execute\\\"]\\n    assert len(exported) == 1, \\\"the span must still be exported when re-parenting fails\\\"\\n    provider.shutdown()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_component_inputs_splitting.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d6a011d86c4663498365c370838e9e9ce59399860524f0eeed4ae17cadce2287\",\"content\":\"\\\"\\\"\\\"Tests for ComponentInputsPayload splitting logic.\\\"\\\"\\\"\\n\\nfrom hypothesis import given\\nfrom hypothesis import strategies as st\\nfrom langflow.services.telemetry.schema import MAX_TELEMETRY_URL_SIZE, ComponentInputsPayload\\n\\n\\ndef test_chunk_fields_exist():\\n    \\\"\\\"\\\"Test that chunk_index and total_chunks fields exist on payload.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={\\\"input1\\\": \\\"value1\\\"},\\n        chunk_index=0,\\n        total_chunks=1,\\n    )\\n\\n    assert payload.chunk_index == 0\\n    assert payload.total_chunks == 1\\n\\n\\ndef test_chunk_fields_serialize_with_aliases():\\n    \\\"\\\"\\\"Test that chunk fields use camelCase aliases.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={\\\"input1\\\": \\\"value1\\\"},\\n        chunk_index=2,\\n        total_chunks=5,\\n    )\\n\\n    data = payload.model_dump(by_alias=True)\\n    assert data[\\\"chunkIndex\\\"] == 2\\n    assert data[\\\"totalChunks\\\"] == 5\\n\\n\\ndef test_chunk_fields_optional_default_none():\\n    \\\"\\\"\\\"Test that chunk fields default to None when not provided.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={\\\"input1\\\": \\\"value1\\\"},\\n    )\\n\\n    assert payload.chunk_index is None\\n    assert payload.total_chunks is None\\n\\n\\ndef test_calculate_url_size_returns_integer():\\n    \\\"\\\"\\\"Test that _calculate_url_size returns a positive integer.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={\\\"input1\\\": \\\"value1\\\"},\\n    )\\n\\n    size = payload._calculate_url_size()\\n    assert isinstance(size, int)\\n    assert size > 0\\n\\n\\ndef test_calculate_url_size_accounts_for_encoding():\\n    \\\"\\\"\\\"Test that URL size accounts for special character encoding.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={\\\"input1\\\": \\\"value with spaces & special=chars\\\"},\\n    )\\n\\n    size = payload._calculate_url_size()\\n    # Size should be larger than raw dict due to JSON serialization and URL encoding\\n    import orjson\\n\\n    serialized_size = len(orjson.dumps(payload.component_inputs).decode(\\\"utf-8\\\"))\\n    assert size > serialized_size\\n\\n\\ndef test_calculate_url_size_includes_all_fields():\\n    \\\"\\\"\\\"Test that URL size includes all payload fields.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={\\\"input1\\\": \\\"value1\\\"},\\n        chunk_index=0,\\n        total_chunks=1,\\n    )\\n\\n    size = payload._calculate_url_size()\\n    # Size should include base URL + all query params\\n    assert size > 100  # Reasonable minimum for all fields\\n\\n\\ndef test_split_if_needed_returns_list():\\n    \\\"\\\"\\\"Test that split_if_needed returns a list of payloads.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={\\\"input1\\\": \\\"value1\\\"},\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n    assert isinstance(result, list)\\n    assert len(result) > 0\\n\\n\\ndef test_split_if_needed_no_split_returns_single_payload():\\n    \\\"\\\"\\\"Test that small payload returns single payload unchanged.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={\\\"input1\\\": \\\"value1\\\"},\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n    assert len(result) == 1\\n    assert result[0].component_run_id == \\\"test-run-id\\\"\\n    assert result[0].component_inputs == {\\\"input1\\\": \\\"value1\\\"}\\n\\n\\ndef test_split_if_needed_no_split_has_no_chunk_metadata():\\n    \\\"\\\"\\\"Test that single payload has None for chunk fields.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={\\\"input1\\\": \\\"value1\\\"},\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n    assert result[0].chunk_index is None\\n    assert result[0].total_chunks is None\\n\\n\\ndef test_split_if_needed_splits_large_payload():\\n    \\\"\\\"\\\"Test that large payload is split into multiple chunks.\\\"\\\"\\\"\\n    # Create payload with many inputs that will exceed 2000 chars\\n    large_inputs = {f\\\"input_{i}\\\": \\\"x\\\" * 100 for i in range(50)}\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=large_inputs,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n    assert len(result) > 1  # Should be split\\n\\n\\ndef test_split_preserves_fixed_fields():\\n    \\\"\\\"\\\"Test that all chunks have identical fixed fields.\\\"\\\"\\\"\\n    large_inputs = {f\\\"input_{i}\\\": \\\"x\\\" * 100 for i in range(50)}\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=large_inputs,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    for chunk in result:\\n        assert chunk.component_run_id == \\\"test-run-id\\\"\\n        assert chunk.component_id == \\\"test-comp-id\\\"\\n        assert chunk.component_name == \\\"TestComponent\\\"\\n\\n\\ndef test_split_chunk_metadata_correct():\\n    \\\"\\\"\\\"Test that chunk_index and total_chunks are correct.\\\"\\\"\\\"\\n    large_inputs = {f\\\"input_{i}\\\": \\\"x\\\" * 100 for i in range(50)}\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=large_inputs,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    # Check chunk indices are sequential\\n    for i, chunk in enumerate(result):\\n        assert chunk.chunk_index == i\\n        assert chunk.total_chunks == len(result)\\n\\n\\ndef test_split_preserves_all_data():\\n    \\\"\\\"\\\"Test that merging all chunks recreates original data.\\\"\\\"\\\"\\n    large_inputs = {f\\\"input_{i}\\\": f\\\"value_{i}\\\" for i in range(50)}\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=large_inputs,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    # Merge all chunk inputs\\n    merged_inputs = {}\\n    for chunk in result:\\n        merged_inputs.update(chunk.component_inputs)\\n\\n    assert merged_inputs == large_inputs\\n\\n\\ndef test_split_chunks_respect_max_size():\\n    \\\"\\\"\\\"Test that all chunks respect max URL size.\\\"\\\"\\\"\\n    large_inputs = {f\\\"input_{i}\\\": \\\"x\\\" * 100 for i in range(50)}\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=large_inputs,\\n    )\\n\\n    max_size = MAX_TELEMETRY_URL_SIZE\\n    result = payload.split_if_needed(max_url_size=max_size)\\n\\n    for chunk in result:\\n        chunk_size = chunk._calculate_url_size()\\n        assert chunk_size <= max_size\\n\\n\\ndef test_split_truncates_oversized_single_field():\\n    \\\"\\\"\\\"Test that single field exceeding max size gets truncated.\\\"\\\"\\\"\\n    # Create input with single field that's too large\\n    oversized_value = \\\"x\\\" * 3000\\n    inputs = {\\\"large_field\\\": oversized_value}\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=inputs,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    # Should return single payload with truncated value\\n    assert len(result) == 1\\n    chunk_inputs = result[0].component_inputs\\n    assert \\\"large_field\\\" in chunk_inputs\\n    assert len(chunk_inputs[\\\"large_field\\\"]) < len(oversized_value)\\n    assert \\\"...[truncated]\\\" in chunk_inputs[\\\"large_field\\\"]\\n\\n    # Verify the chunk respects max size\\n    chunk_size = result[0]._calculate_url_size()\\n    assert chunk_size <= MAX_TELEMETRY_URL_SIZE\\n\\n\\ndef test_split_handles_empty_inputs():\\n    \\\"\\\"\\\"Test that empty inputs dict returns single payload.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs={},\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n    assert len(result) == 1\\n    assert result[0].component_inputs == {}\\n\\n\\ndef test_split_truncates_oversized_non_string_field():\\n    \\\"\\\"\\\"Test that non-string oversized field gets converted to string and truncated.\\\"\\\"\\\"\\n    # Create input with single non-string field that's too large\\n    oversized_list = [{\\\"key\\\": \\\"value\\\" * 100} for _ in range(100)]\\n    inputs = {\\\"large_list\\\": oversized_list}\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=inputs,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    # Should return single payload with truncated value\\n    assert len(result) == 1\\n    chunk_inputs = result[0].component_inputs\\n    assert \\\"large_list\\\" in chunk_inputs\\n\\n    # Value should be converted to string and truncated\\n    assert isinstance(chunk_inputs[\\\"large_list\\\"], str)\\n    assert \\\"...[truncated]\\\" in chunk_inputs[\\\"large_list\\\"]\\n\\n    # Verify the chunk respects max size\\n    chunk_size = result[0]._calculate_url_size()\\n    assert chunk_size <= MAX_TELEMETRY_URL_SIZE\\n\\n\\ndef test_split_truncates_oversized_field_in_multi_field_payload():\\n    \\\"\\\"\\\"Test that oversized field gets truncated when splitting multi-field payload.\\\"\\\"\\\"\\n    # Create inputs with normal fields and one oversized field\\n    inputs = {\\n        \\\"normal1\\\": \\\"value1\\\",\\n        \\\"normal2\\\": \\\"value2\\\",\\n        \\\"huge_field\\\": \\\"x\\\" * 5000,\\n        \\\"normal3\\\": \\\"value3\\\",\\n    }\\n\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=inputs,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    # Should be split into multiple chunks\\n    assert len(result) > 1\\n\\n    # All chunks must respect max size\\n    for chunk in result:\\n        chunk_size = chunk._calculate_url_size()\\n        assert chunk_size <= MAX_TELEMETRY_URL_SIZE\\n\\n    # The huge_field should be truncated\\n    huge_field_found = False\\n    for chunk in result:\\n        if \\\"huge_field\\\" in chunk.component_inputs:\\n            huge_field_found = True\\n            assert \\\"...[truncated]\\\" in chunk.component_inputs[\\\"huge_field\\\"]\\n            assert len(chunk.component_inputs[\\\"huge_field\\\"]) < 5000\\n\\n    assert huge_field_found, \\\"huge_field should be in one of the chunks\\\"\\n\\n\\n# Hypothesis property-based tests\\n\\n\\n@given(st.dictionaries(st.text(min_size=1, max_size=50), st.text(max_size=200), min_size=1))\\ndef test_property_split_never_exceeds_max_size(inputs_dict):\\n    \\\"\\\"\\\"Property: Every chunk URL must be <= max_url_size.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=inputs_dict,\\n    )\\n\\n    max_size = MAX_TELEMETRY_URL_SIZE\\n    result = payload.split_if_needed(max_url_size=max_size)\\n\\n    for chunk in result:\\n        chunk_size = chunk._calculate_url_size()\\n        assert chunk_size <= max_size, f\\\"Chunk size {chunk_size} exceeds max {max_size}\\\"\\n\\n\\n@given(st.dictionaries(st.text(min_size=1, max_size=50), st.text(max_size=200), min_size=1))\\ndef test_property_split_preserves_all_data(inputs_dict):\\n    \\\"\\\"\\\"Property: Merging all chunks recreates original inputs (unless truncated).\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=inputs_dict,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    # Merge all chunk inputs\\n    merged_inputs = {}\\n    has_truncation = False\\n    for chunk in result:\\n        chunk_inputs = chunk.component_inputs\\n        for key, value in chunk_inputs.items():\\n            if isinstance(value, str) and \\\"...[truncated]\\\" in value:\\n                has_truncation = True\\n            merged_inputs[key] = value\\n\\n    # If no truncation, data should be preserved\\n    if not has_truncation:\\n        assert merged_inputs == inputs_dict\\n\\n\\n@given(\\n    st.dictionaries(st.text(min_size=1, max_size=50), st.text(max_size=200), min_size=1),\\n    st.text(min_size=1, max_size=100),\\n    st.text(min_size=1, max_size=100),\\n    st.text(min_size=1, max_size=100),\\n)\\ndef test_property_fixed_fields_identical_across_chunks(inputs_dict, run_id, comp_id, comp_name):\\n    \\\"\\\"\\\"Property: All chunks have identical fixed fields.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=run_id,\\n        component_id=comp_id,\\n        component_name=comp_name,\\n        component_inputs=inputs_dict,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    for chunk in result:\\n        assert chunk.component_run_id == run_id\\n        assert chunk.component_id == comp_id\\n        assert chunk.component_name == comp_name\\n\\n\\n@given(st.dictionaries(st.text(min_size=1, max_size=50), st.text(max_size=200), min_size=1))\\ndef test_property_chunk_indices_sequential(inputs_dict):\\n    \\\"\\\"\\\"Property: chunk_index goes 0,1,2... and total_chunks is correct.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=inputs_dict,\\n    )\\n\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    if len(result) == 1:\\n        # Single payload should have None chunk metadata\\n        assert result[0].chunk_index is None\\n        assert result[0].total_chunks is None\\n    else:\\n        # Multiple chunks should have sequential indices\\n        for i, chunk in enumerate(result):\\n            assert chunk.chunk_index == i\\n            assert chunk.total_chunks == len(result)\\n\\n\\n@given(\\n    st.dictionaries(\\n        st.text(\\n            min_size=1,\\n            max_size=50,\\n            alphabet=st.characters(blacklist_categories=(\\\"Cs\\\", \\\"Cc\\\"), blacklist_characters=\\\"\\\\x00\\\"),\\n        ),\\n        st.text(\\n            max_size=200,\\n            alphabet=st.characters(blacklist_categories=(\\\"Cs\\\", \\\"Cc\\\"), blacklist_characters=\\\"\\\\x00\\\"),\\n        ),\\n        min_size=1,\\n    )\\n)\\ndef test_property_handles_special_characters(inputs_dict):\\n    \\\"\\\"\\\"Property: URL encoding doesn't break splitting logic.\\\"\\\"\\\"\\n    payload = ComponentInputsPayload(\\n        component_run_id=\\\"test-run-id\\\",\\n        component_id=\\\"test-comp-id\\\",\\n        component_name=\\\"TestComponent\\\",\\n        component_inputs=inputs_dict,\\n    )\\n\\n    # Should not raise any exceptions\\n    result = payload.split_if_needed(max_url_size=MAX_TELEMETRY_URL_SIZE)\\n\\n    # All chunks should be valid\\n    assert len(result) > 0\\n    for chunk in result:\\n        assert chunk.component_run_id == \\\"test-run-id\\\"\\n        assert isinstance(chunk.component_inputs, dict)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_db_pool_metrics.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"317720854dd3c6c9591d1dc4056ecfb14c76f564585fbaf898598a7626bba573\",\"content\":\"\\\"\\\"\\\"Connection-pool saturation is only observable while the pool is live.\\n\\nThese drive a real ``AsyncEngine`` -- the same type ``get_db_service().engine`` returns -- with\\nreal connections, rather than a stand-in exposing a ``.pool`` attribute. That matters: the\\ninstrumentation reads ``engine.pool`` and silently returns when it is absent, so a stand-in\\nwould keep every assertion green even if ``AsyncEngine`` did not proxy the attribute at all and\\nthe feature were a no-op in production.\\n\\\"\\\"\\\"\\n\\nimport tempfile\\nfrom pathlib import Path\\n\\nfrom langflow.services.telemetry.opentelemetry import DB_POOL_GAUGES, instrument_db_pool\\nfrom opentelemetry.sdk.metrics import MeterProvider\\nfrom opentelemetry.sdk.metrics.export import InMemoryMetricReader\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\nfrom sqlalchemy.pool import AsyncAdaptedQueuePool\\n\\n\\ndef _collect(reader) -> dict[str, float]:\\n    # None rather than an empty payload is what the reader returns when nothing was ever\\n    # registered, which is itself the assertion in the StaticPool case below.\\n    data = reader.get_metrics_data()\\n    if data is None:\\n        return {}\\n    return {\\n        metric.name: point.value\\n        for rm in (data.resource_metrics or [])\\n        for sm in rm.scope_metrics\\n        for metric in sm.metrics\\n        for point in metric.data.data_points\\n    }\\n\\n\\ndef _provider_with_reader() -> tuple[MeterProvider, InMemoryMetricReader]:\\n    reader = InMemoryMetricReader()\\n    return MeterProvider(metric_readers=[reader], shutdown_on_exit=False), reader\\n\\n\\nasync def test_checkout_from_a_real_async_engine_moves_the_in_use_gauge():\\n    \\\"\\\"\\\"The signal an operator needs during a pool-exhaustion incident.\\n\\n    Uses a counting pool explicitly, because the counters only exist on the queue pools that\\n    real Postgres deployments get.\\n    \\\"\\\"\\\"\\n    provider, reader = _provider_with_reader()\\n    engine = create_async_engine(\\n        \\\"sqlite+aiosqlite:///:memory:\\\", poolclass=AsyncAdaptedQueuePool, pool_size=5, max_overflow=2\\n    )\\n    try:\\n        instrument_db_pool(provider, engine)\\n        assert _collect(reader)[\\\"langflow_db_pool_connections_in_use\\\"] == 0\\n\\n        async with engine.connect():\\n            assert _collect(reader)[\\\"langflow_db_pool_connections_in_use\\\"] == 1\\n\\n        # Returned to the pool, not destroyed: in use falls back, idle now holds it.\\n        collected = _collect(reader)\\n        assert collected[\\\"langflow_db_pool_connections_in_use\\\"] == 0\\n        assert collected[\\\"langflow_db_pool_connections_idle\\\"] == 1\\n        assert collected[\\\"langflow_db_pool_size\\\"] == 5\\n        # A pool well within its size reports a negative overflow internally; the gauge must\\n        # not surface that, or a dashboard shows -5 as the healthy baseline.\\n        assert collected[\\\"langflow_db_pool_overflow\\\"] == 0\\n    finally:\\n        await engine.dispose()\\n        provider.shutdown()\\n\\n\\nasync def test_pools_that_count_nothing_register_nothing():\\n    \\\"\\\"\\\"SQLite is the default and uses StaticPool, which has none of these counters.\\n\\n    Registering a gauge whose callback cannot work would emit a permanently-zero series and,\\n    worse, make a pool look healthy on a deployment where it is simply not measured.\\n    \\\"\\\"\\\"\\n    provider, reader = _provider_with_reader()\\n    engine = create_async_engine(\\\"sqlite+aiosqlite:///:memory:\\\")\\n    try:\\n        instrument_db_pool(provider, engine)\\n        assert not [name for name, *_ in DB_POOL_GAUGES if name in _collect(reader)]\\n    finally:\\n        await engine.dispose()\\n        provider.shutdown()\\n\\n\\nasync def test_instrumenting_without_a_provider_is_a_noop():\\n    \\\"\\\"\\\"Nothing exported means nothing to register on; must not raise.\\\"\\\"\\\"\\n    engine = create_async_engine(\\\"sqlite+aiosqlite:///:memory:\\\", poolclass=AsyncAdaptedQueuePool)\\n    try:\\n        instrument_db_pool(None, engine)\\n    finally:\\n        await engine.dispose()\\n\\n\\nasync def test_gauges_follow_the_pool_across_a_dispose():\\n    \\\"\\\"\\\"dispose() swaps in a fresh pool rather than resetting one in place.\\n\\n    A gauge holding the original pool would answer for the dead one forever, reporting a\\n    permanently healthy zero after any reconnect -- the exact false-healthy reading these\\n    exist to prevent.\\n    \\\"\\\"\\\"\\n    provider, reader = _provider_with_reader()\\n    engine = create_async_engine(\\\"sqlite+aiosqlite:///:memory:\\\", poolclass=AsyncAdaptedQueuePool, pool_size=5)\\n    try:\\n        instrument_db_pool(provider, engine)\\n        original_pool = engine.pool\\n\\n        await engine.dispose()\\n        assert engine.pool is not original_pool, \\\"sqlalchemy no longer swaps the pool; test premise is stale\\\"\\n\\n        async with engine.connect():\\n            assert _collect(reader)[\\\"langflow_db_pool_connections_in_use\\\"] == 1\\n    finally:\\n        await engine.dispose()\\n        provider.shutdown()\\n\\n\\nasync def test_file_backed_sqlite_is_instrumented():\\n    \\\"\\\"\\\"The default deployment is file-backed SQLite, which does get a counting pool.\\n\\n    Only ``:memory:`` uses StaticPool, so this is the branch that actually runs for most\\n    installs and it must not be left to the memory-only tests above.\\n    \\\"\\\"\\\"\\n    provider, reader = _provider_with_reader()\\n    with tempfile.TemporaryDirectory() as tmp:\\n        engine = create_async_engine(f\\\"sqlite+aiosqlite:///{Path(tmp) / 'langflow.db'}\\\", pool_size=20, max_overflow=30)\\n        try:\\n            instrument_db_pool(provider, engine)\\n            collected = _collect(reader)\\n            assert collected[\\\"langflow_db_pool_size\\\"] == 20\\n            # overflow() starts at -pool_size on a queue pool; the clamp must hide that.\\n            assert collected[\\\"langflow_db_pool_overflow\\\"] == 0\\n        finally:\\n            await engine.dispose()\\n            provider.shutdown()\\n\\n\\nasync def test_gauges_retarget_when_the_whole_engine_is_replaced():\\n    \\\"\\\"\\\"Re-instrumenting with a replacement engine must move the gauges to it.\\n\\n    OpenTelemetry de-duplicates observable gauges by name, so the second registration returns\\n    the existing instrument and drops the new callbacks. If the engine were captured per\\n    callback, the gauges would keep reporting on the first, disposed engine -- a permanently\\n    healthy pool for one that no longer exists. Swapping only ``engine.pool`` does not catch\\n    this; the whole engine has to be replaced.\\n    \\\"\\\"\\\"\\n    provider, reader = _provider_with_reader()\\n    first = create_async_engine(\\\"sqlite+aiosqlite:///:memory:\\\", poolclass=AsyncAdaptedQueuePool, pool_size=5)\\n    second = create_async_engine(\\\"sqlite+aiosqlite:///:memory:\\\", poolclass=AsyncAdaptedQueuePool, pool_size=5)\\n    try:\\n        instrument_db_pool(provider, first)\\n        instrument_db_pool(provider, second)\\n\\n        # Hold a connection on the replacement only. A gauge still bound to `first` reports 0.\\n        async with second.connect():\\n            assert _collect(reader)[\\\"langflow_db_pool_connections_in_use\\\"] == 1\\n    finally:\\n        await first.dispose()\\n        await second.dispose()\\n        provider.shutdown()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_dependency_spans.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bd7e018878809e22112f5621c71f8e09406d3415b321b39631310d4e824610a1\",\"content\":\"\\\"\\\"\\\"Dependency spans and sampling.\\n\\nDatabase spans are allowlisted for export; the LLM vendor transports deliberately are not.\\nSampling needs no code of ours, so the check here is that it stays that way.\\n\\nEach case runs in a subprocess because the tracer provider is process-global.\\n\\\"\\\"\\\"\\n\\nimport gzip\\nimport http.server\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\nimport threading\\n\\nimport pytest\\nfrom lfx.observability import APPLICATION_INSTRUMENTATION_SCOPES\\n\\n\\nclass _Collector(http.server.BaseHTTPRequestHandler):\\n    def do_POST(self) -> None:\\n        body = self.rfile.read(int(self.headers.get(\\\"Content-Length\\\", 0)))\\n        if self.headers.get(\\\"Content-Encoding\\\") == \\\"gzip\\\":\\n            body = gzip.decompress(body)\\n        self.server.requests.append((self.path, body))\\n        self.send_response(200)\\n        self.send_header(\\\"Content-Length\\\", \\\"0\\\")\\n        self.end_headers()\\n\\n    def log_message(self, *args) -> None:\\n        pass\\n\\n\\n@pytest.fixture\\ndef collector():\\n    server = http.server.HTTPServer((\\\"127.0.0.1\\\", 0), _Collector)\\n    server.requests = []\\n    thread = threading.Thread(target=server.serve_forever, daemon=True)\\n    thread.start()\\n    yield server\\n    server.shutdown()\\n    server.server_close()\\n    thread.join(timeout=5)\\n\\n\\ndef test_outbound_http_scopes_stay_out_of_the_allowlist():\\n    \\\"\\\"\\\"Redacting URLs does not make the LLM transports safe to export; that boundary stands.\\\"\\\"\\\"\\n    for scope in (\\n        \\\"opentelemetry.instrumentation.httpx\\\",\\n        \\\"opentelemetry.instrumentation.requests\\\",\\n        \\\"opentelemetry.instrumentation.urllib3\\\",\\n    ):\\n        assert scope not in APPLICATION_INSTRUMENTATION_SCOPES\\n\\n\\ndef test_database_spans_are_allowlisted():\\n    \\\"\\\"\\\"The scope is on the list. What it carries is the next test, which is the part that matters.\\\"\\\"\\\"\\n    assert \\\"opentelemetry.instrumentation.sqlalchemy\\\" in APPLICATION_INSTRUMENTATION_SCOPES\\n\\n\\n# Admitting the SQLAlchemy scope rests on one claim: db.statement keeps bound parameters as\\n# placeholders, so row values stay in the database. That claim is why chat message text is\\n# considered safe from this signal, and it was carried by a comment and a membership check\\n# rather than by running a query. This runs the query.\\n#\\n# The membership check alone passes in every way this can actually break: the instrumentor not\\n# installed, instrument() raising and being swallowed, or a future version rendering literals\\n# into the statement.\\nDB_SENTINEL = \\\"SENTINEL-chat-row-value-QQQ\\\"\\n\\nDB_SPAN_PROBE = f\\\"\\\"\\\"\\nimport json, sys\\n\\nfrom opentelemetry import trace\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\nfrom sqlalchemy import create_engine, text\\n\\nfrom lfx.observability import ApplicationOnlySpanProcessor, instrument_database\\n\\nexporter = InMemorySpanExporter()\\nprovider = TracerProvider()\\nprovider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\ntrace.set_tracer_provider(provider)\\n\\nSENTINEL = {DB_SENTINEL!r}\\nliteral = len(sys.argv) > 1 and sys.argv[1] == \\\"literal\\\"\\n\\nengine = create_engine(\\\"sqlite+pysqlite:///:memory:\\\")\\ninstrument_database(engine)\\n\\nwith engine.connect() as connection:\\n    connection.execute(text(\\\"CREATE TABLE messagetable (text VARCHAR)\\\"))\\n    if literal:\\n        # What a regression to literal rendering would look like. Never how the runtime writes.\\n        connection.execute(text(\\\"INSERT INTO messagetable (text) VALUES ('\\\" + SENTINEL + \\\"')\\\"))\\n    else:\\n        # A bound parameter, the shape the runtime uses to store a chat message.\\n        connection.execute(text(\\\"INSERT INTO messagetable (text) VALUES (:text)\\\"), {{\\\"text\\\": SENTINEL}})\\n    connection.commit()\\n\\nprovider.force_flush()\\nspans = [\\n    {{\\n        \\\"name\\\": s.name,\\n        \\\"scope\\\": s.instrumentation_scope.name if s.instrumentation_scope else None,\\n        \\\"attrs\\\": {{k: str(v) for k, v in (s.attributes or {{}}).items()}},\\n    }}\\n    for s in exporter.get_finished_spans()\\n]\\nprint(\\\"PROBE_RESULT \\\" + json.dumps({{\\\"spans\\\": spans}}))\\n\\\"\\\"\\\"  # noqa: S608 - the interpolated INSERT is the control, not a query we run\\n\\n\\ndef _run_db_probe(*args: str) -> list[dict]:\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", DB_SPAN_PROBE, *args],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=300,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    # Not next(): a probe that exits cleanly without printing would raise StopIteration here and\\n    # take its own stdout and stderr with it, which is the context needed to see why.\\n    lines = [ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\")]\\n    assert lines, f\\\"probe printed no result.\\\\nstdout:\\\\n{completed.stdout}\\\\nstderr:\\\\n{completed.stderr}\\\"\\n    spans = json.loads(lines[0].removeprefix(\\\"PROBE_RESULT \\\"))[\\\"spans\\\"]\\n    return [s for s in spans if s[\\\"scope\\\"] == \\\"opentelemetry.instrumentation.sqlalchemy\\\"]\\n\\n\\ndef test_a_database_span_carries_the_placeholder_and_not_the_row_value():\\n    \\\"\\\"\\\"The claim that admits this scope, run rather than asserted.\\n\\n    A chat message is stored through a bound parameter, so if the instrumentation rendered\\n    values into ``db.statement`` the conversation would reach the operator's APM on a scope we\\n    allowlisted on the strength of it not doing that.\\n    \\\"\\\"\\\"\\n    db_spans = _run_db_probe()\\n\\n    # Not a formality: without it this passes when the instrumentor is missing entirely.\\n    assert db_spans, \\\"no sqlalchemy spans were exported\\\"\\n\\n    statements = [s[\\\"attrs\\\"].get(\\\"db.statement\\\", \\\"\\\") for s in db_spans]\\n    # The placeholder, not just the verb: a statement truncated to \\\"INSERT INTO messagetable\\\"\\n    # would satisfy a looser check and satisfy the sentinel check for the wrong reason.\\n    assert any(\\\"INSERT INTO messagetable (text) VALUES (?)\\\" in statement for statement in statements), statements\\n    assert DB_SENTINEL not in json.dumps(db_spans), f\\\"a bound row value reached the APM: {db_spans}\\\"\\n\\n\\ndef test_the_probe_would_have_seen_a_row_value_in_the_statement():\\n    \\\"\\\"\\\"The control, because every assertion above is an absence and an absence proves nothing.\\n\\n    Same probe, same exporter, the value interpolated into the SQL instead of bound.\\n    \\\"\\\"\\\"\\n    db_spans = _run_db_probe(\\\"literal\\\")\\n\\n    assert db_spans\\n    assert DB_SENTINEL in json.dumps(db_spans), \\\"the probe cannot see a value in db.statement at all\\\"\\n\\n\\n# The ticket's sampler criterion, run against the real bootstrap rather than a hand-built\\n# provider: the same request at ratio 0.0 must export nothing and at 1.0 must export the lot.\\nSAMPLER_PROBE = \\\"\\\"\\\"\\nimport json\\nfrom opentelemetry import trace\\nfrom lfx.observability import APPLICATION_TRACER_NAME, bootstrap_application_telemetry\\n\\ntelemetry = bootstrap_application_telemetry()\\ntracer = trace.get_tracer(APPLICATION_TRACER_NAME)\\nfor _ in range(20):\\n    with tracer.start_as_current_span(\\\"flow.execute\\\"):\\n        pass\\ntelemetry.shutdown()\\nprint(\\\"PROBE_RESULT done\\\")\\n\\\"\\\"\\\"\\n\\n\\ndef _run_sampler_probe(endpoint: str, ratio: str) -> None:\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env[\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\"] = endpoint\\n    env[\\\"OTEL_EXPORTER_OTLP_PROTOCOL\\\"] = \\\"http/protobuf\\\"\\n    env[\\\"OTEL_TRACES_SAMPLER\\\"] = \\\"traceidratio\\\"\\n    env[\\\"OTEL_TRACES_SAMPLER_ARG\\\"] = ratio\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", SAMPLER_PROBE],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=300,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n\\n\\ndef _exported_span_count(requests_seen) -> int:\\n    from opentelemetry.proto.collector.trace.v1.trace_service_pb2 import ExportTraceServiceRequest\\n\\n    total = 0\\n    for path, body in requests_seen:\\n        if path != \\\"/v1/traces\\\":\\n            continue\\n        request = ExportTraceServiceRequest()\\n        request.ParseFromString(body)\\n        for rs in request.resource_spans:\\n            for ss in rs.scope_spans:\\n                total += len(ss.spans)\\n    return total\\n\\n\\ndef test_sampling_off_exports_nothing(collector):\\n    port = collector.server_address[1]\\n    _run_sampler_probe(f\\\"http://127.0.0.1:{port}\\\", \\\"0.0\\\")\\n\\n    assert _exported_span_count(collector.requests) == 0\\n\\n\\ndef test_sampling_on_exports_every_span(collector):\\n    port = collector.server_address[1]\\n    _run_sampler_probe(f\\\"http://127.0.0.1:{port}\\\", \\\"1.0\\\")\\n\\n    assert _exported_span_count(collector.requests) == 20\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_http_semconv.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2e83d24e3fb0621cb403514f77b3fec75ab86709dfcbcaafa83b9bbab7666e7c\",\"content\":\"\\\"\\\"\\\"The semantic convention opt-in is process-global and read once, so each case is a subprocess.\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\n\\n# Stable names, emitted since OTel HTTP semconv 1.0. APMs key their HTTP dashboards and\\n# service maps off these; the pre-1.0 names leave the per-endpoint breakdown empty.\\nSTABLE = {\\\"http.route\\\", \\\"http.request.method\\\", \\\"http.response.status_code\\\"}\\nLEGACY = {\\\"http.target\\\", \\\"http.method\\\", \\\"http.status_code\\\"}\\n\\nPROBE = \\\"\\\"\\\"\\nimport json\\nfrom opentelemetry import trace\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export import SimpleSpanProcessor\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\nexporter = InMemorySpanExporter()\\nprovider = TracerProvider()\\nprovider.add_span_processor(SimpleSpanProcessor(exporter))\\ntrace.set_tracer_provider(provider)\\n\\nfrom fastapi import FastAPI\\nfrom fastapi.testclient import TestClient\\nfrom opentelemetry.instrumentation.fastapi import FastAPIInstrumentor\\n\\napp = FastAPI()\\n\\n@app.get(\\\"/flows/{flow_id}\\\")\\ndef read_flow(flow_id: str):\\n    return {\\\"id\\\": flow_id}\\n\\n# Mirror langflow.main.create_app: the opt-in must be set before instrumentation.\\nimport os\\nos.environ.setdefault(\\\"OTEL_SEMCONV_STABILITY_OPT_IN\\\", \\\"http\\\")\\nFastAPIInstrumentor.instrument_app(app)\\n\\n# A real request through a real route, so the attributes are whatever the server actually set.\\nTestClient(app).get(\\\"/flows/11111111-1111-1111-1111-111111111111\\\")\\nprovider.force_flush()\\n\\nserver = [s for s in exporter.get_finished_spans() if s.kind.name == \\\"SERVER\\\"]\\nprint(\\\"PROBE_RESULT \\\" + json.dumps({\\\"attrs\\\": dict(server[0].attributes)}))\\n\\\"\\\"\\\"\\n\\n\\ndef run_probe(env_overrides: dict[str, str]) -> dict:\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env.update(env_overrides)\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", PROBE],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=180,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    line = next(ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\"))\\n    return json.loads(line.removeprefix(\\\"PROBE_RESULT \\\"))\\n\\n\\ndef test_http_spans_use_the_stable_semantic_conventions():\\n    \\\"\\\"\\\"Without the opt-in the FastAPI instrumentation still emits the pre-1.0 attribute names.\\\"\\\"\\\"\\n    attrs = run_probe({})[\\\"attrs\\\"]\\n\\n    assert set(attrs) >= STABLE, f\\\"missing stable attributes: {STABLE - set(attrs)}\\\"\\n    assert not (LEGACY & set(attrs)), f\\\"still emitting legacy attributes: {LEGACY & set(attrs)}\\\"\\n\\n    # The templated route, not the request path: the raw path carries flow ids, and this\\n    # attribute reaches metric labels, where per-flow cardinality is unbounded.\\n    assert attrs[\\\"http.route\\\"] == \\\"/flows/{flow_id}\\\"\\n    assert attrs[\\\"http.request.method\\\"] == \\\"GET\\\"\\n    assert attrs[\\\"http.response.status_code\\\"] == 200\\n\\n\\ndef test_an_operator_can_still_opt_into_emitting_both():\\n    \\\"\\\"\\\"setdefault, not an assignment, so a migration can ask for the old names alongside.\\\"\\\"\\\"\\n    attrs = run_probe({\\\"OTEL_SEMCONV_STABILITY_OPT_IN\\\": \\\"http/dup\\\"})[\\\"attrs\\\"]\\n\\n    assert set(attrs) >= STABLE\\n    assert set(attrs) >= LEGACY\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_metric_export.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ae289ae1864e1b0a1283c97dac447c7a2b6c5b779f1f21f8bb9340359dd795c3\",\"content\":\"\\\"\\\"\\\"The meter provider is process-global and installed once, so each case runs in a subprocess.\\\"\\\"\\\"\\n\\nimport gzip\\nimport http.server\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\nimport threading\\n\\nimport pytest\\nfrom opentelemetry.proto.collector.metrics.v1.metrics_service_pb2 import ExportMetricsServiceRequest\\n\\nREADERS_PROBE = \\\"\\\"\\\"\\nimport json\\nfrom langflow.services.telemetry.opentelemetry import OpenTelemetry\\n\\notel = OpenTelemetry(prometheus_enabled=True)\\nreaders = otel._meter_provider._metric_readers\\n\\ndef exporter_module(reader):\\n    # The push exporter is wrapped in ApplicationOnlyMetricExporter; report the one underneath,\\n    # since the protocol choice is what these cases are about.\\n    exporter = reader._exporter\\n    return type(getattr(exporter, \\\"_exporter\\\", exporter)).__module__\\n\\nresult = {\\n    \\\"readers\\\": [type(r).__name__ for r in readers],\\n    \\\"exporters\\\": [exporter_module(r) for r in readers if hasattr(r, \\\"_exporter\\\")],\\n}\\nprint(\\\"PROBE_RESULT \\\" + json.dumps(result))\\n\\\"\\\"\\\"\\n\\n# Scrape before shutting down: PrometheusMetricReader.shutdown() unregisters its collector\\n# from the global registry, so a later scrape would come back empty for reasons unrelated to\\n# whether the two readers coexist.\\nEXPORT_PROBE = \\\"\\\"\\\"\\nimport json\\nfrom langflow.services.telemetry.opentelemetry import OpenTelemetry\\nfrom prometheus_client import generate_latest\\n\\notel = OpenTelemetry(prometheus_enabled=True)\\notel.increment_counter(\\\"num_files_uploaded\\\", {\\\"flow_id\\\": \\\"probe\\\"}, value=2)\\nscrape = generate_latest().decode()\\notel.shutdown()\\nprint(\\\"PROBE_RESULT \\\" + json.dumps({\\\"prometheus\\\": \\\"num_files_uploaded\\\" in scrape}))\\n\\\"\\\"\\\"\\n\\n\\n# The LLM instrumentors take their meter with a bare get_meter off whatever global provider\\n# exists, which is ours. Their gen_ai metrics belong to the flow author's tracing backend, not\\n# to the operator's APM, so they must stay on the local Prometheus endpoint and go no further.\\nLLM_METRIC_PROBE = \\\"\\\"\\\"\\nimport json\\nfrom opentelemetry import metrics\\nfrom langflow.services.telemetry.opentelemetry import OpenTelemetry\\nfrom prometheus_client import generate_latest\\n\\notel = OpenTelemetry(prometheus_enabled=True)\\notel.increment_counter(\\\"num_files_uploaded\\\", {\\\"flow_id\\\": \\\"probe\\\"}, value=2)\\n\\nllm_meter = metrics.get_meter(\\\"opentelemetry.instrumentation.anthropic\\\")\\nllm_meter.create_counter(\\\"gen_ai.client.token.usage\\\").add(42, {\\\"gen_ai.system\\\": \\\"anthropic\\\"})\\n\\nscrape = generate_latest().decode()\\notel.shutdown()\\nprint(\\\"PROBE_RESULT \\\" + json.dumps({\\\"prometheus_has_gen_ai\\\": \\\"token_usage\\\" in scrape}))\\n\\\"\\\"\\\"\\n\\n\\ndef run_probe(source: str, env_overrides: dict[str, str]) -> dict:\\n    # Start from a clean slate so the developer's own OTEL_* vars cannot skew the result.\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env.update(env_overrides)\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", source],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=180,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    line = next(ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\"))\\n    return json.loads(line.removeprefix(\\\"PROBE_RESULT \\\"))\\n\\n\\nclass _Collector(http.server.BaseHTTPRequestHandler):\\n    def do_POST(self) -> None:\\n        body = self.rfile.read(int(self.headers.get(\\\"Content-Length\\\", 0)))\\n        self.server.requests.append((self.path, self.headers.get(\\\"Content-Encoding\\\"), body))\\n        self.send_response(200)\\n        self.send_header(\\\"Content-Length\\\", \\\"0\\\")\\n        self.end_headers()\\n\\n    def log_message(self, *args) -> None:\\n        pass\\n\\n\\n@pytest.fixture\\ndef collector():\\n    server = http.server.HTTPServer((\\\"127.0.0.1\\\", 0), _Collector)\\n    server.requests = []\\n    thread = threading.Thread(target=server.serve_forever, daemon=True)\\n    thread.start()\\n    yield server\\n    server.shutdown()\\n    server.server_close()\\n    thread.join(timeout=5)\\n\\n\\ndef test_no_endpoint_attaches_prometheus_only():\\n    \\\"\\\"\\\"Local and desktop runs set no OTEL_* vars and must stay inert.\\\"\\\"\\\"\\n    result = run_probe(READERS_PROBE, {})\\n    assert result[\\\"readers\\\"] == [\\\"PrometheusMetricReader\\\"]\\n\\n\\n@pytest.mark.parametrize(\\\"endpoint_var\\\", [\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\", \\\"OTEL_EXPORTER_OTLP_METRICS_ENDPOINT\\\"])\\ndef test_endpoint_attaches_otlp_reader_alongside_prometheus(endpoint_var):\\n    result = run_probe(READERS_PROBE, {endpoint_var: \\\"http://localhost:4318\\\"})\\n    assert result[\\\"readers\\\"] == [\\\"PrometheusMetricReader\\\", \\\"PeriodicExportingMetricReader\\\"]\\n\\n\\ndef test_metrics_exporter_none_disables_push():\\n    \\\"\\\"\\\"Operators disable metrics this way when a shared config injects the endpoint.\\\"\\\"\\\"\\n    result = run_probe(\\n        READERS_PROBE,\\n        {\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\", \\\"OTEL_METRICS_EXPORTER\\\": \\\"none\\\"},\\n    )\\n    assert result[\\\"readers\\\"] == [\\\"PrometheusMetricReader\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"protocol\\\", \\\"expected\\\"),\\n    [\\n        (None, \\\"http\\\"),\\n        (\\\"http/protobuf\\\", \\\"http\\\"),\\n        (\\\"grpc\\\", \\\"grpc\\\"),\\n    ],\\n)\\ndef test_protocol_selects_exporter(protocol, expected):\\n    env = {\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\"}\\n    if protocol:\\n        env[\\\"OTEL_EXPORTER_OTLP_PROTOCOL\\\"] = protocol\\n    result = run_probe(READERS_PROBE, env)\\n    assert len(result[\\\"exporters\\\"]) == 1\\n    assert f\\\".proto.{expected}.\\\" in result[\\\"exporters\\\"][0]\\n\\n\\ndef test_per_signal_protocol_takes_precedence():\\n    \\\"\\\"\\\"Reading only the generic variable points an HTTP exporter at a gRPC receiver.\\\"\\\"\\\"\\n    result = run_probe(\\n        READERS_PROBE,\\n        {\\n            \\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\",\\n            \\\"OTEL_EXPORTER_OTLP_PROTOCOL\\\": \\\"http/protobuf\\\",\\n            \\\"OTEL_EXPORTER_OTLP_METRICS_PROTOCOL\\\": \\\"grpc\\\",\\n        },\\n    )\\n    assert \\\".proto.grpc.\\\" in result[\\\"exporters\\\"][0]\\n\\n\\ndef test_metrics_reach_the_endpoint_and_prometheus_still_works(collector):\\n    port = collector.server_address[1]\\n    result = run_probe(EXPORT_PROBE, {\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": f\\\"http://127.0.0.1:{port}\\\"})\\n\\n    assert result[\\\"prometheus\\\"] is True\\n\\n    assert len(collector.requests) == 1\\n    path, encoding, body = collector.requests[0]\\n    assert path == \\\"/v1/metrics\\\"\\n    if encoding == \\\"gzip\\\":\\n        body = gzip.decompress(body)\\n    # Parsing the payload is the point: a bare TCP connection must not pass this test.\\n    request = ExportMetricsServiceRequest()\\n    request.ParseFromString(body)\\n    names = [\\n        metric.name\\n        for resource_metrics in request.resource_metrics\\n        for scope_metrics in resource_metrics.scope_metrics\\n        for metric in scope_metrics.metrics\\n    ]\\n    assert \\\"num_files_uploaded\\\" in names\\n\\n\\ndef test_metrics_exporter_none_sends_nothing(collector):\\n    port = collector.server_address[1]\\n    result = run_probe(\\n        EXPORT_PROBE,\\n        {\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": f\\\"http://127.0.0.1:{port}\\\", \\\"OTEL_METRICS_EXPORTER\\\": \\\"none\\\"},\\n    )\\n    assert result[\\\"prometheus\\\"] is True\\n    assert collector.requests == []\\n\\n\\ndef test_llm_metrics_stay_local_and_are_not_pushed_to_the_apm(collector):\\n    \\\"\\\"\\\"The metrics half of the boundary ApplicationOnlySpanProcessor enforces for spans.\\\"\\\"\\\"\\n    port = collector.server_address[1]\\n    result = run_probe(LLM_METRIC_PROBE, {\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": f\\\"http://127.0.0.1:{port}\\\"})\\n\\n    # Local Prometheus is the flow author's own process and keeps seeing everything.\\n    assert result[\\\"prometheus_has_gen_ai\\\"] is True\\n\\n    assert len(collector.requests) == 1\\n    _, encoding, body = collector.requests[0]\\n    if encoding == \\\"gzip\\\":\\n        body = gzip.decompress(body)\\n    request = ExportMetricsServiceRequest()\\n    request.ParseFromString(body)\\n    scopes = {sm.scope.name for rm in request.resource_metrics for sm in rm.scope_metrics}\\n    names = [metric.name for rm in request.resource_metrics for sm in rm.scope_metrics for metric in sm.metrics]\\n\\n    assert \\\"opentelemetry.instrumentation.anthropic\\\" not in scopes\\n    assert not any(\\\"gen_ai\\\" in name for name in names)\\n    # The application metric in the same export proves the filter dropped a scope, not the batch.\\n    assert \\\"num_files_uploaded\\\" in names\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_protocol_sweep.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"43233230e4f6326086981d3779d6d6f243be287daa8e6837255546cc2b27363c\",\"content\":\"\\\"\\\"\\\"Every entry point that runs a flow must label its span with the surface it came from.\\n\\n``protocol`` answers the operator's first question when an error rate moves: which door did\\nthis come through. A webhook failing and the canvas failing are different incidents with\\ndifferent owners, and the attribute is the only thing that separates them.\\n\\nTwo halves, because they fail differently.\\n\\nThe completeness gate below is static: it reads the values the source can emit and compares\\nthem against the declared list. That is what catches a new entry point being added with no\\ncell, which is how a sweep like this rots between releases.\\n\\nThe per-cell tests are dynamic: they drive the real route and read the exported span. That is\\nwhat catches a binding that exists in the source but does not actually reach the span, which\\nstatic reading cannot see.\\n\\nNaming trap worth knowing before editing this file: ``protocol`` is overloaded in the v2 code.\\n``stream_protocol``, and the ``protocol=`` argument in ``background_execution/service.py``, are\\nthe SSE wire format (``agui`` / ``langflow``) and have nothing to do with this attribute. The\\ngate below matches on call shape rather than on the word, so it does not conflate them.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.observability import APPLICATION_TRACER_NAME\\n\\nBACKEND_SRC = Path(__file__).resolve().parents[4] / \\\"base\\\" / \\\"langflow\\\"\\nLFX_SRC = Path(__file__).resolve().parents[5] / \\\"lfx\\\" / \\\"src\\\" / \\\"lfx\\\"\\n\\n# One row per surface that can run a flow. Keep this sorted and keep it complete: the gate\\n# below fails when the source emits a value that is not here, which is the point.\\nDECLARED_PROTOCOLS = {\\n    \\\"a2a\\\",\\n    \\\"agentic\\\",\\n    \\\"lfx.run\\\",\\n    \\\"lfx.serve\\\",\\n    \\\"mcp\\\",\\n    \\\"openai_responses\\\",\\n    \\\"v1\\\",\\n    \\\"v1.advanced\\\",\\n    \\\"v1.build\\\",\\n    \\\"v1.build.public\\\",\\n    \\\"v2\\\",\\n    \\\"v2.background\\\",\\n    \\\"v2.public\\\",\\n    \\\"voice\\\",\\n    \\\"webhook\\\",\\n}\\n\\n\\n# Where each cell's live evidence lives. This IS the sweep's table: a protocol with no entry\\n# has never been driven end to end, and saying so out loud is the point -- a sweep that\\n# silently omits a surface reads as more coverage than it has.\\n#\\n# \\\"sweep\\\" means a test in this file. Anything else names the file that already drives it;\\n# duplicating those here would add a second thing to keep in step for no extra evidence.\\nCELL_EVIDENCE = {\\n    \\\"v1\\\": \\\"sweep\\\",\\n    \\\"v1.advanced\\\": \\\"sweep\\\",\\n    \\\"v2\\\": \\\"sweep\\\",\\n    \\\"v2.background\\\": \\\"sweep\\\",\\n    \\\"webhook\\\": \\\"sweep\\\",\\n    \\\"openai_responses\\\": \\\"sweep\\\",\\n    \\\"v1.build\\\": \\\"tests/unit/api/test_build_flow_span.py\\\",\\n    \\\"a2a\\\": \\\"tests/unit/api/v1/test_a2a_span.py\\\",\\n    \\\"voice\\\": \\\"tests/unit/services/telemetry/test_flow_execution_span.py\\\",\\n    \\\"lfx.serve\\\": \\\"src/lfx/tests/unit/cli/test_serve_app_flow_span.py\\\",\\n    \\\"lfx.run\\\": \\\"src/lfx/tests/unit/cli/test_run_command_flow_span.py\\\",\\n    # Not yet driven end to end. Each needs a driver this sweep does not have yet; recorded\\n    # rather than omitted so the gap is visible in the table instead of in nobody's head.\\n    \\\"v1.build.public\\\": \\\"BLOCKED: needs a public-flow fixture with the tmp build route\\\",\\n    \\\"v2.public\\\": \\\"BLOCKED: needs a published public workflow fixture\\\",\\n    \\\"mcp\\\": \\\"BLOCKED: needs an MCP client session against the in-process server\\\",\\n    \\\"agentic\\\": \\\"BLOCKED: needs the assistant service driven end to end\\\",\\n}\\n\\n\\n# The N/A cells: combinations that must fail loudly rather than run something. Kept beside\\n# CELL_EVIDENCE because a table that only records what works reads as complete when it is not.\\nNA_EVIDENCE = {\\n    \\\"lfx.serve x v1/webhook/mcp routes\\\": \\\"src/lfx/tests/unit/cli/test_serve_app_flow_span.py\\\",\\n    \\\"lfx.run x any HTTP surface\\\": \\\"src/lfx/tests/unit/cli/test_run_command_flow_span.py\\\",\\n}\\n\\n\\ndef test_every_declared_protocol_has_recorded_evidence():\\n    \\\"\\\"\\\"The table itself. A cell with no row here is an unfilled cell, blocked or not.\\\"\\\"\\\"\\n    missing = DECLARED_PROTOCOLS - set(CELL_EVIDENCE)\\n\\n    assert not missing, f\\\"declared with no evidence row: {sorted(missing)}\\\"\\n\\n\\ndef test_no_evidence_row_is_orphaned():\\n    \\\"\\\"\\\"And the reverse, so a deleted surface cannot leave a row claiming coverage.\\\"\\\"\\\"\\n    orphaned = set(CELL_EVIDENCE) - DECLARED_PROTOCOLS\\n\\n    assert not orphaned, f\\\"evidence rows for protocols that no longer exist: {sorted(orphaned)}\\\"\\n\\n\\ndef test_every_cited_evidence_file_exists():\\n    \\\"\\\"\\\"A cited file that has been moved or deleted is a cell claiming coverage it lost.\\n\\n    The paths were prose until this existed, and one of them was still a placeholder with an\\n    ellipsis in it, which is exactly the rot this catches.\\n    \\\"\\\"\\\"\\n    repo_root = BACKEND_SRC.parents[3]\\n    missing = []\\n    for protocol, evidence in sorted({**CELL_EVIDENCE, **NA_EVIDENCE}.items()):\\n        if evidence == \\\"sweep\\\" or evidence.startswith(\\\"BLOCKED\\\"):\\n            continue\\n        candidate = repo_root / evidence if evidence.startswith(\\\"src/\\\") else BACKEND_SRC.parents[1] / evidence\\n        if not candidate.is_file():\\n            missing.append(f\\\"{protocol} -> {evidence} (looked in {candidate})\\\")\\n\\n    assert not missing, \\\"evidence files that do not exist:\\\\n  \\\" + \\\"\\\\n  \\\".join(missing)\\n\\n\\ndef _literal_protocols(root: Path) -> set[str]:\\n    \\\"\\\"\\\"Every protocol value the source under ``root`` can bind, read from the AST.\\n\\n    Two call shapes carry one, and missing the second is exactly the mistake this function\\n    exists to prevent:\\n\\n    * ``execution_protocol(\\\"v1\\\")`` -- bound directly at the entry point.\\n    * ``_stream_event_frames(..., protocol=\\\"v2.background\\\")`` -- passed one level out, then\\n      bound inside. The parameter is required and un-defaulted there precisely so an unwired\\n      caller cannot silently inherit a wrong label.\\n\\n    Matched on call shape, not on the identifier ``protocol``, so the SSE wire-format argument\\n    of the same name is not swept up.\\n    \\\"\\\"\\\"\\n    found: set[str] = set()\\n    for path in root.rglob(\\\"*.py\\\"):\\n        # Not `\\\"test\\\" in path.parts`: that matches a directory named exactly \\\"test\\\" and misses\\n        # both \\\"tests\\\" directories and test_*.py modules, of which the scanned roots contain 32.\\n        # A test that binds a made-up protocol would otherwise register as an emitted value.\\n        if any(part in {\\\"test\\\", \\\"tests\\\"} or part.startswith(\\\"test_\\\") for part in path.parts):\\n            continue\\n        try:\\n            tree = ast.parse(path.read_text(encoding=\\\"utf-8\\\"), filename=str(path))\\n        except SyntaxError:\\n            continue\\n        for node in ast.walk(tree):\\n            if not isinstance(node, ast.Call):\\n                continue\\n            name = node.func.id if isinstance(node.func, ast.Name) else getattr(node.func, \\\"attr\\\", \\\"\\\")\\n            if name == \\\"execution_protocol\\\":\\n                for arg in node.args:\\n                    if isinstance(arg, ast.Constant) and isinstance(arg.value, str):\\n                        found.add(arg.value)\\n            elif name == \\\"_stream_event_frames\\\":\\n                for kw in node.keywords:\\n                    if kw.arg == \\\"protocol\\\" and isinstance(kw.value, ast.Constant) and isinstance(kw.value.value, str):\\n                        found.add(kw.value.value)\\n    return found\\n\\n\\ndef test_the_scanner_finds_something():\\n    \\\"\\\"\\\"Asserted before the comparisons: an empty scan would make both gates vacuous.\\\"\\\"\\\"\\n    assert _literal_protocols(BACKEND_SRC), f\\\"no protocol values found under {BACKEND_SRC}\\\"\\n\\n\\ndef test_no_entry_point_emits_an_undeclared_protocol():\\n    \\\"\\\"\\\"A new surface without a cell fails here rather than shipping unlabelled.\\\"\\\"\\\"\\n    emitted = _literal_protocols(BACKEND_SRC) | _literal_protocols(LFX_SRC)\\n    undeclared = emitted - DECLARED_PROTOCOLS\\n\\n    assert not undeclared, (\\n        f\\\"these protocol values are emitted but have no cell in this sweep: {sorted(undeclared)}. \\\"\\n        f\\\"Add a row to DECLARED_PROTOCOLS and a per-cell test, or stop emitting them.\\\"\\n    )\\n\\n\\ndef test_every_declared_protocol_is_actually_emitted():\\n    \\\"\\\"\\\"The other direction: a cell for a surface that no longer exists is dead weight.\\n\\n    Without this, deleting an entry point leaves a row asserting nothing, and the table reads\\n    as more coverage than it has.\\n    \\\"\\\"\\\"\\n    emitted = _literal_protocols(BACKEND_SRC) | _literal_protocols(LFX_SRC)\\n    stale = DECLARED_PROTOCOLS - emitted\\n\\n    assert not stale, f\\\"declared but never emitted anywhere in the source: {sorted(stale)}\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Per-cell evidence, driven through the real routes.\\n# ---------------------------------------------------------------------------\\n\\npytestmark = pytest.mark.usefixtures(\\\"client\\\")\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef span_exporter():\\n    \\\"\\\"\\\"Attach an exporter to whatever tracer provider this worker has, and hand it back.\\n\\n    In-process rather than in a subprocess because these tests need the app, the database and\\n    the auth fixtures.\\n\\n    Attaching rather than installing is deliberate. The provider is process-global and\\n    ``set_tracer_provider`` is first-write-wins, so a module that installs its own works alone\\n    and breaks the moment xdist puts another provider-installing module in the same worker.\\n    Adding a processor to the provider already there has no ordering dependency.\\n\\n    The cells still cannot pass vacuously: each asserts its own span arrived before asserting\\n    anything about it.\\n    \\\"\\\"\\\"\\n    from opentelemetry import trace\\n    from opentelemetry.sdk.trace import TracerProvider\\n    from opentelemetry.sdk.trace.export import SimpleSpanProcessor\\n    from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\n    exporter = InMemorySpanExporter()\\n    processor = SimpleSpanProcessor(exporter)\\n    current = trace.get_tracer_provider()\\n    if isinstance(current, TracerProvider):\\n        # A real SDK provider is already installed. set_tracer_provider is first-write-wins,\\n        # so installing another would be ignored and every assertion below would read an\\n        # exporter nothing feeds. Attach to the one that exists instead: no ordering\\n        # dependency, and the cells still fail loudly if their span never arrives.\\n        current.add_span_processor(processor)\\n        try:\\n            yield exporter\\n        finally:\\n            # Shut the processor down rather than detach it: a provider has no removal API,\\n            # so clearing the exporter empties the list and leaves the processor registered,\\n            # still appending every later span in this worker to it for the rest of the run.\\n            processor.shutdown()\\n            exporter.clear()\\n        return\\n\\n    provider = TracerProvider()\\n    provider.add_span_processor(processor)\\n    trace.set_tracer_provider(provider)\\n    try:\\n        yield exporter\\n    finally:\\n        provider.shutdown()\\n        exporter.clear()\\n\\n\\ndef flow_span_protocols(exporter) -> list[str | None]:\\n    \\\"\\\"\\\"The ``protocol`` attribute of every exported flow span, in order.\\\"\\\"\\\"\\n    return [\\n        (span.attributes or {}).get(\\\"protocol\\\")\\n        for span in exporter.get_finished_spans()\\n        if span.name == \\\"flow.execute\\\"\\n        and span.instrumentation_scope\\n        and span.instrumentation_scope.name == APPLICATION_TRACER_NAME\\n    ]\\n\\n\\nasync def test_v1_run_endpoint_reports_v1(client, simple_api_test, created_api_key, span_exporter):\\n    \\\"\\\"\\\"Cell 1: POST /api/v1/run/{flow} -> protocol=v1.\\n\\n    Authenticated with an API key rather than the session cookie, because that is what the\\n    route accepts and therefore what a real caller of this surface uses.\\n    \\\"\\\"\\\"\\n    span_exporter.clear()\\n    flow_id = simple_api_test[\\\"id\\\"]\\n\\n    response = await client.post(\\n        f\\\"/api/v1/run/{flow_id}\\\",\\n        json={\\\"input_value\\\": \\\"hello\\\", \\\"input_type\\\": \\\"chat\\\", \\\"output_type\\\": \\\"chat\\\"},\\n        headers={\\\"x-api-key\\\": created_api_key.api_key},\\n    )\\n\\n    assert response.status_code == 200, response.text\\n    assert \\\"v1\\\" in flow_span_protocols(span_exporter), flow_span_protocols(span_exporter)\\n\\n\\nasync def test_v2_sync_run_reports_v2(client, simple_api_test, created_api_key, span_exporter):\\n    \\\"\\\"\\\"Cell 5: POST /api/v2/workflows?mode=sync -> protocol=v2.\\n\\n    The sync mode is the one that goes through ``Graph.arun``. The streaming and background\\n    modes of the same endpoint bind ``v2.background``, which is a separate cell -- asserting\\n    the exact value here is what keeps the three from being confused for one another.\\n    \\\"\\\"\\\"\\n    span_exporter.clear()\\n\\n    response = await client.post(\\n        \\\"/api/v2/workflows?mode=sync\\\",\\n        json={\\\"flow_id\\\": str(simple_api_test[\\\"id\\\"]), \\\"input_value\\\": \\\"hello\\\"},\\n        headers={\\\"x-api-key\\\": created_api_key.api_key},\\n    )\\n\\n    assert response.status_code == 200, response.text\\n    protocols = flow_span_protocols(span_exporter)\\n    assert \\\"v2\\\" in protocols, protocols\\n    # The exact value matters: a sync run reporting v2.background would mean an operator\\n    # cannot tell inline work from queued work, which is the whole point of the attribute.\\n    assert \\\"v2.background\\\" not in protocols, protocols\\n\\n\\nasync def test_v1_advanced_run_reports_v1_advanced(client, simple_api_test, created_api_key, span_exporter):\\n    \\\"\\\"\\\"Cell 4: POST /api/v1/run/advanced/{flow} -> protocol=v1.advanced.\\\"\\\"\\\"\\n    span_exporter.clear()\\n\\n    response = await client.post(\\n        f\\\"/api/v1/run/advanced/{simple_api_test['id']}\\\",\\n        headers={\\\"x-api-key\\\": created_api_key.api_key},\\n        json={\\\"inputs\\\": [{\\\"components\\\": [], \\\"input_value\\\": \\\"hello\\\"}], \\\"outputs\\\": [], \\\"tweaks\\\": {}, \\\"stream\\\": False},\\n    )\\n\\n    assert response.status_code == 200, response.text\\n    protocols = flow_span_protocols(span_exporter)\\n    assert \\\"v1.advanced\\\" in protocols, protocols\\n    # Distinct from the plain v1 endpoint: they share a driver, so a regression that dropped\\n    # the more specific binding would silently relabel this surface as v1.\\n    assert protocols == [\\\"v1.advanced\\\"], protocols\\n\\n\\nasync def test_webhook_run_reports_webhook(client, added_webhook_test, created_api_key, span_exporter):\\n    \\\"\\\"\\\"Cell 8: POST /api/v1/webhook/{flow} -> protocol=webhook.\\n\\n    The webhook returns 202 and runs the flow in the background, so the span appears after the\\n    response. Polled rather than asserted immediately, because asserting straight away would\\n    race the run and fail intermittently rather than meaningfully.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    span_exporter.clear()\\n\\n    response = await client.post(\\n        f\\\"api/v1/webhook/{added_webhook_test['id']}\\\",\\n        headers={\\\"x-api-key\\\": created_api_key.api_key},\\n        json={\\\"test_key\\\": \\\"test_value\\\"},\\n    )\\n    assert response.status_code == 202, response.text\\n\\n    for _ in range(100):\\n        if \\\"webhook\\\" in flow_span_protocols(span_exporter):\\n            break\\n        await asyncio.sleep(0.1)\\n\\n    assert \\\"webhook\\\" in flow_span_protocols(span_exporter), flow_span_protocols(span_exporter)\\n\\n\\nasync def test_openai_responses_run_reports_openai_responses(client, simple_api_test, created_api_key, span_exporter):\\n    \\\"\\\"\\\"Cell 11: POST /api/v1/responses -> protocol=openai_responses.\\n\\n    The OpenAI-compatible surface takes the flow id in ``model``, which is the shape an\\n    OpenAI SDK client sends.\\n    \\\"\\\"\\\"\\n    span_exporter.clear()\\n\\n    response = await client.post(\\n        \\\"/api/v1/responses\\\",\\n        headers={\\\"x-api-key\\\": created_api_key.api_key},\\n        json={\\\"model\\\": str(simple_api_test[\\\"id\\\"]), \\\"input\\\": \\\"hello\\\", \\\"stream\\\": False},\\n    )\\n\\n    assert response.status_code == 200, response.text\\n    assert \\\"openai_responses\\\" in flow_span_protocols(span_exporter), flow_span_protocols(span_exporter)\\n\\n\\nasync def test_v2_background_run_reports_v2_background(client, simple_api_test, created_api_key, span_exporter):\\n    \\\"\\\"\\\"Cell 6: POST /api/v2/workflows with mode=background -> protocol=v2.background.\\n\\n    The cell that made this sweep worth writing. A background run is handed to a worker after\\n    the response returns, so the label has to survive that hop; if it did not, queued work\\n    would be indistinguishable from inline work in the APM, which is the single question an\\n    operator asks when a v2 run is slow.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    span_exporter.clear()\\n\\n    response = await client.post(\\n        \\\"/api/v2/workflows\\\",\\n        headers={\\\"x-api-key\\\": created_api_key.api_key},\\n        json={\\\"flow_id\\\": str(simple_api_test[\\\"id\\\"]), \\\"input_value\\\": \\\"hello\\\", \\\"mode\\\": \\\"background\\\"},\\n    )\\n    assert response.status_code == 200, response.text\\n\\n    for _ in range(150):\\n        if \\\"v2.background\\\" in flow_span_protocols(span_exporter):\\n            break\\n        await asyncio.sleep(0.1)\\n\\n    protocols = flow_span_protocols(span_exporter)\\n    assert \\\"v2.background\\\" in protocols, protocols\\n    # Not \\\"v2\\\": that would mean the background hop lost the specific label and fell back to\\n    # the generic one, which reads as a pass while erasing the distinction.\\n    assert \\\"v2\\\" not in protocols, protocols\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_queued_trace_continuity.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1e7c709d4fedaff898819b68c8a4282979809c4baae9ebe672ff0b0b744f37ce\",\"content\":\"\\\"\\\"\\\"A background run must be reachable from the request that queued it.\\n\\nBefore this, the two were unrelated traces. Measured on a real background run:\\n\\n    flow.execute  trace_id = 1291125b0d1eaf83ea0508d451d160a9   <- its own trace\\n                  parent   = None\\n                  links    = []\\n\\nAn operator looking at a slow background run could not get back to the request that caused\\nit, and an operator looking at a slow request could not see the work it queued.\\n\\nDriven through the real route rather than by calling the helpers, because the helpers already\\nhave unit tests in ``src/lfx/tests/unit/test_trace_carrier.py``. What those cannot show is\\nthat the carrier survives the actual hop: written on the job row by one request, read by the\\nrunner that picks the job up afterwards.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\n\\nimport pytest\\nfrom lfx.observability import APPLICATION_TRACER_NAME\\n\\npytestmark = pytest.mark.usefixtures(\\\"client\\\")\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef span_exporter():\\n    \\\"\\\"\\\"Attach an exporter to whatever tracer provider this worker has, and hand it back.\\n\\n    In-process rather than a subprocess because this needs the app, the database and the auth\\n    fixtures.\\n\\n    Attaching rather than installing is deliberate. ``set_tracer_provider`` is\\n    first-write-wins, so a module that installs its own provider works alone and fails the\\n    moment xdist puts another provider-installing module in the same worker -- which is\\n    exactly what happened here on one Python version and not the others. Adding a processor\\n    to the provider that is already there has no such ordering dependency.\\n\\n    The tests still cannot pass vacuously: each one asserts that its own spans arrived before\\n    asserting anything about their links.\\n    \\\"\\\"\\\"\\n    from opentelemetry import trace\\n    from opentelemetry.sdk.trace import TracerProvider\\n    from opentelemetry.sdk.trace.export import SimpleSpanProcessor\\n    from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\n    exporter = InMemorySpanExporter()\\n    processor = SimpleSpanProcessor(exporter)\\n    current = trace.get_tracer_provider()\\n    if isinstance(current, TracerProvider):\\n        # Someone already installed a real SDK provider. Ride it rather than fight it; the\\n        # helpers below filter to this module's own spans by name and scope.\\n        current.add_span_processor(processor)\\n        try:\\n            yield exporter\\n        finally:\\n            # Shut the processor down rather than detach it: a provider has no removal API,\\n            # so clearing the exporter empties the list and leaves the processor registered,\\n            # still appending every later span in this worker to it for the rest of the run.\\n            processor.shutdown()\\n            exporter.clear()\\n        return\\n\\n    provider = TracerProvider()\\n    provider.add_span_processor(processor)\\n    trace.set_tracer_provider(provider)\\n    try:\\n        yield exporter\\n    finally:\\n        provider.shutdown()\\n        exporter.clear()\\n\\n\\ndef _flow_spans(exporter):\\n    return [\\n        s\\n        for s in exporter.get_finished_spans()\\n        if s.name == \\\"flow.execute\\\"\\n        and s.instrumentation_scope\\n        and s.instrumentation_scope.name == APPLICATION_TRACER_NAME\\n    ]\\n\\n\\ndef _request_spans(exporter):\\n    return [s for s in exporter.get_finished_spans() if \\\"workflows\\\" in s.name and s.kind.name == \\\"SERVER\\\"]\\n\\n\\nasync def _run_background(client, flow_id, api_key, exporter):\\n    \\\"\\\"\\\"Start a background run and wait for its flow span to arrive.\\\"\\\"\\\"\\n    response = await client.post(\\n        \\\"/api/v2/workflows\\\",\\n        headers={\\\"x-api-key\\\": api_key},\\n        json={\\\"flow_id\\\": str(flow_id), \\\"input_value\\\": \\\"hello\\\", \\\"mode\\\": \\\"background\\\"},\\n    )\\n    assert response.status_code == 200, response.text\\n\\n    for _ in range(150):\\n        if _flow_spans(exporter):\\n            break\\n        await asyncio.sleep(0.1)\\n    return response.json()\\n\\n\\nasync def test_a_background_run_links_back_to_the_request_that_queued_it(\\n    client, simple_api_test, created_api_key, span_exporter\\n):\\n    \\\"\\\"\\\"The regression this file exists for.\\\"\\\"\\\"\\n    span_exporter.clear()\\n\\n    await _run_background(client, simple_api_test[\\\"id\\\"], created_api_key.api_key, span_exporter)\\n\\n    flows = _flow_spans(span_exporter)\\n    requests = _request_spans(span_exporter)\\n\\n    # Asserted before the link check: with no spans at all, \\\"the link is right\\\" passes trivially.\\n    assert len(flows) == 1, [s.name for s in span_exporter.get_finished_spans()]\\n    assert requests, \\\"no server span for the enqueuing request; the link has nothing to point at\\\"\\n\\n    links = [link.context.trace_id for link in (flows[0].links or [])]\\n    assert links == [requests[0].get_span_context().trace_id], (\\n        f\\\"flow span links {[format(t, '032x') for t in links]}, \\\"\\n        f\\\"request trace {format(requests[0].get_span_context().trace_id, '032x')}\\\"\\n    )\\n\\n\\nasync def test_the_run_keeps_its_own_trace(client, simple_api_test, created_api_key, span_exporter):\\n    \\\"\\\"\\\"A link, not a parent, and not a merge into the request's trace.\\n\\n    The run starts after the request finished. Parenting it, or folding it into the same\\n    trace, renders as a child that begins after its parent ended.\\n    \\\"\\\"\\\"\\n    span_exporter.clear()\\n\\n    await _run_background(client, simple_api_test[\\\"id\\\"], created_api_key.api_key, span_exporter)\\n\\n    flow = _flow_spans(span_exporter)[0]\\n    request = _request_spans(span_exporter)[0]\\n\\n    assert flow.parent is None, flow.parent\\n    assert flow.get_span_context().trace_id != request.get_span_context().trace_id\\n\\n\\nasync def test_a_synchronous_run_gets_no_link(client, simple_api_test, created_api_key, span_exporter):\\n    \\\"\\\"\\\"The control, and the thing that would break first if the carrier leaked.\\n\\n    A sync run has a live request above it, so it is a real child and needs no link. If this\\n    grows one, the ambient link is escaping its binding and attaching to runs it has nothing\\n    to do with.\\n    \\\"\\\"\\\"\\n    span_exporter.clear()\\n\\n    response = await client.post(\\n        \\\"/api/v2/workflows?mode=sync\\\",\\n        headers={\\\"x-api-key\\\": created_api_key.api_key},\\n        json={\\\"flow_id\\\": str(simple_api_test[\\\"id\\\"]), \\\"input_value\\\": \\\"hello\\\"},\\n    )\\n    assert response.status_code == 200, response.text\\n\\n    flows = _flow_spans(span_exporter)\\n    assert flows, \\\"no flow span for the sync run\\\"\\n    assert all(not (s.links or []) for s in flows), [[link.context.trace_id for link in (s.links or [])] for s in flows]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_run_event_store.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"017391e70c7513c7e2ef0d1c5fad3db53376117b353572b4a104ee92512c66c0\",\"content\":\"\\\"\\\"\\\"Unit tests for the run event store (enterprise metering seam).\\n\\nTesting library and framework: pytest\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom langflow.services.telemetry import run_event_store\\nfrom langflow.services.telemetry.run_event_store import append_run_event, peek_all, pop_all\\nfrom langflow.services.telemetry.schema import RunPayload\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _drain_store():\\n    \\\"\\\"\\\"Isolate each test from events other tests (or fixtures) appended.\\\"\\\"\\\"\\n    pop_all()\\n    yield\\n    pop_all()\\n\\n\\ndef _payload(run_id: str) -> RunPayload:\\n    return RunPayload(run_seconds=1, run_success=True, run_id=run_id)\\n\\n\\ndef test_append_and_pop_roundtrip():\\n    p = _payload(\\\"r1\\\")\\n    append_run_event(p)\\n    assert pop_all() == [p]\\n\\n\\ndef test_pop_all_drains():\\n    append_run_event(_payload(\\\"r1\\\"))\\n    append_run_event(_payload(\\\"r2\\\"))\\n    assert len(pop_all()) == 2\\n    assert pop_all() == []\\n\\n\\ndef test_pop_all_preserves_order():\\n    first, second = _payload(\\\"r1\\\"), _payload(\\\"r2\\\")\\n    append_run_event(first)\\n    append_run_event(second)\\n    assert pop_all() == [first, second]\\n\\n\\ndef test_peek_all_is_nondestructive():\\n    p = _payload(\\\"r1\\\")\\n    append_run_event(p)\\n    assert peek_all() == [p]\\n    assert peek_all() == [p]\\n    assert pop_all() == [p]\\n\\n\\ndef test_bound_discards_oldest(monkeypatch):\\n    monkeypatch.setattr(run_event_store, \\\"_MAX_EVENTS\\\", 3)\\n    for i in range(5):\\n        append_run_event(_payload(f\\\"r{i}\\\"))\\n    kept = pop_all()\\n    assert [p.run_id for p in kept] == [\\\"r2\\\", \\\"r3\\\", \\\"r4\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_runtime_and_log_export.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6ac510465b0e6f8b1771b49dce2ed30b66415a7367e0153952e91dbd5bccf5ed\",\"content\":\"\\\"\\\"\\\"Runtime metrics and log export, driven against a real loopback OTLP collector.\\n\\nThe providers are process-global and installed once, so every case runs in a subprocess.\\n\\\"\\\"\\\"\\n\\nimport gzip\\nimport http.server\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\nimport threading\\n\\nimport pytest\\nfrom opentelemetry.proto.collector.logs.v1.logs_service_pb2 import ExportLogsServiceRequest\\nfrom opentelemetry.proto.collector.metrics.v1.metrics_service_pb2 import ExportMetricsServiceRequest\\nfrom opentelemetry.proto.collector.trace.v1.trace_service_pb2 import ExportTraceServiceRequest\\n\\n# What an operator needs before anything is failing: saturation and runtime health.\\nEXPECTED_PROCESS_METRICS = {\\n    \\\"process.cpu.utilization\\\",\\n    \\\"process.memory.usage\\\",\\n    \\\"process.thread.count\\\",\\n}\\n\\n# Host-level families the default config would have added. They describe the machine, not\\n# the service, and the disk and network ones multiply per device.\\nUNWANTED_HOST_METRICS = (\\\"system.disk.\\\", \\\"system.network.\\\", \\\"system.swap.\\\")\\n\\nSENTINEL_INFO = \\\"operator-visible-info-line\\\"\\nSENTINEL_DEBUG = \\\"flow-payload-that-must-not-be-shipped\\\"\\n\\nPROBE = f\\\"\\\"\\\"\\nimport logging\\nfrom langflow.services.telemetry.opentelemetry import OpenTelemetry\\nfrom lfx.log.logger import configure\\nfrom lfx.log.logger import logger\\n\\n# Configure logging first, the order both runtimes use: the startup line the bootstrap emits\\n# only reaches the exporter through the structlog chain this installs.\\n# DEBUG so the emitter sees both records and has to make the severity decision itself.\\nconfigure(log_level=\\\"DEBUG\\\")\\n\\notel = OpenTelemetry(prometheus_enabled=False)\\nlogger.debug({SENTINEL_DEBUG!r})\\nlogger.info({SENTINEL_INFO!r})\\nlogger.warning(\\\"disk is nearly full\\\")\\n\\notel.shutdown()   # flushes both the metric reader and the log processor\\nprint(\\\"PROBE_RESULT \\\" + '{{}}')\\n\\\"\\\"\\\"\\n\\n\\ndef run_probe(env_overrides: dict[str, str]) -> None:\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env.update(env_overrides)\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", PROBE],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=300,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    assert \\\"PROBE_RESULT\\\" in completed.stdout, completed.stdout\\n\\n\\nclass _Collector(http.server.BaseHTTPRequestHandler):\\n    def do_POST(self) -> None:\\n        body = self.rfile.read(int(self.headers.get(\\\"Content-Length\\\", 0)))\\n        if self.headers.get(\\\"Content-Encoding\\\") == \\\"gzip\\\":\\n            body = gzip.decompress(body)\\n        self.server.requests.append((self.path, body))\\n        self.send_response(200)\\n        self.send_header(\\\"Content-Length\\\", \\\"0\\\")\\n        self.end_headers()\\n\\n    def log_message(self, *args) -> None:\\n        pass\\n\\n\\n@pytest.fixture\\ndef collector():\\n    server = http.server.HTTPServer((\\\"127.0.0.1\\\", 0), _Collector)\\n    server.requests = []\\n    thread = threading.Thread(target=server.serve_forever, daemon=True)\\n    thread.start()\\n    yield server\\n    server.shutdown()\\n    server.server_close()\\n    thread.join(timeout=5)\\n\\n\\ndef _metric_names(requests) -> set[str]:\\n    names = set()\\n    for path, body in requests:\\n        if path != \\\"/v1/metrics\\\":\\n            continue\\n        request = ExportMetricsServiceRequest()\\n        request.ParseFromString(body)\\n        for rm in request.resource_metrics:\\n            for sm in rm.scope_metrics:\\n                names.update(m.name for m in sm.metrics)\\n    return names\\n\\n\\ndef _log_records(requests, *, scope: str | None = None) -> list:\\n    \\\"\\\"\\\"Log records the collector received, optionally only those on one instrumentation scope.\\n\\n    Scope is the axis the body boundary is drawn on, so several cases below need to ask about\\n    one side of it at a time.\\n    \\\"\\\"\\\"\\n    records = []\\n    for path, body in requests:\\n        if path != \\\"/v1/logs\\\":\\n            continue\\n        request = ExportLogsServiceRequest()\\n        request.ParseFromString(body)\\n        for rl in request.resource_logs:\\n            for sl in rl.scope_logs:\\n                if scope is not None and sl.scope.name != scope:\\n                    continue\\n                records.extend(sl.log_records)\\n    return records\\n\\n\\n@pytest.fixture\\ndef exported(collector):\\n    port = collector.server_address[1]\\n    run_probe({\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": f\\\"http://127.0.0.1:{port}\\\"})\\n    return collector.requests\\n\\n\\ndef test_runtime_metrics_reach_the_apm(exported):\\n    \\\"\\\"\\\"Without these, the only metrics are request-shaped and saturation is invisible.\\\"\\\"\\\"\\n    names = _metric_names(exported)\\n\\n    assert names >= EXPECTED_PROCESS_METRICS, f\\\"missing: {EXPECTED_PROCESS_METRICS - names}\\\"\\n    # GC is the Python-specific failure mode: slow service, flat CPU.\\n    assert any(n.startswith(\\\"cpython.gc.\\\") for n in names), sorted(names)\\n\\n\\ndef test_host_level_metrics_are_not_exported(exported):\\n    \\\"\\\"\\\"The node belongs to the infrastructure agent; these would only multiply series.\\\"\\\"\\\"\\n    names = _metric_names(exported)\\n\\n    offenders = [n for n in names if n.startswith(UNWANTED_HOST_METRICS)]\\n    assert not offenders, f\\\"host-level metrics leaked into the export: {offenders}\\\"\\n\\n\\ndef test_log_lines_reach_the_apm(exported):\\n    \\\"\\\"\\\"The pivot from a failing trace to the log lines emitted inside it.\\n\\n    The record still travels; only its body is withheld. Whether an operator can see the text is\\n    a separate question from whether the record exists, and alerting on error rate or pivoting\\n    by trace id needs only the second.\\n    \\\"\\\"\\\"\\n    records = _log_records(exported, scope=\\\"lfx\\\")\\n\\n    assert len(records) >= 2, records\\n    assert {r.severity_text for r in records} >= {\\\"INFO\\\", \\\"WARNING\\\"}\\n\\n\\ndef test_message_bodies_do_not_cross_the_boundary(exported):\\n    \\\"\\\"\\\"The logs signal allowlists by scope, the same rule the span exporter already applies.\\n\\n    Both sentinels are ordinary application log lines on the default scope, which is the channel\\n    that carried prompts, chat history and provider error text to the operator's APM.\\n    \\\"\\\"\\\"\\n    payload = json.dumps([str(r) for r in _log_records(exported)])\\n\\n    assert SENTINEL_INFO not in payload\\n    assert SENTINEL_DEBUG not in payload\\n\\n\\ndef test_the_startup_line_states_the_boundary(exported):\\n    \\\"\\\"\\\"The allowlisted scope keeps its body, and it is what tells the operator what they get.\\n\\n    Documentation does not reach the person writing the Helm values; a line in their own log\\n    stream does. It is also the proof that the allowlist lets something through rather than\\n    being an off switch with extra steps.\\n    \\\"\\\"\\\"\\n    bodies = [r.body.string_value for r in _log_records(exported, scope=\\\"langflow.observability\\\")]\\n\\n    assert any(\\\"OTLP log export enabled\\\" in b for b in bodies), bodies\\n    assert any(\\\"bodies are withheld\\\" in b.lower() for b in bodies), bodies\\n    assert any(\\\"container stdout\\\" in b for b in bodies), bodies\\n\\n\\ndef test_debug_lines_are_not_shipped_to_the_operator(exported):\\n    \\\"\\\"\\\"The console is the developer's, the APM is the operator's.\\n\\n    Severity is the first of two gates and still the one that keeps the bulk of flow payload\\n    logging local; the body boundary above is the second. This asserts the severity gate on its\\n    own, so a regression in either is attributable.\\n    \\\"\\\"\\\"\\n    records = _log_records(exported)\\n\\n    assert records, \\\"the probe must export something for this to mean anything\\\"\\n    assert all(r.severity_number >= 9 for r in records)  # INFO and above\\n\\n\\ndef test_log_severity_is_preserved(exported):\\n    \\\"\\\"\\\"An operator alerting on error rate needs the level, and it survives the body boundary.\\\"\\\"\\\"\\n    by_severity = {r.severity_text: r for r in _log_records(exported, scope=\\\"lfx\\\")}\\n\\n    assert \\\"INFO\\\" in by_severity, sorted(by_severity)\\n    assert \\\"WARNING\\\" in by_severity, sorted(by_severity)\\n    assert by_severity[\\\"WARNING\\\"].severity_number > by_severity[\\\"INFO\\\"].severity_number\\n\\n\\n# The incident walk in one probe: a request comes in, something is logged while handling it,\\n# and the operator pivots from the failing trace to that line by trace id.\\nINCIDENT_PROBE = \\\"\\\"\\\"\\nimport json\\nfrom opentelemetry import trace, _logs\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export import SimpleSpanProcessor\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\nfrom opentelemetry.sdk._logs import LoggerProvider\\nfrom opentelemetry.sdk._logs.export import SimpleLogRecordProcessor\\nfrom opentelemetry.sdk._logs._internal.export.in_memory_log_exporter import InMemoryLogExporter\\n\\nspans = InMemorySpanExporter()\\ntp = TracerProvider(); tp.add_span_processor(SimpleSpanProcessor(spans))\\ntrace.set_tracer_provider(tp)\\n\\nlogs = InMemoryLogExporter()\\nlp = LoggerProvider(); lp.add_log_record_processor(SimpleLogRecordProcessor(logs))\\n_logs.set_logger_provider(lp)\\n\\nfrom fastapi import FastAPI\\nfrom fastapi.testclient import TestClient\\nfrom opentelemetry.instrumentation.fastapi import FastAPIInstrumentor\\nfrom lfx.log.logger import configure, logger\\n\\nconfigure(log_level=\\\"INFO\\\")\\napp = FastAPI()\\n\\n@app.get(\\\"/boom\\\")\\ndef boom():\\n    logger.error(\\\"payment provider timed out\\\")\\n    raise RuntimeError(\\\"kaboom\\\")\\n\\nFastAPIInstrumentor.instrument_app(app)\\n\\nclient = TestClient(app, raise_server_exceptions=False)\\nclient.get(\\\"/boom\\\")\\ntp.force_flush(); lp.force_flush()\\n\\nserver_span = [s for s in spans.get_finished_spans() if s.kind.name == \\\"SERVER\\\"][0]\\ndef as_hex(value):\\n    return format(value, \\\"032x\\\") if value else None\\n\\nrecords = [\\n    {\\n        \\\"body\\\": str(r.log_record.body),\\n        \\\"severity\\\": r.log_record.severity_text,\\n        \\\"trace_id\\\": as_hex(r.log_record.trace_id),\\n    }\\n    for r in logs.get_finished_logs()\\n]\\nprint(\\\"PROBE_RESULT \\\" + json.dumps({\\n    \\\"span_trace_id\\\": format(server_span.context.trace_id, \\\"032x\\\"),\\n    \\\"records\\\": records,\\n}))\\n\\\"\\\"\\\"\\n\\n\\ndef test_a_log_emitted_during_a_request_carries_that_request_trace_id():\\n    \\\"\\\"\\\"This is the pivot the incident walk depends on; without it logs and traces are two silos.\\\"\\\"\\\"\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", INCIDENT_PROBE],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=300,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    line = next(ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\"))\\n    result = json.loads(line.removeprefix(\\\"PROBE_RESULT \\\"))\\n\\n    # Matched on severity rather than text: the body is withheld at the boundary, and the\\n    # correlation this test exists for is carried by trace_id, which is not.\\n    match = [r for r in result[\\\"records\\\"] if r[\\\"severity\\\"] == \\\"ERROR\\\"]\\n    assert match, result[\\\"records\\\"]\\n    # any(), not match[0]: nothing orders the exported records, and another ERROR arriving\\n    # first would fail this while correlation itself works.\\n    assert any(r[\\\"trace_id\\\"] == result[\\\"span_trace_id\\\"] for r in match), result[\\\"records\\\"]\\n    assert \\\"payment provider timed out\\\" not in json.dumps(result[\\\"records\\\"])\\n\\n\\n# The DEBUG floor is an override, not a lock: an operator debugging a live incident may\\n# genuinely need it. What must not happen is it moving quietly.\\nOVERRIDE_PROBE = f\\\"\\\"\\\"\\nfrom opentelemetry import _logs\\nfrom opentelemetry.sdk._logs import LoggerProvider\\nfrom opentelemetry.sdk._logs.export import SimpleLogRecordProcessor\\nfrom opentelemetry.sdk._logs._internal.export.in_memory_log_exporter import InMemoryLogExporter\\n\\nexporter = InMemoryLogExporter()\\nprovider = LoggerProvider()\\nprovider.add_log_record_processor(SimpleLogRecordProcessor(exporter))\\n_logs.set_logger_provider(provider)\\n\\nfrom lfx.log.logger import configure, logger\\n\\nconfigure(log_level=\\\"DEBUG\\\")\\nlogger.debug({SENTINEL_DEBUG!r})\\nlogger.info({SENTINEL_INFO!r})\\nprovider.force_flush()\\n\\nseverities = [r.log_record.severity_text for r in exporter.get_finished_logs()]\\nprint(\\\"DEBUG_SHIPPED \\\" + str(\\\"DEBUG\\\" in severities))\\n\\\"\\\"\\\"\\n\\n\\ndef run_override_probe(value: str | None) -> tuple[bool, str]:\\n    \\\"\\\"\\\"Return (was DEBUG exported, whatever went to stderr).\\\"\\\"\\\"\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env.pop(\\\"LANGFLOW_OTEL_LOG_LEVEL\\\", None)\\n    if value is not None:\\n        env[\\\"LANGFLOW_OTEL_LOG_LEVEL\\\"] = value\\n    env[\\\"PYTHONWARNINGS\\\"] = \\\"always\\\"\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", OVERRIDE_PROBE],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=300,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    shipped = next(ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"DEBUG_SHIPPED \\\"))\\n    return shipped.endswith(\\\"True\\\"), completed.stderr\\n\\n\\ndef test_debug_export_is_off_and_silent_by_default():\\n    shipped, stderr = run_override_probe(None)\\n\\n    assert shipped is False\\n    assert \\\"LANGFLOW_OTEL_LOG_LEVEL\\\" not in stderr\\n\\n\\ndef test_lowering_the_floor_works_but_says_so_loudly():\\n    \\\"\\\"\\\"Refusing outright would just get worked around; the requirement is that it is not quiet.\\\"\\\"\\\"\\n    shipped, stderr = run_override_probe(\\\"debug\\\")\\n\\n    assert shipped is True\\n    assert \\\"LANGFLOW_OTEL_LOG_LEVEL\\\" in stderr\\n    # The warning has to name the actual consequence, not just report a setting.\\n    assert \\\"prompt\\\" in stderr.lower()\\n    assert \\\"DEBUG\\\" in stderr\\n\\n\\ndef test_an_unrecognised_value_fails_closed_and_warns():\\n    \\\"\\\"\\\"A typo must not be a way to accidentally open the floor.\\\"\\\"\\\"\\n    shipped, stderr = run_override_probe(\\\"verbose\\\")\\n\\n    assert shipped is False\\n    assert \\\"LANGFLOW_OTEL_LOG_LEVEL\\\" in stderr\\n    assert \\\"verbose\\\" in stderr\\n\\n\\n# The same incident walk, but for a flow run rather than an HTTP request, and driven end to end:\\n# langflow's real telemetry bootstrap, the real OTLP exporters, and the trace ids read back off\\n# the protobuf that reached the collector. `lfx serve` is asserted separately, in\\n# src/lfx/tests/unit/cli/test_serve_app_log_trace_correlation.py, because the two runtimes reach\\n# the flow span by different paths and only one of them can be true at a time.\\nFLOW_SENTINEL = \\\"component-log-line-emitted-inside-the-flow-run\\\"\\n\\nFLOW_PROBE = f\\\"\\\"\\\"\\nimport asyncio\\n\\nfrom langflow.processing.process import run_graph\\nfrom langflow.services.telemetry.opentelemetry import OpenTelemetry\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.graph import Graph\\nfrom lfx.io import MessageInput, Output\\nfrom lfx.log.logger import configure, logger\\nfrom lfx.schema.message import Message\\n\\n\\nclass LoggingComponent(Component):\\n    display_name = \\\"Logging\\\"\\n    inputs = [MessageInput(name=\\\"input_value\\\", display_name=\\\"Input\\\")]\\n    outputs = [Output(name=\\\"message\\\", display_name=\\\"Message\\\", method=\\\"passthrough\\\")]\\n\\n    def passthrough(self) -> Message:\\n        logger.info({FLOW_SENTINEL!r})\\n        return self.input_value\\n\\n\\n# Installs the OTLP providers from the OTEL_* env vars, exactly as a langflow server does.\\notel = OpenTelemetry(prometheus_enabled=False)\\nconfigure(log_level=\\\"INFO\\\")\\n\\nchat_input = ChatInput()\\nlogging_component = LoggingComponent().set(input_value=chat_input.message_response)\\nchat_output = ChatOutput().set(input_value=logging_component.passthrough)\\ngraph = Graph(chat_input, chat_output, flow_id=\\\"00000000-0000-0000-0000-0000000000aa\\\")\\n\\nasyncio.run(run_graph(graph=graph, input_value=\\\"hello\\\", input_type=\\\"chat\\\", output_type=\\\"chat\\\"))\\notel.shutdown()\\nprint(\\\"PROBE_RESULT ok\\\")\\n\\\"\\\"\\\"\\n\\n\\ndef _spans(requests) -> list:\\n    spans = []\\n    for path, body in requests:\\n        if path != \\\"/v1/traces\\\":\\n            continue\\n        request = ExportTraceServiceRequest()\\n        request.ParseFromString(body)\\n        for rs in request.resource_spans:\\n            for ss in rs.scope_spans:\\n                spans.extend(ss.spans)\\n    return spans\\n\\n\\n@pytest.fixture\\ndef exported_flow_run(collector, tmp_path):\\n    \\\"\\\"\\\"Run one real flow under the real bootstrap; return what reached the collector.\\\"\\\"\\\"\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env[\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\"] = f\\\"http://127.0.0.1:{collector.server_address[1]}\\\"\\n    # The sentinel is how this test finds its own record, and the log body boundary withholds\\n    # message bodies from the export by default, so without this the match comes back empty and\\n    # the test fails before it reaches the correlation it exists to check. This test is about\\n    # correlation, not about that boundary, so ask for bodies explicitly. No-op on a build that\\n    # predates the setting. The lfx fixture in test_serve_app_log_trace_correlation.py does the\\n    # same thing for the same reason.\\n    env[\\\"LANGFLOW_OTEL_LOG_BODIES\\\"] = \\\"all\\\"\\n    # A file rather than ``python -c``: Component.__init__ reads its own class source with\\n    # inspect.getsource, which has nothing to read for a class defined in a ``-c`` string.\\n    probe = tmp_path / \\\"flow_probe.py\\\"\\n    probe.write_text(FLOW_PROBE)\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, str(probe)],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=600,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    assert \\\"PROBE_RESULT ok\\\" in completed.stdout, completed.stdout\\n    return collector.requests\\n\\n\\ndef test_a_log_line_from_a_flow_run_carries_the_flow_span_trace_id(exported_flow_run):\\n    \\\"\\\"\\\"The pivot from a flow's trace to its logs. Without it the two signals are separate silos.\\\"\\\"\\\"\\n    flow_span = next(s for s in _spans(exported_flow_run) if s.name == \\\"flow.execute\\\")\\n    matching = [r for r in _log_records(exported_flow_run) if r.body.string_value == FLOW_SENTINEL]\\n\\n    assert matching, [r.body.string_value for r in _log_records(exported_flow_run)]\\n    # A zeroed trace id is what \\\"no active span\\\" looks like on the wire, so it would pass a\\n    # naive equality check against another zeroed one.\\n    assert flow_span.trace_id != b\\\"\\\\x00\\\" * 16\\n    assert matching[0].trace_id == flow_span.trace_id, (\\n        f\\\"log trace_id {matching[0].trace_id.hex()} != span trace_id {flow_span.trace_id.hex()}\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_span_url_redaction.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4a2b9b8ceaea7d0cf5f96b5facbc64c3354c88d349c6a5abd89ca02c0830d5dd\",\"content\":\"\\\"\\\"\\\"The operator's APM must never receive a credential that travelled in a URL.\\n\\n``lfx serve`` accepts its API key as a query parameter (``APIKeyQuery``), and the FastAPI\\nserver span records ``url.query`` verbatim. That scope is on the export allowlist, so before\\nthis the key went to whatever OTLP backend the operator configured.\\n\\nRuns in a subprocess because the tracer provider is process-global.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\nimport tempfile\\nfrom pathlib import Path\\n\\nfrom lfx.observability import APPLICATION_INSTRUMENTATION_SCOPES\\n\\nSECRET = \\\"lfx-serve-api-key-NOT-REAL\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n# The server span is already allowlisted, and ``lfx serve`` accepts its API key as a query\\n# parameter, so this is a live path today rather than a hypothetical one.\\nSERVER_SPAN_PROBE = f\\\"\\\"\\\"\\nimport asyncio, json\\n\\nfrom opentelemetry import trace\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\nfrom lfx.observability import ApplicationOnlySpanProcessor, instrument_fastapi_app\\n\\nexporter = InMemorySpanExporter()\\nprovider = TracerProvider()\\nprovider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\ntrace.set_tracer_provider(provider)\\n\\nfrom fastapi import FastAPI\\nfrom httpx import ASGITransport, AsyncClient\\n\\napp = FastAPI()\\n\\n\\n@app.get(\\\"/flows/run\\\")\\nasync def run():\\n    return {{\\\"ok\\\": True}}\\n\\n\\ninstrument_fastapi_app(app)\\nSECRET = {SECRET!r}\\n\\n\\nasync def main():\\n    async with AsyncClient(transport=ASGITransport(app=app), base_url=\\\"http://probe\\\") as client:\\n        await client.get(f\\\"/flows/run?x-api-key={{SECRET}}&flow=abc\\\")\\n    provider.force_flush()\\n    spans = [\\n        {{\\\"name\\\": s.name, \\\"attrs\\\": dict(s.attributes)}}\\n        for s in exporter.get_finished_spans()\\n        if s.attributes and \\\"url.path\\\" in s.attributes\\n    ]\\n    print(\\\"PROBE_RESULT \\\" + json.dumps({{\\\"spans\\\": spans}}))\\n\\n\\nasyncio.run(main())\\n\\\"\\\"\\\"\\n\\n\\ndef run_probe(source: str) -> dict:\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    with tempfile.TemporaryDirectory() as tmp:\\n        probe_path = Path(tmp) / \\\"probe.py\\\"\\n        probe_path.write_text(source, encoding=\\\"utf-8\\\")\\n        completed = subprocess.run(  # noqa: S603\\n            [sys.executable, str(probe_path)],\\n            env=env,\\n            capture_output=True,\\n            text=True,\\n            timeout=300,\\n            check=False,\\n        )\\n    assert completed.returncode == 0, completed.stderr\\n    # Not next(): a probe that exits cleanly without printing would raise StopIteration here and\\n    # take its own stdout and stderr with it, which is the context needed to see why.\\n    lines = [ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\")]\\n    assert lines, f\\\"probe printed no result.\\\\nstdout:\\\\n{completed.stdout}\\\\nstderr:\\\\n{completed.stderr}\\\"\\n    return json.loads(lines[0].removeprefix(\\\"PROBE_RESULT \\\"))\\n\\n\\ndef test_the_serve_api_key_never_reaches_the_apm():\\n    \\\"\\\"\\\"Regression for a live leak: the key is accepted as a query param and the span kept it.\\\"\\\"\\\"\\n    result = run_probe(SERVER_SPAN_PROBE)\\n\\n    assert result[\\\"spans\\\"], \\\"expected a server span carrying url.path\\\"\\n    blob = json.dumps(result[\\\"spans\\\"])\\n    assert SECRET not in blob, f\\\"serve API key reached the APM: {blob}\\\"\\n\\n\\ndef test_redaction_keeps_the_route_an_operator_needs():\\n    \\\"\\\"\\\"Blanking everything would be safe and useless; path and method must survive.\\\"\\\"\\\"\\n    result = run_probe(SERVER_SPAN_PROBE)\\n    assert result[\\\"spans\\\"], \\\"expected a server span carrying url.path\\\"\\n    attrs = result[\\\"spans\\\"][0][\\\"attrs\\\"]\\n\\n    assert attrs[\\\"url.path\\\"] == \\\"/flows/run\\\"\\n    assert attrs[\\\"url.query\\\"] == \\\"\\\"\\n    assert attrs[\\\"http.request.method\\\"] == \\\"GET\\\"\\n\\n\\n# The server span carries the credential in a query string, which is the leak that prompted the\\n# redaction. It is not the only shape: ``http.url`` and ``url.full`` carry a whole URL, and the\\n# vendors that document a collector endpoint with userinfo in the authority put the credential\\n# there instead. The redaction handles both; only the query half was covered.\\nUSERINFO_SPAN_PROBE = f\\\"\\\"\\\"\\nimport json\\n\\nfrom opentelemetry import trace\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\nfrom lfx.observability import APPLICATION_TRACER_NAME, ApplicationOnlySpanProcessor\\n\\nexporter = InMemorySpanExporter()\\nprovider = TracerProvider()\\nprovider.add_span_processor(ApplicationOnlySpanProcessor(exporter))\\ntrace.set_tracer_provider(provider)\\n\\nSECRET = {SECRET!r}\\n\\ntracer = trace.get_tracer(APPLICATION_TRACER_NAME)\\nwith tracer.start_as_current_span(\\\"probe.outbound\\\") as span:\\n    span.set_attribute(\\\"http.url\\\", f\\\"https://svc:{{SECRET}}@db.internal:5432/records?token={{SECRET}}\\\")\\n    span.set_attribute(\\\"url.full\\\", f\\\"https://svc:{{SECRET}}@db.internal:5432/records?token={{SECRET}}\\\")\\n    span.set_attribute(\\\"http.target\\\", f\\\"/records?token={{SECRET}}\\\")\\n    span.set_attribute(\\\"server.address\\\", \\\"db.internal\\\")\\n\\nprovider.force_flush()\\nspans = [{{\\\"name\\\": s.name, \\\"attrs\\\": dict(s.attributes or {{}})}} for s in exporter.get_finished_spans()]\\nprint(\\\"PROBE_RESULT \\\" + json.dumps({{\\\"spans\\\": spans}}))\\n\\\"\\\"\\\"\\n\\n\\ndef test_a_credential_in_the_authority_never_reaches_the_apm():\\n    \\\"\\\"\\\"Userinfo is the other half of the same leak, and several vendors document it that way.\\\"\\\"\\\"\\n    result = run_probe(USERINFO_SPAN_PROBE)\\n\\n    assert result[\\\"spans\\\"], \\\"expected the probe span\\\"\\n    assert SECRET not in json.dumps(result[\\\"spans\\\"]), f\\\"a URL credential reached the APM: {result['spans']}\\\"\\n\\n\\ndef test_redaction_keeps_the_host_and_path_an_operator_needs():\\n    \\\"\\\"\\\"Blanking the URL entirely would pass the test above and lose the point of the attribute.\\\"\\\"\\\"\\n    result = run_probe(USERINFO_SPAN_PROBE)\\n    # Asserted before indexing: an empty list would otherwise surface as an IndexError, which\\n    # says nothing about why the probe produced no span.\\n    assert result[\\\"spans\\\"], \\\"expected the probe span\\\"\\n    attrs = result[\\\"spans\\\"][0][\\\"attrs\\\"]\\n\\n    for key in (\\\"http.url\\\", \\\"url.full\\\"):\\n        assert attrs[key] == \\\"https://db.internal:5432/records\\\", attrs[key]\\n    # http.target too, and by value: the probe sets it, so blanking it would pass the\\n    # secret-is-absent check above while losing the route the attribute exists to carry.\\n    assert attrs[\\\"http.target\\\"] == \\\"/records\\\", attrs[\\\"http.target\\\"]\\n    # Nothing outside the URL attributes is touched.\\n    assert attrs[\\\"server.address\\\"] == \\\"db.internal\\\"\\n\\n\\ndef test_outbound_http_scopes_stay_out_of_the_allowlist():\\n    \\\"\\\"\\\"Redacting URLs does not make the LLM transports safe to export; that boundary stands.\\\"\\\"\\\"\\n    for scope in (\\n        \\\"opentelemetry.instrumentation.httpx\\\",\\n        \\\"opentelemetry.instrumentation.requests\\\",\\n        \\\"opentelemetry.instrumentation.urllib3\\\",\\n    ):\\n        assert scope not in APPLICATION_INSTRUMENTATION_SCOPES\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_telemetry_reexports.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aaeabaa9dd39992e0d9dc4f01bd510216ad0a14fe56c797d651a3628db2ba8f0\",\"content\":\"\\\"\\\"\\\"Unit tests for the stable telemetry extension-point re-exports.\\n\\nVerifies that enterprise consumers can import pop_all and append_run_event\\nfrom the stable langflow.services.telemetry package path and that the\\nfunctions are the same objects as those in the internal module.\\n\\nThese tests are the CI gate for the public API contract described in\\nrun_event_store.py.  A rename, removal, or signature change in that\\nmodule will cause one of the assertions below to fail before any\\nenterprise consumer is broken.\\n\\\"\\\"\\\"\\n\\nimport inspect\\n\\nfrom langflow.services import telemetry as telemetry_pkg\\nfrom langflow.services.telemetry import append_run_event, pop_all\\nfrom langflow.services.telemetry import run_event_store as _store\\n\\n\\ndef test_pop_all_reexported_from_package():\\n    assert pop_all is _store.pop_all\\n\\n\\ndef test_append_run_event_reexported_from_package():\\n    assert append_run_event is _store.append_run_event\\n\\n\\ndef test_reexports_present_in_all():\\n    assert \\\"pop_all\\\" in telemetry_pkg.__all__\\n    assert \\\"append_run_event\\\" in telemetry_pkg.__all__\\n\\n\\n# ---------------------------------------------------------------------------\\n# Public API contract \u2014 signature shape\\n# These break if a future refactor renames, removes, or changes the arity of\\n# the two stable extension-point functions.\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_pop_all_takes_no_parameters():\\n    \\\"\\\"\\\"pop_all() must remain a zero-argument callable (enterprise callers pass none).\\\"\\\"\\\"\\n    sig = inspect.signature(pop_all)\\n    assert list(sig.parameters.values()) == []\\n\\n\\ndef test_append_run_event_accepts_single_payload_param():\\n    \\\"\\\"\\\"append_run_event(payload) must keep exactly one required positional parameter.\\\"\\\"\\\"\\n    sig = inspect.signature(append_run_event)\\n    assert list(sig.parameters) == [\\\"payload\\\"]\\n    payload_param = sig.parameters[\\\"payload\\\"]\\n    assert payload_param.kind is inspect.Parameter.POSITIONAL_OR_KEYWORD\\n    assert payload_param.default is inspect.Parameter.empty\\n\\n\\ndef test_stable_import_path_resolves():\\n    \\\"\\\"\\\"The documented import path must resolve without ImportError.\\n\\n    This is a belt-and-suspenders guard: the import at the top of this\\n    module already exercises it, but an explicit assertion makes the\\n    intent clear to future maintainers.\\n    \\\"\\\"\\\"\\n    import importlib\\n\\n    mod = importlib.import_module(\\\"langflow.services.telemetry\\\")\\n    assert callable(getattr(mod, \\\"pop_all\\\", None)), \\\"pop_all missing from langflow.services.telemetry\\\"\\n    assert callable(getattr(mod, \\\"append_run_event\\\", None)), \\\"append_run_event missing from langflow.services.telemetry\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Functional smoke-test\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_append_then_pop_roundtrip():\\n    \\\"\\\"\\\"Functional smoke-test through the re-exported symbols.\\\"\\\"\\\"\\n    # drain any leftover state from other tests\\n    pop_all()\\n\\n    from langflow.services.telemetry.schema import RunPayload\\n\\n    payload = RunPayload(\\n        run_seconds=1,\\n        run_success=True,\\n    )\\n    append_run_event(payload)\\n    drained = pop_all()\\n\\n    assert len(drained) == 1\\n    assert drained[0].model_dump() == payload.model_dump()\\n    # store is empty after pop\\n    assert pop_all() == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_telemetry_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1461c72ca1c89f3699a85659bcde5f9b8440a7df7af386988f542b92a2eda8ea\",\"content\":\"\\\"\\\"\\\"Comprehensive unit tests for telemetry schema classes.\\n\\nTesting library and framework: pytest\\n\\\"\\\"\\\"\\n\\nimport re\\n\\nimport pytest\\nfrom langflow.services.telemetry.schema import (\\n    ComponentPayload,\\n    DeploymentPayload,\\n    EmailPayload,\\n    PlaygroundPayload,\\n    RunPayload,\\n    ShutdownPayload,\\n    VersionPayload,\\n)\\n\\n\\nclass TestDeploymentPayload:\\n    \\\"\\\"\\\"Test cases for DeploymentPayload.\\\"\\\"\\\"\\n\\n    def test_deployment_payload_initialization_with_valid_data(self):\\n        \\\"\\\"\\\"Test DeploymentPayload initialization with valid parameters.\\\"\\\"\\\"\\n        payload = DeploymentPayload(\\n            deployment_action=\\\"deployment.create\\\",\\n            deployment_provider=\\\"test_provider\\\",\\n            deployment_seconds=1.5,\\n            deployment_success=True,\\n            deployment_error_message=\\\"\\\",\\n            wxo_tenant_id=\\\"tenant-abc\\\",\\n            client_type=\\\"oss\\\",\\n        )\\n\\n        assert payload.deployment_action == \\\"deployment.create\\\"\\n        assert payload.deployment_provider == \\\"test_provider\\\"\\n        assert payload.deployment_seconds == 1.5\\n        assert payload.deployment_success is True\\n        assert payload.deployment_error_message == \\\"\\\"\\n        assert payload.wxo_tenant_id == \\\"tenant-abc\\\"\\n        assert payload.client_type == \\\"oss\\\"\\n\\n    def test_deployment_payload_initialization_with_defaults(self):\\n        \\\"\\\"\\\"Test DeploymentPayload initialization with default values.\\\"\\\"\\\"\\n        payload = DeploymentPayload(\\n            deployment_action=\\\"deployment.delete\\\",\\n            deployment_provider=\\\"test_provider\\\",\\n            deployment_seconds=0.5,\\n            deployment_success=False,\\n            deployment_error_message=\\\"404: Provider not found.\\\",\\n        )\\n\\n        assert payload.deployment_action == \\\"deployment.delete\\\"\\n        assert payload.deployment_provider == \\\"test_provider\\\"\\n        assert payload.deployment_seconds == 0.5\\n        assert payload.deployment_success is False\\n        assert payload.deployment_error_message == \\\"404: Provider not found.\\\"\\n        assert payload.wxo_tenant_id is None  # Default value\\n        assert payload.client_type is None  # Default value\\n\\n    def test_deployment_payload_serialization(self):\\n        \\\"\\\"\\\"Test DeploymentPayload serialization to dictionary.\\\"\\\"\\\"\\n        payload = DeploymentPayload(\\n            deployment_action=\\\"deployment.update\\\",\\n            deployment_provider=\\\"test_provider\\\",\\n            deployment_seconds=2.0,\\n            deployment_success=True,\\n            deployment_error_message=\\\"\\\",\\n            wxo_tenant_id=\\\"tenant-xyz\\\",\\n            client_type=\\\"desktop\\\",\\n        )\\n\\n        data = payload.model_dump(by_alias=True, exclude_none=True)\\n\\n        assert data[\\\"deploymentAction\\\"] == \\\"deployment.update\\\"\\n        assert data[\\\"deploymentProvider\\\"] == \\\"test_provider\\\"\\n        assert data[\\\"deploymentSeconds\\\"] == 2.0\\n        assert data[\\\"deploymentSuccess\\\"] is True\\n        assert data[\\\"deploymentErrorMessage\\\"] == \\\"\\\"\\n        assert data[\\\"wxoTenantId\\\"] == \\\"tenant-xyz\\\"\\n        assert data[\\\"clientType\\\"] == \\\"desktop\\\"\\n\\n    def test_deployment_payload_roundtrip(self):\\n        \\\"\\\"\\\"Test DeploymentPayload roundtrip serialization.\\\"\\\"\\\"\\n        payload = DeploymentPayload(\\n            deployment_action=\\\"provider.create\\\",\\n            deployment_provider=\\\"test_provider\\\",\\n            deployment_seconds=1.0,\\n            deployment_success=False,\\n            deployment_error_message=\\\"500: Adapter exploded.\\\",\\n            wxo_tenant_id=\\\"tenant-abc\\\",\\n            client_type=\\\"oss\\\",\\n        )\\n\\n        data = payload.model_dump()\\n        new_payload = DeploymentPayload(**data)\\n\\n        assert new_payload.deployment_action == payload.deployment_action\\n        assert new_payload.deployment_provider == payload.deployment_provider\\n        assert new_payload.deployment_seconds == payload.deployment_seconds\\n        assert new_payload.deployment_success == payload.deployment_success\\n        assert new_payload.deployment_error_message == payload.deployment_error_message\\n        assert new_payload.wxo_tenant_id == payload.wxo_tenant_id\\n        assert new_payload.client_type == payload.client_type\\n\\n\\nclass TestRunPayload:\\n    \\\"\\\"\\\"Test cases for RunPayload.\\\"\\\"\\\"\\n\\n    def test_run_payload_initialization_with_valid_data(self):\\n        \\\"\\\"\\\"Test RunPayload initialization with valid parameters.\\\"\\\"\\\"\\n        payload = RunPayload(\\n            run_is_webhook=True,\\n            run_seconds=120,\\n            run_success=True,\\n            run_error_message=\\\"\\\",\\n            client_type=\\\"oss\\\",\\n            run_id=None,\\n        )\\n\\n        assert payload.run_is_webhook is True\\n        assert payload.run_seconds == 120\\n        assert payload.run_success is True\\n        assert payload.run_error_message == \\\"\\\"\\n        assert payload.client_type == \\\"oss\\\"\\n        assert payload.run_id is None\\n\\n    def test_run_payload_initialization_with_defaults(self):\\n        \\\"\\\"\\\"Test RunPayload initialization with default values.\\\"\\\"\\\"\\n        payload = RunPayload(\\n            run_seconds=60,\\n            run_success=False,\\n            run_error_message=\\\"Test error\\\",\\n            run_id=None,\\n        )\\n\\n        assert payload.run_is_webhook is False  # Default value\\n        assert payload.run_seconds == 60\\n        assert payload.run_success is False\\n        assert payload.run_error_message == \\\"Test error\\\"\\n        assert payload.client_type is None  # Default value\\n        assert payload.run_id is None\\n\\n    def test_run_payload_serialization(self):\\n        \\\"\\\"\\\"Test RunPayload serialization to dictionary.\\\"\\\"\\\"\\n        payload = RunPayload(\\n            run_is_webhook=True,\\n            run_seconds=180,\\n            run_success=True,\\n            run_error_message=\\\"\\\",\\n            client_type=\\\"desktop\\\",\\n            run_id=None,\\n        )\\n\\n        data = payload.model_dump(by_alias=True)\\n\\n        assert data[\\\"runIsWebhook\\\"] is True\\n        assert data[\\\"runSeconds\\\"] == 180\\n        assert data[\\\"runSuccess\\\"] is True\\n        assert data[\\\"runErrorMessage\\\"] == \\\"\\\"\\n        assert data[\\\"clientType\\\"] == \\\"desktop\\\"\\n        assert data[\\\"runId\\\"] is None\\n\\n    def test_run_payload_with_negative_seconds(self):\\n        \\\"\\\"\\\"Test RunPayload accepts negative seconds (no validation in schema).\\\"\\\"\\\"\\n        payload = RunPayload(\\n            run_seconds=-10,\\n            run_success=True,\\n            run_error_message=\\\"\\\",\\n            run_id=None,\\n        )\\n        assert payload.run_seconds == -10\\n        assert payload.run_success is True\\n\\n    def test_run_payload_with_long_error_message(self):\\n        \\\"\\\"\\\"Test RunPayload with long error message.\\\"\\\"\\\"\\n        long_error = \\\"x\\\" * 1000\\n        payload = RunPayload(\\n            run_seconds=30,\\n            run_success=False,\\n            run_error_message=long_error,\\n            client_type=\\\"oss\\\",\\n            run_id=None,\\n        )\\n\\n        assert payload.run_error_message == long_error\\n        assert len(payload.run_error_message) == 1000\\n\\n\\nclass TestShutdownPayload:\\n    \\\"\\\"\\\"Test cases for ShutdownPayload.\\\"\\\"\\\"\\n\\n    def test_shutdown_payload_initialization(self):\\n        \\\"\\\"\\\"Test ShutdownPayload initialization with valid parameters.\\\"\\\"\\\"\\n        payload = ShutdownPayload(time_running=3600, client_type=\\\"oss\\\")\\n\\n        assert payload.time_running == 3600\\n        assert payload.client_type == \\\"oss\\\"\\n\\n    def test_shutdown_payload_initialization_without_client_type(self):\\n        \\\"\\\"\\\"Test ShutdownPayload initialization without client_type.\\\"\\\"\\\"\\n        payload = ShutdownPayload(time_running=1800)\\n\\n        assert payload.time_running == 1800\\n        assert payload.client_type is None\\n\\n    def test_shutdown_payload_serialization(self):\\n        \\\"\\\"\\\"Test ShutdownPayload serialization to dictionary.\\\"\\\"\\\"\\n        payload = ShutdownPayload(time_running=7200, client_type=\\\"desktop\\\")\\n\\n        data = payload.model_dump(by_alias=True)\\n\\n        assert data[\\\"timeRunning\\\"] == 7200\\n        assert data[\\\"clientType\\\"] == \\\"desktop\\\"\\n\\n    def test_shutdown_payload_with_negative_time(self):\\n        \\\"\\\"\\\"Test ShutdownPayload accepts negative time (no validation in schema).\\\"\\\"\\\"\\n        payload = ShutdownPayload(time_running=-100)\\n        assert payload.time_running == -100\\n\\n    def test_shutdown_payload_with_zero_time(self):\\n        \\\"\\\"\\\"Test ShutdownPayload with zero time running.\\\"\\\"\\\"\\n        payload = ShutdownPayload(time_running=0)\\n        assert payload.time_running == 0\\n\\n\\nclass TestEmailPayload:\\n    \\\"\\\"\\\"Test cases for EmailPayload.\\\"\\\"\\\"\\n\\n    CLIENT_TYPE_DESKTOP: str = \\\"desktop\\\"\\n    TEST_EMAIL_1: str = \\\"test@ibm.com\\\"\\n\\n    def test_email_payload_initialization(self):\\n        \\\"\\\"\\\"Test EmailPayload initialization with valid parameters.\\\"\\\"\\\"\\n        payload = EmailPayload(\\n            client_type=self.CLIENT_TYPE_DESKTOP,\\n            email=self.TEST_EMAIL_1,\\n        )\\n\\n        assert payload.client_type == self.CLIENT_TYPE_DESKTOP\\n        assert payload.email == self.TEST_EMAIL_1\\n\\n    def test_email_payload_initialization_without_client_type(self):\\n        \\\"\\\"\\\"Test EmailPayload initialization without client_type.\\\"\\\"\\\"\\n        payload = EmailPayload(\\n            email=self.TEST_EMAIL_1,\\n        )\\n\\n        assert payload.client_type is None\\n        assert payload.email == self.TEST_EMAIL_1\\n\\n    def test_email_payload_initialization_with_invalid_email(self):\\n        \\\"\\\"\\\"Test EmailPayload initialization with an invalid email.\\\"\\\"\\\"\\n        payload = None\\n        error_message: str = (\\n            \\\"value is not a valid email address: The part after the @-sign is not valid. It should have a period.\\\"\\n        )\\n\\n        with pytest.raises(ValueError, match=re.escape(error_message)):\\n            payload = EmailPayload(\\n                client_type=self.CLIENT_TYPE_DESKTOP,\\n                email=\\\"test@ibm\\\",\\n            )\\n\\n        assert payload is None\\n\\n    def test_email_payload_serialization(self):\\n        \\\"\\\"\\\"Test EmailPayload serialization to dictionary.\\\"\\\"\\\"\\n        payload = EmailPayload(\\n            client_type=self.CLIENT_TYPE_DESKTOP,\\n            email=self.TEST_EMAIL_1,\\n        )\\n\\n        data = payload.model_dump(by_alias=True)\\n\\n        assert data[\\\"clientType\\\"] == self.CLIENT_TYPE_DESKTOP\\n        assert data[\\\"email\\\"] == self.TEST_EMAIL_1\\n\\n\\nclass TestVersionPayload:\\n    \\\"\\\"\\\"Test cases for VersionPayload.\\\"\\\"\\\"\\n\\n    def test_version_payload_initialization(self):\\n        \\\"\\\"\\\"Test VersionPayload initialization with valid parameters.\\\"\\\"\\\"\\n        payload = VersionPayload(\\n            package=\\\"langflow\\\",\\n            version=\\\"1.0.0\\\",\\n            platform=\\\"Linux-5.4.0\\\",\\n            python=\\\"3.9\\\",\\n            arch=\\\"x86_64\\\",\\n            auto_login=False,\\n            cache_type=\\\"memory\\\",\\n            backend_only=False,\\n            client_type=\\\"oss\\\",\\n        )\\n\\n        assert payload.package == \\\"langflow\\\"\\n        assert payload.version == \\\"1.0.0\\\"\\n        assert payload.platform == \\\"Linux-5.4.0\\\"\\n        assert payload.python == \\\"3.9\\\"\\n        assert payload.arch == \\\"x86_64\\\"\\n        assert payload.auto_login is False\\n        assert payload.cache_type == \\\"memory\\\"\\n        assert payload.backend_only is False\\n        assert payload.client_type == \\\"oss\\\"\\n\\n    def test_version_payload_initialization_with_all_required_fields(self):\\n        \\\"\\\"\\\"Test VersionPayload initialization with all required fields.\\\"\\\"\\\"\\n        payload = VersionPayload(\\n            package=\\\"langflow\\\",\\n            version=\\\"1.0.0\\\",\\n            platform=\\\"Windows\\\",\\n            python=\\\"3.8\\\",\\n            arch=\\\"x86_64\\\",\\n            auto_login=True,\\n            cache_type=\\\"redis\\\",\\n            backend_only=True,\\n        )\\n\\n        assert payload.package == \\\"langflow\\\"\\n        assert payload.version == \\\"1.0.0\\\"\\n        assert payload.client_type is None  # Default value\\n\\n    def test_version_payload_serialization(self):\\n        \\\"\\\"\\\"Test VersionPayload serialization to dictionary.\\\"\\\"\\\"\\n        payload = VersionPayload(\\n            package=\\\"langflow\\\",\\n            version=\\\"1.5.2\\\",\\n            platform=\\\"macOS-12.0\\\",\\n            python=\\\"3.10\\\",\\n            arch=\\\"arm64\\\",\\n            auto_login=True,\\n            cache_type=\\\"redis\\\",\\n            backend_only=True,\\n            client_type=\\\"desktop\\\",\\n        )\\n\\n        data = payload.model_dump(by_alias=True)\\n\\n        assert data[\\\"package\\\"] == \\\"langflow\\\"\\n        assert data[\\\"version\\\"] == \\\"1.5.2\\\"\\n        assert data[\\\"platform\\\"] == \\\"macOS-12.0\\\"\\n        assert data[\\\"python\\\"] == \\\"3.10\\\"\\n        assert data[\\\"arch\\\"] == \\\"arm64\\\"\\n        assert data[\\\"autoLogin\\\"] is True\\n        assert data[\\\"cacheType\\\"] == \\\"redis\\\"\\n        assert data[\\\"backendOnly\\\"] is True\\n        assert data[\\\"clientType\\\"] == \\\"desktop\\\"\\n\\n    def test_version_payload_with_special_characters(self):\\n        \\\"\\\"\\\"Test VersionPayload with special characters in strings.\\\"\\\"\\\"\\n        payload = VersionPayload(\\n            package=\\\"langflow-dev\\\",\\n            version=\\\"1.0.0-beta.1\\\",\\n            platform=\\\"Windows 10 Pro\\\",\\n            python=\\\"3.9.7\\\",\\n            arch=\\\"x86_64\\\",\\n            auto_login=False,\\n            cache_type=\\\"memory\\\",\\n            backend_only=False,\\n        )\\n\\n        assert payload.package == \\\"langflow-dev\\\"\\n        assert payload.version == \\\"1.0.0-beta.1\\\"\\n        assert payload.platform == \\\"Windows 10 Pro\\\"\\n\\n\\nclass TestPlaygroundPayload:\\n    \\\"\\\"\\\"Test cases for PlaygroundPayload.\\\"\\\"\\\"\\n\\n    def test_playground_payload_initialization(self):\\n        \\\"\\\"\\\"Test PlaygroundPayload initialization with valid parameters.\\\"\\\"\\\"\\n        payload = PlaygroundPayload(\\n            playground_seconds=45,\\n            playground_component_count=5,\\n            playground_success=True,\\n            playground_error_message=\\\"\\\",\\n            client_type=\\\"oss\\\",\\n            playground_run_id=None,\\n        )\\n\\n        assert payload.playground_seconds == 45\\n        assert payload.playground_component_count == 5\\n        assert payload.playground_success is True\\n        assert payload.playground_error_message == \\\"\\\"\\n        assert payload.client_type == \\\"oss\\\"\\n        assert payload.playground_run_id is None\\n\\n    def test_playground_payload_initialization_with_none_component_count(self):\\n        \\\"\\\"\\\"Test PlaygroundPayload initialization with None component count.\\\"\\\"\\\"\\n        payload = PlaygroundPayload(\\n            playground_seconds=30,\\n            playground_component_count=None,\\n            playground_success=True,\\n            playground_error_message=\\\"\\\",\\n            playground_run_id=None,\\n        )\\n\\n        assert payload.playground_seconds == 30\\n        assert payload.playground_component_count is None\\n        assert payload.playground_success is True\\n\\n    def test_playground_payload_serialization(self):\\n        \\\"\\\"\\\"Test PlaygroundPayload serialization to dictionary.\\\"\\\"\\\"\\n        payload = PlaygroundPayload(\\n            playground_seconds=60,\\n            playground_component_count=10,\\n            playground_success=False,\\n            playground_error_message=\\\"Component failed\\\",\\n            client_type=\\\"desktop\\\",\\n            playground_run_id=None,\\n        )\\n\\n        data = payload.model_dump(by_alias=True)\\n\\n        assert data[\\\"playgroundSeconds\\\"] == 60\\n        assert data[\\\"playgroundComponentCount\\\"] == 10\\n        assert data[\\\"playgroundSuccess\\\"] is False\\n        assert data[\\\"playgroundErrorMessage\\\"] == \\\"Component failed\\\"\\n        assert data[\\\"clientType\\\"] == \\\"desktop\\\"\\n        assert data[\\\"playgroundRunId\\\"] is None\\n\\n    def test_playground_payload_with_negative_seconds(self):\\n        \\\"\\\"\\\"Test PlaygroundPayload accepts negative seconds (no validation in schema).\\\"\\\"\\\"\\n        payload = PlaygroundPayload(\\n            playground_seconds=-10,\\n            playground_component_count=0,\\n            playground_success=True,\\n            playground_error_message=\\\"\\\",\\n            playground_run_id=None,\\n        )\\n        assert payload.playground_seconds == -10\\n        assert payload.playground_success is True\\n\\n    def test_playground_payload_with_negative_component_count(self):\\n        \\\"\\\"\\\"Test PlaygroundPayload accepts negative component count (no validation in schema).\\\"\\\"\\\"\\n        payload = PlaygroundPayload(\\n            playground_seconds=30,\\n            playground_component_count=-5,\\n            playground_success=True,\\n            playground_error_message=\\\"\\\",\\n            playground_run_id=None,\\n        )\\n        assert payload.playground_component_count == -5\\n        assert payload.playground_success is True\\n\\n    def test_playground_payload_with_failed_execution(self):\\n        \\\"\\\"\\\"Test PlaygroundPayload with failed execution.\\\"\\\"\\\"\\n        payload = PlaygroundPayload(\\n            playground_seconds=15,\\n            playground_component_count=3,\\n            playground_success=False,\\n            playground_error_message=\\\"Timeout occurred\\\",\\n            client_type=\\\"oss\\\",\\n            playground_run_id=None,\\n        )\\n\\n        assert payload.playground_success is False\\n        assert payload.playground_error_message == \\\"Timeout occurred\\\"\\n\\n\\nclass TestComponentPayload:\\n    \\\"\\\"\\\"Test cases for ComponentPayload.\\\"\\\"\\\"\\n\\n    def test_component_payload_initialization(self):\\n        \\\"\\\"\\\"Test ComponentPayload initialization with valid parameters.\\\"\\\"\\\"\\n        payload = ComponentPayload(\\n            component_name=\\\"TextInput\\\",\\n            component_id=\\\"comp-123\\\",\\n            component_seconds=2,\\n            component_success=True,\\n            component_error_message=None,\\n            client_type=\\\"oss\\\",\\n            component_run_id=None,\\n        )\\n\\n        assert payload.component_name == \\\"TextInput\\\"\\n        assert payload.component_seconds == 2\\n        assert payload.component_success is True\\n        assert payload.component_error_message is None\\n        assert payload.client_type == \\\"oss\\\"\\n        assert payload.component_run_id is None\\n\\n    def test_component_payload_initialization_with_error(self):\\n        \\\"\\\"\\\"Test ComponentPayload initialization with error message.\\\"\\\"\\\"\\n        payload = ComponentPayload(\\n            component_name=\\\"LLMChain\\\",\\n            component_id=\\\"comp-456\\\",\\n            component_seconds=5,\\n            component_success=False,\\n            component_error_message=\\\"API rate limit exceeded\\\",\\n            client_type=\\\"desktop\\\",\\n            component_run_id=None,\\n        )\\n\\n        assert payload.component_name == \\\"LLMChain\\\"\\n        assert payload.component_seconds == 5\\n        assert payload.component_success is False\\n        assert payload.component_error_message == \\\"API rate limit exceeded\\\"\\n        assert payload.client_type == \\\"desktop\\\"\\n        assert payload.component_run_id is None\\n\\n    def test_component_payload_serialization(self):\\n        \\\"\\\"\\\"Test ComponentPayload serialization to dictionary.\\\"\\\"\\\"\\n        payload = ComponentPayload(\\n            component_name=\\\"OpenAI\\\",\\n            component_id=\\\"comp-789\\\",\\n            component_seconds=3,\\n            component_success=True,\\n            component_error_message=None,\\n            client_type=\\\"oss\\\",\\n            component_run_id=None,\\n        )\\n\\n        data = payload.model_dump(by_alias=True)\\n\\n        assert data[\\\"componentName\\\"] == \\\"OpenAI\\\"\\n        assert data[\\\"componentSeconds\\\"] == 3\\n        assert data[\\\"componentSuccess\\\"] is True\\n        assert data[\\\"componentErrorMessage\\\"] is None\\n        assert data[\\\"clientType\\\"] == \\\"oss\\\"\\n        assert data[\\\"componentRunId\\\"] is None\\n\\n    def test_component_payload_with_negative_seconds(self):\\n        \\\"\\\"\\\"Test ComponentPayload accepts negative seconds (no validation in schema).\\\"\\\"\\\"\\n        payload = ComponentPayload(\\n            component_name=\\\"TestComponent\\\",\\n            component_id=\\\"comp-neg\\\",\\n            component_seconds=-1,\\n            component_success=True,\\n            component_error_message=None,\\n            component_run_id=None,\\n        )\\n        assert payload.component_seconds == -1\\n        assert payload.component_success is True\\n\\n    def test_component_payload_with_empty_name(self):\\n        \\\"\\\"\\\"Test ComponentPayload with empty component name.\\\"\\\"\\\"\\n        payload = ComponentPayload(\\n            component_name=\\\"\\\",\\n            component_id=\\\"comp-empty\\\",\\n            component_seconds=1,\\n            component_success=True,\\n            component_error_message=None,\\n            component_run_id=None,\\n        )\\n        assert payload.component_name == \\\"\\\"\\n        assert payload.component_success is True\\n\\n    def test_component_payload_with_special_characters_in_name(self):\\n        \\\"\\\"\\\"Test ComponentPayload with special characters in component name.\\\"\\\"\\\"\\n        payload = ComponentPayload(\\n            component_name=\\\"Custom-Component_v1.0\\\",\\n            component_id=\\\"comp-special\\\",\\n            component_seconds=1,\\n            component_success=True,\\n            component_error_message=None,\\n            component_run_id=None,\\n        )\\n\\n        assert payload.component_name == \\\"Custom-Component_v1.0\\\"\\n\\n\\nclass TestPayloadEdgeCases:\\n    \\\"\\\"\\\"Test edge cases and boundary conditions for all payloads.\\\"\\\"\\\"\\n\\n    def test_run_payload_with_extremely_large_values(self):\\n        \\\"\\\"\\\"Test RunPayload with extremely large values.\\\"\\\"\\\"\\n        large_seconds = 2**31 - 1  # Max int32 value\\n\\n        payload = RunPayload(\\n            run_seconds=large_seconds,\\n            run_success=True,\\n            run_error_message=\\\"x\\\" * 10000,\\n            run_id=None,\\n        )\\n\\n        assert payload.run_seconds == large_seconds\\n        assert len(payload.run_error_message) == 10000\\n\\n    def test_shutdown_payload_with_maximum_time(self):\\n        \\\"\\\"\\\"Test ShutdownPayload with maximum time value.\\\"\\\"\\\"\\n        max_time = 2**31 - 1\\n\\n        payload = ShutdownPayload(time_running=max_time)\\n        assert payload.time_running == max_time\\n\\n    def test_version_payload_with_unicode_strings(self):\\n        \\\"\\\"\\\"Test VersionPayload with unicode strings.\\\"\\\"\\\"\\n        payload = VersionPayload(\\n            package=\\\"langflow-\ud83d\ude80\\\",\\n            version=\\\"1.0.0-\u6d4b\u8bd5\\\",\\n            platform=\\\"Linux-\u6d4b\u8bd5\u7cfb\u7edf\\\",\\n            python=\\\"3.9\\\",\\n            arch=\\\"x86_64\\\",\\n            auto_login=False,\\n            cache_type=\\\"memory\\\",\\n            backend_only=False,\\n        )\\n\\n        assert payload.package == \\\"langflow-\ud83d\ude80\\\"\\n        assert payload.version == \\\"1.0.0-\u6d4b\u8bd5\\\"\\n        assert payload.platform == \\\"Linux-\u6d4b\u8bd5\u7cfb\u7edf\\\"\\n\\n    def test_playground_payload_with_zero_values(self):\\n        \\\"\\\"\\\"Test PlaygroundPayload with zero values.\\\"\\\"\\\"\\n        payload = PlaygroundPayload(\\n            playground_seconds=0,\\n            playground_component_count=0,\\n            playground_success=True,\\n            playground_error_message=\\\"\\\",\\n            playground_run_id=None,\\n        )\\n\\n        assert payload.playground_seconds == 0\\n        assert payload.playground_component_count == 0\\n\\n    def test_component_payload_with_very_long_name(self):\\n        \\\"\\\"\\\"Test ComponentPayload with very long component name.\\\"\\\"\\\"\\n        long_name = \\\"x\\\" * 1000\\n\\n        payload = ComponentPayload(\\n            component_name=long_name,\\n            component_id=\\\"comp-long\\\",\\n            component_seconds=1,\\n            component_success=True,\\n            component_error_message=None,\\n            component_run_id=None,\\n        )\\n\\n        assert payload.component_name == long_name\\n        assert len(payload.component_name) == 1000\\n\\n    @pytest.mark.parametrize(\\\"client_type\\\", [\\\"oss\\\", \\\"desktop\\\", \\\"cloud\\\", \\\"enterprise\\\", \\\"custom\\\"])\\n    def test_all_payloads_with_different_client_types(self, client_type):\\n        \\\"\\\"\\\"Test all payloads with different client types.\\\"\\\"\\\"\\n        # Test RunPayload\\n        run_payload = RunPayload(\\n            run_seconds=60,\\n            run_success=True,\\n            client_type=client_type,\\n            run_error_message=\\\"\\\",\\n            run_id=None,\\n        )\\n        assert run_payload.client_type == client_type\\n\\n        # Test ShutdownPayload\\n        shutdown_payload = ShutdownPayload(time_running=3600, client_type=client_type)\\n        assert shutdown_payload.client_type == client_type\\n\\n        # Test VersionPayload\\n        version_payload = VersionPayload(\\n            package=\\\"langflow\\\",\\n            version=\\\"1.0.0\\\",\\n            platform=\\\"Linux\\\",\\n            python=\\\"3.9\\\",\\n            arch=\\\"x86_64\\\",\\n            auto_login=False,\\n            cache_type=\\\"memory\\\",\\n            backend_only=False,\\n            client_type=client_type,\\n        )\\n        assert version_payload.client_type == client_type\\n\\n        # Test PlaygroundPayload\\n        playground_payload = PlaygroundPayload(\\n            playground_seconds=30,\\n            playground_component_count=0,\\n            playground_success=True,\\n            client_type=client_type,\\n            playground_error_message=\\\"\\\",\\n            playground_run_id=None,\\n        )\\n        assert playground_payload.client_type == client_type\\n\\n        # Test ComponentPayload\\n        component_payload = ComponentPayload(\\n            component_name=\\\"TestComponent\\\",\\n            component_id=\\\"comp-test\\\",\\n            component_seconds=1,\\n            component_success=True,\\n            component_error_message=None,\\n            client_type=client_type,\\n            component_run_id=None,\\n        )\\n        assert component_payload.client_type == client_type\\n\\n    def test_payload_serialization_with_none_values(self):\\n        \\\"\\\"\\\"Test payload serialization when optional fields are None.\\\"\\\"\\\"\\n        # Test with client_type as None\\n        run_payload = RunPayload(run_seconds=60, run_success=True, client_type=None, run_error_message=\\\"\\\", run_id=None)\\n\\n        data = run_payload.model_dump(by_alias=True, exclude_none=True)\\n        assert \\\"clientType\\\" not in data  # Should be excluded when None\\n\\n    def test_payload_serialization_with_empty_strings(self):\\n        \\\"\\\"\\\"Test payload serialization with empty strings.\\\"\\\"\\\"\\n        run_payload = RunPayload(\\n            run_seconds=60,\\n            run_success=True,\\n            run_error_message=\\\"\\\",\\n            client_type=\\\"oss\\\",  # Empty string\\n            run_id=None,\\n        )\\n\\n        data = run_payload.model_dump(by_alias=True)\\n        assert data[\\\"runErrorMessage\\\"] == \\\"\\\"\\n\\n    def test_payload_validation_with_invalid_types(self):\\n        \\\"\\\"\\\"Test payload validation with invalid data types.\\\"\\\"\\\"\\n        # Test RunPayload with string instead of int\\n        with pytest.raises((ValueError, TypeError)):\\n            RunPayload(\\n                run_seconds=\\\"not_a_number\\\",  # type: ignore  # noqa: PGH003\\n                run_success=True,\\n                run_error_message=\\\"\\\",\\n                run_id=None,\\n            )\\n\\n        # Test with boolean instead of string for error message\\n        with pytest.raises((ValueError, TypeError)):\\n            RunPayload(\\n                run_seconds=60,\\n                run_success=True,\\n                run_error_message=True,  # type: ignore  # noqa: PGH003\\n                run_id=None,\\n            )\\n\\n\\nclass TestPayloadIntegration:\\n    \\\"\\\"\\\"Integration tests for payload interactions.\\\"\\\"\\\"\\n\\n    def test_payload_workflow_simulation(self):\\n        \\\"\\\"\\\"Simulate a complete telemetry workflow with all payload types.\\\"\\\"\\\"\\n        # 1. Version payload (startup)\\n        version_payload = VersionPayload(\\n            package=\\\"langflow\\\",\\n            version=\\\"1.0.0\\\",\\n            platform=\\\"Linux\\\",\\n            python=\\\"3.9\\\",\\n            arch=\\\"x86_64\\\",\\n            auto_login=False,\\n            cache_type=\\\"memory\\\",\\n            backend_only=False,\\n            client_type=\\\"oss\\\",\\n        )\\n\\n        # 2. Run payload (flow execution)\\n        run_payload = RunPayload(\\n            run_seconds=120,\\n            run_success=True,\\n            client_type=\\\"oss\\\",\\n            run_error_message=\\\"\\\",\\n            run_id=None,\\n        )\\n\\n        # 3. Component payloads (individual components)\\n        component_payloads = [\\n            ComponentPayload(\\n                component_name=\\\"TextInput\\\",\\n                component_id=\\\"comp-input\\\",\\n                component_seconds=1,\\n                component_success=True,\\n                component_error_message=None,\\n                client_type=\\\"oss\\\",\\n                component_run_id=None,\\n            ),\\n            ComponentPayload(\\n                component_name=\\\"OpenAI\\\",\\n                component_id=\\\"comp-openai\\\",\\n                component_seconds=5,\\n                component_success=True,\\n                component_error_message=None,\\n                client_type=\\\"oss\\\",\\n                component_run_id=None,\\n            ),\\n            ComponentPayload(\\n                component_name=\\\"TextOutput\\\",\\n                component_id=\\\"comp-output\\\",\\n                component_seconds=1,\\n                component_success=True,\\n                component_error_message=None,\\n                client_type=\\\"oss\\\",\\n                component_run_id=None,\\n            ),\\n        ]\\n\\n        # 4. Playground payload (testing)\\n        playground_payload = PlaygroundPayload(\\n            playground_seconds=30,\\n            playground_component_count=3,\\n            playground_success=True,\\n            client_type=\\\"oss\\\",\\n            playground_error_message=\\\"\\\",\\n            playground_run_id=None,\\n        )\\n\\n        # 5. Shutdown payload (cleanup)\\n        shutdown_payload = ShutdownPayload(time_running=3600, client_type=\\\"oss\\\")\\n\\n        # Verify all payloads have consistent client_type\\n        all_payloads = [version_payload, run_payload, playground_payload, shutdown_payload, *component_payloads]\\n        client_types = [p.client_type for p in all_payloads]\\n        assert all(ct == \\\"oss\\\" for ct in client_types)\\n\\n        # Verify timing consistency\\n        total_component_time = sum(cp.component_seconds for cp in component_payloads)\\n        assert total_component_time <= run_payload.run_seconds\\n\\n    def test_error_propagation_workflow(self):\\n        \\\"\\\"\\\"Test error propagation through different payload types.\\\"\\\"\\\"\\n        # Component that fails\\n        failed_component = ComponentPayload(\\n            component_name=\\\"OpenAI\\\",\\n            component_id=\\\"comp-failed\\\",\\n            component_seconds=5,\\n            component_success=False,\\n            component_error_message=\\\"API rate limit exceeded\\\",\\n            client_type=\\\"oss\\\",\\n            component_run_id=None,\\n        )\\n\\n        # Run fails due to component failure\\n        failed_run = RunPayload(\\n            run_seconds=10,\\n            run_success=False,\\n            run_error_message=\\\"Component 'OpenAI' failed: API rate limit exceeded\\\",\\n            client_type=\\\"oss\\\",\\n            run_id=None,\\n        )\\n\\n        # Playground fails\\n        failed_playground = PlaygroundPayload(\\n            playground_seconds=30,\\n            playground_component_count=1,\\n            playground_success=False,\\n            playground_error_message=\\\"Test failed due to component error\\\",\\n            client_type=\\\"oss\\\",\\n            playground_run_id=None,\\n        )\\n\\n        # Verify error consistency\\n        assert not failed_component.component_success\\n        assert not failed_run.run_success\\n        assert not failed_playground.playground_success\\n        assert \\\"API rate limit exceeded\\\" in (failed_component.component_error_message or \\\"\\\")\\n        assert \\\"API rate limit exceeded\\\" in failed_run.run_error_message\\n\\n\\n# Test configuration and fixtures\\n@pytest.fixture\\ndef sample_run_payload():\\n    \\\"\\\"\\\"Fixture providing sample run payload for tests.\\\"\\\"\\\"\\n    return RunPayload(\\n        run_is_webhook=False,\\n        run_seconds=120,\\n        run_success=True,\\n        run_error_message=\\\"\\\",\\n        client_type=\\\"oss\\\",\\n        run_id=None,\\n    )\\n\\n\\n@pytest.fixture\\ndef sample_shutdown_payload():\\n    \\\"\\\"\\\"Fixture providing sample shutdown payload for tests.\\\"\\\"\\\"\\n    return ShutdownPayload(time_running=3600, client_type=\\\"oss\\\")\\n\\n\\n@pytest.fixture\\ndef sample_version_payload():\\n    \\\"\\\"\\\"Fixture providing sample version payload for tests.\\\"\\\"\\\"\\n    return VersionPayload(\\n        package=\\\"langflow\\\",\\n        version=\\\"1.0.0\\\",\\n        platform=\\\"Linux-5.4.0\\\",\\n        python=\\\"3.9\\\",\\n        arch=\\\"x86_64\\\",\\n        auto_login=False,\\n        cache_type=\\\"memory\\\",\\n        backend_only=False,\\n        client_type=\\\"oss\\\",\\n    )\\n\\n\\n@pytest.fixture\\ndef sample_playground_payload():\\n    \\\"\\\"\\\"Fixture providing sample playground payload for tests.\\\"\\\"\\\"\\n    return PlaygroundPayload(\\n        playground_seconds=45,\\n        playground_component_count=5,\\n        playground_success=True,\\n        playground_error_message=\\\"\\\",\\n        client_type=\\\"oss\\\",\\n        playground_run_id=None,\\n    )\\n\\n\\n@pytest.fixture\\ndef sample_component_payload():\\n    \\\"\\\"\\\"Fixture providing sample component payload for tests.\\\"\\\"\\\"\\n    return ComponentPayload(\\n        component_name=\\\"TextInput\\\",\\n        component_id=\\\"comp-fixture\\\",\\n        component_seconds=2,\\n        component_success=True,\\n        component_error_message=None,\\n        client_type=\\\"oss\\\",\\n        component_run_id=None,\\n    )\\n\\n\\n# Performance and stress tests\\nclass TestPayloadPerformance:\\n    \\\"\\\"\\\"Performance tests for payload operations.\\\"\\\"\\\"\\n\\n    def test_payload_creation_performance(self):\\n        \\\"\\\"\\\"Test performance of creating many payload objects.\\\"\\\"\\\"\\n        import time\\n\\n        start_time = time.time()\\n\\n        # Create 1000 payload objects\\n        payloads = []\\n        for i in range(1000):\\n            payload = RunPayload(run_seconds=i, run_success=True, client_type=\\\"oss\\\", run_id=None, run_error_message=\\\"\\\")\\n            payloads.append(payload)\\n\\n        creation_time = time.time() - start_time\\n\\n        # Should create 1000 objects reasonably quickly (under 1 second)\\n        assert creation_time < 1.0\\n        assert len(payloads) == 1000\\n\\n    def test_payload_serialization_performance(self):\\n        \\\"\\\"\\\"Test performance of serializing payload objects.\\\"\\\"\\\"\\n        import time\\n\\n        # Create complex payload\\n        payload = VersionPayload(\\n            package=\\\"langflow\\\",\\n            version=\\\"1.0.0\\\",\\n            platform=\\\"Linux-5.4.0-x86_64-with-glibc2.31\\\",\\n            python=\\\"3.9.7\\\",\\n            arch=\\\"x86_64\\\",\\n            auto_login=True,\\n            cache_type=\\\"redis\\\",\\n            backend_only=False,\\n            client_type=\\\"oss\\\",\\n        )\\n\\n        start_time = time.time()\\n\\n        # Serialize 1000 times\\n        for _ in range(1000):\\n            data = payload.model_dump(by_alias=True)\\n            assert len(data) > 0\\n\\n        serialization_time = time.time() - start_time\\n\\n        # Should serialize 1000 objects reasonably quickly\\n        assert serialization_time < 2.0\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    pytest.main([__file__])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry/test_tracer_provider.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8be6f8c3864c60b042d23b4a1f973af41d5a8551cded256beeb0eb177995b5f5\",\"content\":\"\\\"\\\"\\\"The tracer provider is process-global and installed once, so each case runs in a subprocess.\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\n\\nimport pytest\\n\\nPROBE = \\\"\\\"\\\"\\nimport json, os\\nfrom langflow.services.telemetry.opentelemetry import OpenTelemetry\\nfrom opentelemetry import trace\\n\\nOpenTelemetry(prometheus_enabled=False)\\n\\nprovider = trace.get_tracer_provider()\\nresult = {\\\"provider\\\": type(provider).__name__}\\nresource = getattr(provider, \\\"resource\\\", None)\\nif resource is not None:\\n    result[\\\"service_name\\\"] = resource.attributes.get(\\\"service.name\\\")\\n    result[\\\"deployment_environment\\\"] = resource.attributes.get(\\\"deployment.environment\\\")\\nprocessors = getattr(getattr(provider, \\\"_active_span_processor\\\", None), \\\"_span_processors\\\", ())\\nresult[\\\"exporters\\\"] = [type(p.span_exporter).__module__ for p in processors]\\nprint(\\\"PROBE_RESULT \\\" + json.dumps(result))\\n\\\"\\\"\\\"\\n\\n\\ndef run_probe(env_overrides: dict[str, str]) -> dict:\\n    # Start from a clean slate so the developer's own OTEL_* vars cannot skew the result.\\n    env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"OTEL_\\\")}\\n    env.update(env_overrides)\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", PROBE],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=180,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    line = next(ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\"))\\n    return json.loads(line.removeprefix(\\\"PROBE_RESULT \\\"))\\n\\n\\ndef test_no_endpoint_installs_no_provider():\\n    \\\"\\\"\\\"Local and desktop runs set no OTEL_* vars and must stay inert.\\\"\\\"\\\"\\n    result = run_probe({})\\n    assert result[\\\"provider\\\"] == \\\"ProxyTracerProvider\\\"\\n\\n\\n@pytest.mark.parametrize(\\\"endpoint_var\\\", [\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\", \\\"OTEL_EXPORTER_OTLP_TRACES_ENDPOINT\\\"])\\ndef test_endpoint_installs_sdk_provider(endpoint_var):\\n    result = run_probe({endpoint_var: \\\"http://localhost:4318\\\"})\\n    assert result[\\\"provider\\\"] == \\\"TracerProvider\\\"\\n    assert result[\\\"service_name\\\"] == \\\"langflow\\\"\\n\\n\\ndef test_service_name_env_wins_over_default():\\n    result = run_probe(\\n        {\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\", \\\"OTEL_SERVICE_NAME\\\": \\\"my-langflow\\\"},\\n    )\\n    assert result[\\\"service_name\\\"] == \\\"my-langflow\\\"\\n\\n\\ndef test_resource_attributes_env_wins_over_default():\\n    result = run_probe(\\n        {\\n            \\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\",\\n            \\\"OTEL_RESOURCE_ATTRIBUTES\\\": \\\"service.name=from-attrs,deployment.environment=prod\\\",\\n        },\\n    )\\n    assert result[\\\"service_name\\\"] == \\\"from-attrs\\\"\\n    assert result[\\\"deployment_environment\\\"] == \\\"prod\\\"\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"resource_attributes\\\", \\\"expected\\\"),\\n    [\\n        # A key that merely ends in service.name must not be mistaken for one.\\n        (\\\"k8s.service.name=checkout\\\", \\\"langflow\\\"),\\n        (\\\"app.service.name=foo,deployment.environment=prod\\\", \\\"langflow\\\"),\\n        # Spaces around the = are legal and the SDK strips them.\\n        (\\\"service.name = spaced\\\", \\\"spaced\\\"),\\n    ],\\n)\\ndef test_service_name_is_not_matched_by_substring(resource_attributes, expected):\\n    result = run_probe(\\n        {\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\", \\\"OTEL_RESOURCE_ATTRIBUTES\\\": resource_attributes},\\n    )\\n    assert result[\\\"service_name\\\"] == expected\\n\\n\\ndef test_empty_service_name_falls_back_to_default():\\n    result = run_probe({\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\", \\\"OTEL_SERVICE_NAME\\\": \\\"\\\"})\\n    assert result[\\\"service_name\\\"] == \\\"langflow\\\"\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"protocol\\\", \\\"expected\\\"),\\n    [\\n        (None, \\\"http\\\"),\\n        (\\\"http/protobuf\\\", \\\"http\\\"),\\n        (\\\"grpc\\\", \\\"grpc\\\"),\\n    ],\\n)\\ndef test_protocol_selects_exporter(protocol, expected):\\n    env = {\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\"}\\n    if protocol:\\n        env[\\\"OTEL_EXPORTER_OTLP_PROTOCOL\\\"] = protocol\\n    result = run_probe(env)\\n    assert len(result[\\\"exporters\\\"]) == 1\\n    assert f\\\".proto.{expected}.\\\" in result[\\\"exporters\\\"][0]\\n\\n\\n@pytest.mark.parametrize(\\\"protocol\\\", [\\\" grpc\\\", \\\"grpc \\\", \\\"GRPC\\\", \\\"http/json\\\", \\\"nonsense\\\"])\\ndef test_unsupported_protocol_falls_back_to_http_without_misrouting(protocol):\\n    \\\"\\\"\\\"A stray space must not silently point an HTTP exporter at a gRPC receiver.\\\"\\\"\\\"\\n    result = run_probe(\\n        {\\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\", \\\"OTEL_EXPORTER_OTLP_PROTOCOL\\\": protocol},\\n    )\\n    expected = \\\"grpc\\\" if protocol.strip() == \\\"grpc\\\" else \\\"http\\\"\\n    assert f\\\".proto.{expected}.\\\" in result[\\\"exporters\\\"][0]\\n\\n\\ndef test_traces_exporter_none_disables_export():\\n    \\\"\\\"\\\"Operators disable traces this way when a shared config injects the endpoint.\\\"\\\"\\\"\\n    result = run_probe(\\n        {\\\"OTEL_EXPORTER_OTLP_ENDPOI";
